export enum GameState {
  MENU,
  PLAYING,
  GAME_OVER,
  VICTORY_ANIMATION
}

export type GameMode = 'PVE' | 'PVP';

export interface Vector {
  x: number;
  y: number;
}

export type WeaponType = 'pistol' | 'bomb' | 'stick' | 'sword' | 'blade' | 'atom_bomb' | 'missile' | 'dragon';

export interface Platform {
  x: number;
  y: number;
  width: number;
  height: number;
}

export interface Entity {
  id: string;
  pos: Vector;
  vel: Vector;
  width: number;
  height: number;
  color: string;
  isGrounded: boolean;
  isCrouching: boolean;
  health: number;
  maxHealth: number;
  isDead: boolean;
  facingRight: boolean;
  attackCooldown: number;
  isAttacking: boolean;
  attackFrame: number;
  type: 'player'; 
  playerIndex: number; 
  isWinner?: boolean;
  isLoser?: boolean;
  heldWeapon?: WeaponType | null;
  ammo: number; // 弹药量 或 近战武器耐久度
  weaponDuration: number; // 新增：武器剩余存在时间 (帧)
  stunFrames: number; // 受击硬直/击飞状态
}

export interface FallingItem {
  id: string;
  type: WeaponType;
  pos: Vector;
  vel: Vector;
  width: number;
  height: number;
  onGround: boolean;
}

export interface Projectile {
  id: string;
  type: WeaponType;
  pos: Vector;
  vel: Vector;
  ownerId: string;
  width: number;
  height: number;
  active: boolean;
  targetId?: string; // 追踪目标ID

  // 神龙特有属性
  dragonState?: 'enter' | 'hunt';
  dragonPathProgress?: number; // 入场动画进度
  dragonSegments?: Vector[]; // 龙身位置数组
  remainingHits?: number; // 剩余攻击次数
  lastHitFrame?: number; // 上次攻击时间
}

export interface Particle {
  id: string;
  pos: Vector;
  vel: Vector;
  life: number;
  maxLife: number;
  color: string;
  size: number;
  gravity?: number; 

  // 新增属性用于高级特效 (蘑菇云等)
  growth?: number; // 尺寸增长速率
  alphaDecay?: number; // 透明度衰减速率 (默认是 life/maxLife，此项可覆盖)
  currentAlpha?: number;
}

export interface GameStats {
  winner: string | null;
  mode: GameMode;
  duration: number;
}

import { GameStats } from "../types";

// 本地解说语料库
const COMMENTARY_DB = {
  short_kill: [
    "裁判还没吹哨就结束了？这也太快了吧！",
    "这就叫降维打击！输家甚至没看清招式。",
    "完全是单方面的碾压，建议输家回去重修《火柴人基本功》。",
    "秒杀！这就是传说中的‘有手就行’吗？",
    "快得像一道闪电！我刚打开水瓶盖，比赛就结束了。"
  ],
  long_fight: [
    "这就是传说中的‘千日战争’吗？两边都累得像狗一样。",
    "史诗级的拉锯战！观众的膀胱都要炸了。",
    "双方都展现了惊人的毅力（和极其刮痧的伤害）。",
    "这场战斗比我奶奶的裹脚布还长，但确实精彩！",
    "互相刮痧了半天，终于分出胜负了，不容易啊！"
  ],
  generic: [
    "精彩的对决！虽然有一方看起来像是在梦游。",
    "这就是格斗的艺术！暴力美学的完美呈现。",
    "胜败乃兵家常事，但这次输得确实有点惨。",
    "赢家风光无限，输家... 建议换个手柄试试？"
  ],
  advice: [
    "建议：下次尝试按攻击键，而不是脸滚键盘。",
    "建议：躲避敌人的攻击通常比用脸接更有用。",
    "建议：虽然火柴人没有脑子，但玩家得有。",
    "建议：实在打不过，可以试试拔对方网线。",
    "建议：多吃点核桃，补脑。"
  ]
};

const getRandom = (arr: string[]) => arr[Math.floor(Math.random() * arr.length)];

export const getTacticalAnalysis = async (stats: GameStats): Promise<string> => {
  // 模拟异步延迟，让UI有一点“正在思考”的感觉，但不需要网络
  await new Promise(resolve => setTimeout(resolve, 600));

  let comment = "";

  // 根据时长选择主评语
  if (stats.duration < 15) {
    comment += getRandom(COMMENTARY_DB.short_kill);
  } else if (stats.duration > 60) {
    comment += getRandom(COMMENTARY_DB.long_fight);
  } else {
    comment += getRandom(COMMENTARY_DB.generic);
  }

  // 加上一句扎心建议
  comment += " " + getRandom(COMMENTARY_DB.advice);

  return comment;
};

import React, { useRef, useEffect, useCallback } from 'react';
import { GameState, Entity, Vector, Particle, GameStats, GameMode, FallingItem, Projectile, WeaponType, Platform } from '../types';
import { playJumpSound, playAttackSound, playHitSound, playShootSound, playExplodeSound, playDragonRoar } from '../services/audioService';

interface GameCanvasProps {
  gameState: GameState;
  setGameState: (state: GameState) => void;
  setStats: React.Dispatch<React.SetStateAction<GameStats>>;
  setPlayers: (players: Entity[]) => void;
  gameMode: GameMode;
}

// === 物理参数 ===
const GRAVITY = 0.6; 
const FRICTION = 0.85; 
const MOVE_SPEED = 1.2; 
const JUMP_FORCE = -16; 
const GROUND_Y = 600;
const ATTACK_COOLDOWN = 30; 
const ATTACK_RANGE = 100;
const ATTACK_DAMAGE = 8;

// === 武器生成配置 ===
const MAX_WEAPONS_PER_GAME = 6; 
const WEAPON_SPAWN_INTERVAL = 900; 
const WEAPON_LIFETIME = 15 * 60; 

// === 关卡设计 ===
const PLATFORMS: Platform[] = [
    { x: 300, y: 450, width: 200, height: 20 },
    { x: 800, y: 450, width: 200, height: 20 },
    { x: 500, y: 250, width: 300, height: 20 } 
];

const GameCanvas: React.FC<GameCanvasProps> = ({ gameState, setGameState, setStats, setPlayers, gameMode }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();
  const frameRef = useRef<number>(0);

  const entitiesRef = useRef<Entity[]>([]);
  const particlesRef = useRef<Particle[]>([]);
  const fallingItemsRef = useRef<FallingItem[]>([]);
  const projectilesRef = useRef<Projectile[]>([]);

  // 武器生成控制
  const spawnedWeaponCountRef = useRef<number>(0); 
  const atomBombIndexRef = useRef<number>(-1); 
  const missileIndexRef = useRef<number>(-1); 
  const dragonIndexRef = useRef<number>(-1); 

  const keysRef = useRef<Set<string>>(new Set());
  const statsRef = useRef<GameStats>({ winner: null, mode: gameMode, duration: 0 });
  const shakeRef = useRef<number>(0);
  const flashRef = useRef<number>(0); 

  // 初始化对决
  const initGame = useCallback(() => {
    const newEntities: Entity[] = [];

    // P1 (左侧)
    newEntities.push({
      id: 'p1', type: 'player', playerIndex: 0,
      pos: { x: 100, y: 100 }, vel: { x: 0, y: 0 }, 
      width: 40, height: 70, color: '#3b82f6', 
      isGrounded: false, isCrouching: false, health: 100, maxHealth: 100, isDead: false,
      facingRight: true, attackCooldown: 0, isAttacking: false, attackFrame: 0,
      heldWeapon: null, ammo: 0, weaponDuration: 0, stunFrames: 0
    });

    // P2/CPU (右侧)
    newEntities.push({
      id: 'p2', type: 'player', playerIndex: 1,
      pos: { x: window.innerWidth - 100, y: 100 }, vel: { x: 0, y: 0 },
      width: 40, height: 70, color: '#facc15',
      isGrounded: false, isCrouching: false, health: 100, maxHealth: 100, isDead: false,
      facingRight: false, attackCooldown: 0, isAttacking: false, attackFrame: 0,
      heldWeapon: null, ammo: 0, weaponDuration: 0, stunFrames: 0
    });

    entitiesRef.current = newEntities;
    particlesRef.current = [];
    fallingItemsRef.current = [];
    projectilesRef.current = [];
    spawnedWeaponCountRef.current = 0; 

    const indices = Array.from({length: MAX_WEAPONS_PER_GAME}, (_, i) => i);
    for (let i = indices.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [indices[i], indices[j]] = [indices[j], indices[i]];
    }

    atomBombIndexRef.current = indices[0];
    missileIndexRef.current = indices[1];
    dragonIndexRef.current = indices[2]; 

    statsRef.current = { winner: null, mode: gameMode, duration: 0 };
    frameRef.current = 0;
    shakeRef.current = 0;
    flashRef.current = 0;

    setStats(statsRef.current);
    setPlayers([...entitiesRef.current]);
  }, [gameMode, setStats, setPlayers]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        if (e.repeat) return;
        keysRef.current.add(e.code);
        if (e.code === 'KeyR' && gameState === GameState.GAME_OVER) {
             setGameState(GameState.PLAYING);
        }
    };
    const handleKeyUp = (e: KeyboardEvent) => keysRef.current.delete(e.code);
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, [gameState, setGameState]);

  useEffect(() => {
    if (gameState === GameState.PLAYING) {
      initGame();
    }
  }, [gameState, initGame]);

  const spawnParticles = (x: number, y: number, color: string, count: number, speed = 8, lifeMultiplier = 1) => {
      for(let i=0; i<count; i++) {
          particlesRef.current.push({
              id: Math.random().toString(),
              pos: {x, y},
              vel: { x: (Math.random() - 0.5) * speed, y: (Math.random() - 0.5) * speed },
              life: (20 + Math.random() * 20) * lifeMultiplier,
              maxLife: 40 * lifeMultiplier,
              color: color,
              size: Math.random() * 6 + 3,
              gravity: 0.5 
          });
      }
  };

  const spawnMushroomCloud = (x: number, y: number) => {
    // 1. 蘑菇柄 (上升的烟柱)
    for (let i = 0; i < 20; i++) {
      particlesRef.current.push({
        id: Math.random().toString(),
        pos: { x: x + (Math.random()-0.5)*20, y: y },
        vel: { x: (Math.random()-0.5) * 1, y: -2 - Math.random() * 3 },
        life: 180,
        maxLife: 180,
        color: i % 2 === 0 ? '#555' : '#333',
        size: 15 + Math.random() * 10,
        gravity: -0.05, // 轻微上升
        growth: 0.3, // 膨胀
        alphaDecay: 0.005,
        currentAlpha: 0.8
      });
    }

    // 2. 蘑菇盖 (顶部扩散)
    for (let i = 0; i < 40; i++) {
      const angle = (Math.PI / 40) * i * 2; // 360度
      const speed = 2 + Math.random() * 3;
      particlesRef.current.push({
        id: Math.random().toString(),
        pos: { x: x, y: y - 80 },
        vel: { x: Math.cos(angle) * speed, y: Math.sin(angle) * speed * 0.5 - 1 },
        life: 200,
        maxLife: 200,
        color: Math.random() > 0.5 ? '#ff4500' : '#ff8800', // 橙红火光
        size: 20 + Math.random() * 10,
        gravity: -0.02,
        growth: 0.5, // 快速膨胀
        alphaDecay: 0.008,
        currentAlpha: 0.9
      });
    }

    // 3. 底部冲击波 (贴地尘土)
    for (let i = 0; i < 30; i++) {
        const dir = i % 2 === 0 ? 1 : -1;
        particlesRef.current.push({
            id: Math.random().toString(),
            pos: { x: x, y: y },
            vel: { x: dir * (5 + Math.random()*10), y: -1 },
            life: 100, maxLife: 100,
            color: '#777',
            size: 10,
            gravity: 0,
            growth: 0.8,
            alphaDecay: 0.02,
            currentAlpha: 0.6
        });
    }
  };

  const spawnConfetti = (width: number) => {
      const colors = ['#FFD700', '#FF6347', '#00BFFF', '#32CD32', '#FF69B4', '#FFFFFF'];
      const x = Math.random() * width;
      const y = -10; 
      const color = colors[Math.floor(Math.random() * colors.length)];
      particlesRef.current.push({
          id: Math.random().toString(),
          pos: { x, y },
          vel: { x: (Math.random() - 0.5) * 2, y: Math.random() * 2 + 1 },
          life: 200, maxLife: 200, color, size: Math.random() * 4 + 3, gravity: 0.02 
      });
  };

  const spawnFallingItem = (canvasWidth: number) => {
      let type: WeaponType;

      const count = spawnedWeaponCountRef.current;

      if (count === atomBombIndexRef.current) {
          type = 'atom_bomb';
      } else if (count === missileIndexRef.current) {
          type = 'missile';
      } else if (count === dragonIndexRef.current) {
          type = 'dragon';
      } else {
          const normalPool: WeaponType[] = ['pistol', 'bomb', 'stick', 'sword', 'blade'];
          type = normalPool[Math.floor(Math.random() * normalPool.length)];
      }

      fallingItemsRef.current.push({
          id: Math.random().toString() + "_" + Date.now(),
          type,
          pos: { x: 100 + Math.random() * (canvasWidth - 200), y: -50 },
          vel: { x: (Math.random() - 0.5) * 2, y: 2 },
          width: 30, height: 30,
          onGround: false
      });
      spawnedWeaponCountRef.current++;
  };

  const update = () => {
    if (gameState !== GameState.PLAYING && gameState !== GameState.VICTORY_ANIMATION) return;
    const canvas = canvasRef.current;
    if (!canvas) return;

    frameRef.current++;
    if (shakeRef.current > 0) shakeRef.current--;
    if (flashRef.current > 0) flashRef.current -= 0.02; 
    if (gameState === GameState.PLAYING) statsRef.current.duration += 1/60;

    const triggerWin = (winnerId: string) => {
        if (statsRef.current.winner) return;
        const winner = entitiesRef.current.find(e => e.id === winnerId);
        if (winner) winner.isWinner = true;
        statsRef.current.winner = winnerId === 'p1' ? 'P1' : 'P2';
        setGameState(GameState.VICTORY_ANIMATION);
        setTimeout(() => setGameState(GameState.GAME_OVER), 4000);
    };

    // === 0. 掉落物生成 ===
    if (gameState === GameState.PLAYING && 
        spawnedWeaponCountRef.current < MAX_WEAPONS_PER_GAME && 
        frameRef.current > 60 && 
        frameRef.current % WEAPON_SPAWN_INTERVAL === 0) {
        spawnFallingItem(canvas.width);
    }

    // === 1. 掉落物逻辑 ===
    fallingItemsRef.current.forEach(item => {
        item.vel.y += 0.2; 
        if (item.vel.y > 8) item.vel.y = 8;

        const prevY = item.pos.y;
        item.pos.x += item.vel.x;
        item.pos.y += item.vel.y;

        if (item.pos.y >= GROUND_Y - item.height) {
            item.pos.y = GROUND_Y - item.height;
            item.onGround = true;
            item.vel.y = -item.vel.y * 0.5;
            item.vel.x *= 0.8;
        }

        if (item.vel.y > 0) {
            PLATFORMS.forEach(plat => {
                if (item.pos.x + item.width > plat.x && item.pos.x < plat.x + plat.width) {
                    if (prevY + item.height <= plat.y && item.pos.y + item.height >= plat.y) {
                        item.pos.y = plat.y - item.height;
                        item.onGround = true;
                        item.vel.y = -item.vel.y * 0.5;
                        item.vel.x *= 0.8;
                    }
                }
            });
        }
    });

    // === 2. 投射物逻辑 (子弹、炸弹、导弹、神龙) ===
    projectilesRef.current.forEach(proj => {
        if (!proj.active) return;

        // --- 神龙逻辑 (优化动作) ---
        if (proj.type === 'dragon') {
            const dragonSegmentsCount = 20; // 增加段数，更流畅
            if (!proj.dragonSegments || proj.dragonSegments.length === 0) {
                proj.dragonSegments = Array.from({ length: dragonSegmentsCount }, () => ({ ...proj.pos }));
            }

            if (proj.dragonState === 'enter') {
                if (!proj.dragonPathProgress) proj.dragonPathProgress = 0;
                proj.dragonPathProgress += 0.02;

                shakeRef.current = 8;
                if (Math.random() < 0.1) playExplodeSound();

                const w = canvas.width;
                const h = canvas.height;
                const t = proj.dragonPathProgress * Math.PI * 2;

                // 更复杂的入场轨迹
                const targetX = w/2 + (w/2 - 50) * Math.cos(t) * Math.sin(t*0.5);
                const targetY = h/3 + (h/4) * Math.sin(2*t);

                proj.vel.x = (targetX - proj.pos.x) * 0.2;
                proj.vel.y = (targetY - proj.pos.y) * 0.2;
                proj.pos.x += proj.vel.x;
                proj.pos.y += proj.vel.y;

                if (proj.dragonPathProgress >= 1.5) {
                    proj.dragonState = 'hunt';
                    shakeRef.current = 0;
                }
            } else if (proj.dragonState === 'hunt') {
                const target = entitiesRef.current.find(e => e.id !== proj.ownerId && !e.isDead);
                if (target) {
                    const dx = target.pos.x - proj.pos.x;
                    const dy = (target.pos.y - 40) - proj.pos.y;
                    const dist = Math.sqrt(dx*dx + dy*dy);

                    const speed = 7; // 略微提速
                    // 增加一点惯性，避免转弯太生硬
                    proj.vel.x = (proj.vel.x * 20 + (dx / dist) * speed) / 21;
                    proj.vel.y = (proj.vel.y * 20 + (dy / dist) * speed) / 21;

                    proj.pos.x += proj.vel.x;
                    proj.pos.y += proj.vel.y;

                    if (dist < 50) {
                        const now = frameRef.current;
                        if (!proj.lastHitFrame || now - proj.lastHitFrame > 30) {
                            proj.lastHitFrame = now;
                            if (proj.remainingHits && proj.remainingHits > 0) {
                                proj.remainingHits--;

                                target.health -= 5;
                                target.stunFrames = 20;
                                target.vel.x = (Math.random()-0.5) * 30;
                                target.vel.y = -15;

                                playHitSound();
                                spawnParticles(target.pos.x, target.pos.y, '#FFD700', 20, 8);
                                shakeRef.current = 15;

                                if (target.health <= 0) {
                                    target.health = 0;
                                    target.isDead = true;
                                    target.isLoser = true;
                                    triggerWin(proj.ownerId);
                                }

                                if (proj.remainingHits <= 0) {
                                    proj.active = false;
                                    // 神龙离去特效
                                    spawnParticles(proj.pos.x, proj.pos.y, '#FFD700', 80, 15);
                                }
                            }
                        }
                    }
                } else {
                    proj.vel.y -= 0.5;
                    proj.pos.x += Math.sin(frameRef.current * 0.1) * 5;
                    proj.pos.y += proj.vel.y;
                    if (proj.pos.y < -300) proj.active = false;
                }
            }

            if (proj.dragonSegments && proj.dragonSegments.length > 0) {
                proj.dragonSegments[0] = { ...proj.pos };
                for (let i = 1; i < proj.dragonSegments.length; i++) {
                    const current = proj.dragonSegments[i];
                    const prev = proj.dragonSegments[i-1];
                    const dx = prev.x - current.x;
                    const dy = prev.y - current.y;
                    const d = Math.sqrt(dx*dx + dy*dy);
                    const spacing = 18; 

                    if (d > spacing) {
                        const ratio = (d - spacing) / d;
                        current.x += dx * ratio;
                        current.y += dy * ratio;
                    }
                }
            }
            return; 
        }

        // --- 巡航导弹逻辑 (东风) ---
        if (proj.type === 'missile') {
            if (frameRef.current % 2 === 0) {
                // 浓烟尾迹
                particlesRef.current.push({
                    id: Math.random().toString(),
                    pos: { x: proj.pos.x, y: proj.pos.y },
                    vel: { x: -proj.vel.x * 0.1, y: -proj.vel.y * 0.1 }, // 惯性残留
                    life: 40, maxLife: 40, color: '#aaa', size: 6, gravity: 0, growth: 0.2, alphaDecay: 0.05
                });
                // 火焰中心
                particlesRef.current.push({
                    id: Math.random().toString(),
                    pos: { x: proj.pos.x, y: proj.pos.y },
                    vel: { x: -proj.vel.x * 0.5, y: -proj.vel.y * 0.5 },
                    life: 10, maxLife: 10, color: '#ff5500', size: 4, gravity: 0
                });
            }

            const target = entitiesRef.current.find(e => e.id !== proj.ownerId && !e.isDead);
            if (target) {
                const targetX = target.pos.x;
                const targetY = target.pos.y - 35; 
                const dx = targetX - proj.pos.x;
                const dy = targetY - proj.pos.y;
                const dist = Math.sqrt(dx*dx + dy*dy);

                if (dist > 10) {
                    const speed = 8; // 导弹速度
                    // 增加追踪惯性
                    proj.vel.x = (proj.vel.x * 30 + (dx / dist) * speed) / 31;
                    proj.vel.y = (proj.vel.y * 30 + (dy / dist) * speed) / 31;
                }
            }
        }

        proj.pos.x += proj.vel.x;
        proj.pos.y += proj.vel.y;

        // --- 炸弹/原子弹落地 ---
        if (proj.type === 'bomb' || proj.type === 'atom_bomb') {
            const isNuke = proj.type === 'atom_bomb';
            proj.vel.y += GRAVITY; 
            let hitGround = false;
             if (proj.pos.y >= GROUND_Y) { hitGround = true; }
             else if (proj.vel.y > 0) {
                 PLATFORMS.forEach(plat => {
                     if (proj.pos.x > plat.x && proj.pos.x < plat.x + plat.width && 
                         proj.pos.y >= plat.y && proj.pos.y <= plat.y + 20) {
                         hitGround = true;
                     }
                 });
             }

            if (hitGround) {
                proj.active = false;

                if (isNuke) {
                    // === 核爆逻辑升级 ===
                    shakeRef.current = 120; 
                    flashRef.current = 1.0; 
                    playExplodeSound();

                    // 生成蘑菇云
                    spawnMushroomCloud(proj.pos.x, proj.pos.y - 10);

                    // 冲击波伤害范围极大
                    entitiesRef.current.forEach(target => {
                         if (!target.isDead) {
                             target.health = 0;
                             target.isDead = true;
                             target.isLoser = true;
                             // 被吹飞
                             const dir = target.pos.x - proj.pos.x > 0 ? 1 : -1;
                             target.vel.x = dir * 60;
                             target.vel.y = -60;

                             if (target.id !== proj.ownerId) {
                                 const winner = entitiesRef.current.find(e => e.id === proj.ownerId);
                                 if (winner) triggerWin(winner.id);
                             } else {
                                 const enemy = entitiesRef.current.find(e => e.id !== proj.ownerId);
                                 if (enemy) triggerWin(enemy.id);
                             }
                         }
                    });

                } else {
                    shakeRef.current = 25; 
                    playExplodeSound();
                    spawnParticles(proj.pos.x, proj.pos.y, '#ff4500', 40, 15, 2); 

                    entitiesRef.current.forEach(target => {
                        if (!target.isDead) {
                            const dist = Math.sqrt(Math.pow(target.pos.x - proj.pos.x, 2) + Math.pow(target.pos.y - proj.pos.y, 2));
                            if (dist < 180) {
                                target.health -= 25; 
                                if (target.health <= 0) { target.health = 0; target.isDead = true; target.isLoser = true; }

                                const angle = Math.atan2(target.pos.y - proj.pos.y, target.pos.x - proj.pos.x);
                                target.vel.x = Math.cos(angle) * 30;
                                target.vel.y = Math.sin(angle) * 30;
                                target.stunFrames = 30;

                                if (target.isDead) {
                                    const winner = entitiesRef.current.find(e => e.id === proj.ownerId);
                                    if (winner) triggerWin(winner.id);
                                }
                            }
                        }
                    });
                }
            }
        } else {
            // === 碰撞逻辑 (子弹 & 导弹) ===
            const isMissile = proj.type === 'missile';
            if (proj.pos.x < 0 || proj.pos.x > canvas.width || proj.pos.y > canvas.height + 100 || proj.pos.y < -200) proj.active = false;

            entitiesRef.current.forEach(target => {
                if (target.id !== proj.ownerId && !target.isDead && proj.active) {
                    const hitDist = isMissile ? 50 : 30; 
                    if (Math.abs(proj.pos.x - target.pos.x) < hitDist &&
                        proj.pos.y > target.pos.y - 75 && proj.pos.y < target.pos.y + 10) {

                        proj.active = false;
                        const damage = isMissile ? 35 : 15; // 导弹伤害增加
                        target.health -= damage; 
                        target.stunFrames = isMissile ? 40 : 10;
                        shakeRef.current = isMissile ? 25 : 5;

                        isMissile ? playExplodeSound() : playHitSound();

                        // 导弹击中特效
                        if (isMissile) {
                             spawnParticles(target.pos.x, target.pos.y - 35, '#ff5500', 40, 10);
                             spawnParticles(target.pos.x, target.pos.y - 35, '#555', 20, 5);
                        } else {
                             spawnParticles(target.pos.x, target.pos.y - 35, '#ff0000', 10, 8);
                        }

                        target.vel.x += proj.vel.x * (isMissile ? 1.2 : 0.3); 
                        target.vel.y -= isMissile ? 15 : 5;

                        if (target.health <= 0) {
                            target.health = 0; 
                            target.isDead = true;
                            target.isLoser = true;
                            target.vel.x = proj.vel.x * 0.8;
                            const winner = entitiesRef.current.find(e => e.id === proj.ownerId);
                            if (winner) triggerWin(winner.id);
                        }
                    }
                }
            });
        }
    });
    projectilesRef.current = projectilesRef.current.filter(p => p.active);

    // === 3. 实体更新 ===
    entitiesRef.current.forEach(entity => {
      // 检查武器是否过期
      if (entity.heldWeapon) {
          entity.weaponDuration--;
          if (entity.weaponDuration <= 0) {
              entity.heldWeapon = null;
              spawnParticles(entity.pos.x, entity.pos.y - 40, '#888', 5, 5); // 消失特效
          }
      }

      if (gameState === GameState.VICTORY_ANIMATION && entity.isWinner) {
          entity.isAttacking = false; entity.attackFrame = 0; entity.isCrouching = false;
          const targetX = canvas.width / 2;
          const targetY = canvas.height / 3;
          entity.pos.x += (targetX - entity.pos.x) * 0.05;
          entity.pos.y += (targetY - entity.pos.y) * 0.05;
          entity.pos.y += Math.sin(frameRef.current * 0.08) * 0.8;
          entity.vel.x = 0; entity.vel.y = 0;
          if (frameRef.current % 3 === 0) spawnConfetti(canvas.width);
          return;
      }

      // 拾取武器
      if (!entity.isDead) {
          const canPickUp = !entity.heldWeapon || entity.ammo <= 0;

          if (canPickUp) {
            const itemIndex = fallingItemsRef.current.findIndex(item => {
                const dx = Math.abs(entity.pos.x - (item.pos.x + item.width/2));
                const dy = Math.abs((entity.pos.y - 35) - (item.pos.y + item.height/2));
                return dx < 50 && dy < 60;
            });

            if (itemIndex !== -1) {
                const item = fallingItemsRef.current[itemIndex];
                entity.heldWeapon = item.type;
                entity.weaponDuration = WEAPON_LIFETIME; 
                switch(item.type) {
                    case 'pistol': entity.ammo = 6; break;
                    case 'bomb': entity.ammo = 3; break;
                    case 'stick': entity.ammo = 10; break; 
                    case 'sword': entity.ammo = 8; break;
                    case 'blade': entity.ammo = 5; break; 
                    case 'atom_bomb': entity.ammo = 1; break; 
                    case 'missile': entity.ammo = 2; break; // 导弹只有2发
                    case 'dragon': entity.ammo = 1; break; 
                }
                fallingItemsRef.current.splice(itemIndex, 1);
                playJumpSound();
                spawnParticles(entity.pos.x, entity.pos.y - 30, '#fff', 5, 5);
            }
          }
      }

      // 物理引擎
      const prevY = entity.pos.y;
      entity.vel.y += GRAVITY;

      if (!entity.isLoser && entity.stunFrames > 0) {
           entity.stunFrames--; 
           entity.vel.x *= 0.95; 
      } else if (!entity.isLoser) {
          const currentFriction = entity.isCrouching && entity.isGrounded ? 0.4 : FRICTION;
          entity.vel.x *= currentFriction;
      } else {
          entity.vel.x *= 0.99; 
      }

      entity.pos.x += entity.vel.x;
      entity.pos.y += entity.vel.y;

      // 碰撞检测
      entity.isGrounded = false;
      if (entity.pos.y >= GROUND_Y) {
          if (!entity.isLoser) {
            entity.pos.y = GROUND_Y;
            entity.vel.y = 0;
            entity.isGrounded = true;
          }
      }
      if (entity.vel.y >= 0 && !entity.isDead) {
          PLATFORMS.forEach(plat => {
              if (entity.pos.x > plat.x - 10 && entity.pos.x < plat.x + plat.width + 10) {
                  if (prevY <= plat.y && entity.pos.y >= plat.y) {
                      entity.pos.y = plat.y;
                      entity.vel.y = 0;
                      entity.isGrounded = true;
                  }
              }
          });
      }

      if (!entity.isLoser) {
        if (entity.pos.x < 10) { entity.pos.x = 10; entity.vel.x *= -0.5; }
        if (entity.pos.x > canvas.width - 10) { entity.pos.x = canvas.width - 10; entity.vel.x *= -0.5; }
      }

      if (gameState === GameState.VICTORY_ANIMATION || entity.isDead || entity.stunFrames > 0) return;

      if (entity.attackCooldown > 0) entity.attackCooldown--;
      if (entity.isAttacking) {
          entity.attackFrame++;
          if (entity.attackFrame > 15) { 
              entity.isAttacking = false;
              entity.attackFrame = 0;
          }
      }

      let moveLeft = false, moveRight = false, jump = false, crouch = false, attack = false;

      // Input P1
      if (entity.playerIndex === 0) {
        if (keysRef.current.has('KeyA')) moveLeft = true;
        if (keysRef.current.has('KeyD')) moveRight = true;
        if (keysRef.current.has('KeyW')) jump = true;
        if (keysRef.current.has('KeyS')) crouch = true;
        if (keysRef.current.has('Space')) attack = true;
      }

      // Input P2 / AI
      if (entity.playerIndex === 1) {
          if (gameMode === 'PVP') {
            if (keysRef.current.has('ArrowLeft')) moveLeft = true;
            if (keysRef.current.has('ArrowRight')) moveRight = true;
            if (keysRef.current.has('ArrowUp')) jump = true;
            if (keysRef.current.has('ArrowDown')) crouch = true;
            if (keysRef.current.has('Enter')) attack = true;
          } else {
            // AI Logic
            const p1 = entitiesRef.current.find(e => e.playerIndex === 0);
            if (p1 && !p1.isDead) {
                let targetX = p1.pos.x;
                let targetY = p1.pos.y;

                if (!entity.heldWeapon && fallingItemsRef.current.length > 0) {
                    let minDist = 9999;
                    fallingItemsRef.current.forEach(item => {
                        const d = Math.abs(item.pos.x - entity.pos.x) + Math.abs(item.pos.y - entity.pos.y);
                        if (d < minDist) {
                            minDist = d;
                            targetX = item.pos.x;
                            targetY = item.pos.y;
                        }
                    });
                }

                const distX = targetX - entity.pos.x;
                const distY = targetY - entity.pos.y; 

                if (Math.abs(distX) > 40) {
                    distX > 0 ? moveRight = true : moveLeft = true;
                } else if (!entity.heldWeapon && Math.abs(distX) < 20) {
                     distX > 0 ? moveLeft = true : moveRight = true;
                }

                if (entity.isGrounded) {
                     if (distY < -100 || (Math.random() < 0.02)) {
                         jump = true;
                     }
                }

                const absDistX = Math.abs(p1.pos.x - entity.pos.x);
                entity.facingRight = (p1.pos.x - entity.pos.x) > 0;

                // AI 攻击逻辑
                let attackRange = ATTACK_RANGE;
                if (entity.heldWeapon === 'stick') attackRange = 200;
                if (entity.heldWeapon === 'pistol') attackRange = 600;
                if (entity.heldWeapon === 'atom_bomb') attackRange = 300; 
                if (entity.heldWeapon === 'missile') attackRange = 700; 
                if (entity.heldWeapon === 'dragon') attackRange = 400; 

                if (absDistX < attackRange && Math.abs(p1.pos.y - entity.pos.y) < 100) {
                    if (entity.attackCooldown === 0 && Math.random() < 0.05) attack = true;
                }
            }
          }
      }

      entity.isCrouching = crouch && entity.isGrounded;
      if (!entity.isCrouching) {
          if (moveLeft) { entity.vel.x -= MOVE_SPEED; entity.facingRight = false; }
          if (moveRight) { entity.vel.x += MOVE_SPEED; entity.facingRight = true; }
      }
      if (jump && entity.isGrounded && !entity.isCrouching) {
          entity.vel.y = JUMP_FORCE;
          playJumpSound();
      }

      // === 攻击处理 ===
      if (attack && entity.attackCooldown === 0) {
          entity.attackCooldown = ATTACK_COOLDOWN;
          entity.isAttacking = true;
          entity.attackFrame = 5;

          if (entity.heldWeapon === 'pistol') {
              playShootSound();
              entity.vel.x += entity.facingRight ? -8 : 8;
              entity.vel.y -= 2;

              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'pistol',
                  pos: { x: entity.pos.x + (entity.facingRight ? 40 : -40), y: entity.pos.y - 45 },
                  vel: { x: entity.facingRight ? 20 : -20, y: (Math.random()-0.5) * 2 }, 
                  ownerId: entity.id,
                  width: 12, height: 4, active: true
              });
              entity.ammo--;
          } else if (entity.heldWeapon === 'bomb') {
              entity.vel.x += entity.facingRight ? -2 : 2;
              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'bomb',
                  pos: { x: entity.pos.x, y: entity.pos.y - 60 },
                  vel: { x: entity.facingRight ? 12 : -12, y: -12 },
                  ownerId: entity.id,
                  width: 20, height: 20, active: true
              });
              entity.ammo--;
          } else if (entity.heldWeapon === 'atom_bomb') {
              entity.vel.x += entity.facingRight ? -4 : 4;
              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'atom_bomb',
                  pos: { x: entity.pos.x, y: entity.pos.y - 70 },
                  vel: { x: entity.facingRight ? 8 : -8, y: -10 },
                  ownerId: entity.id,
                  width: 30, height: 40, active: true
              });
              entity.ammo--; 
          } else if (entity.heldWeapon === 'missile') {
              playShootSound(); 
              entity.vel.x += entity.facingRight ? -10 : 10; 
              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'missile',
                  pos: { x: entity.pos.x + (entity.facingRight ? 50 : -50), y: entity.pos.y - 50 },
                  vel: { x: entity.facingRight ? 10 : -10, y: -5 }, 
                  ownerId: entity.id,
                  width: 20, height: 8, active: true
              });
              entity.ammo--; 
          } else if (entity.heldWeapon === 'dragon') {
              playDragonRoar();
              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'dragon',
                  pos: { x: entity.pos.x, y: entity.pos.y - 100 },
                  vel: { x: 0, y: 0 },
                  ownerId: entity.id,
                  width: 40, height: 40, active: true,
                  dragonState: 'enter', 
                  remainingHits: 5,
                  dragonPathProgress: 0,
                  dragonSegments: undefined
              });
              entity.ammo--;
          } else {
              // == 近战武器 ==
              playAttackSound();

              let range = ATTACK_RANGE;
              let dmg = ATTACK_DAMAGE;
              let knockbackX = 15;
              let knockbackY = -8;
              let selfPush = 10;
              let hitEffectSize = 12;

              if (entity.heldWeapon === 'stick') {
                  range = 220; dmg = 12; knockbackX = 20; selfPush = 5; hitEffectSize = 15;
              } else if (entity.heldWeapon === 'sword') {
                  range = 140; dmg = 15; knockbackX = 12; selfPush = 12; entity.attackCooldown = 20; 
              } else if (entity.heldWeapon === 'blade') {
                  range = 160; dmg = 25; knockbackX = 25; knockbackY = -12; selfPush = 2; entity.attackCooldown = 50; 
              }

              entity.vel.x = entity.facingRight ? selfPush : -selfPush;

              const hitX = entity.facingRight ? entity.pos.x + range/2 : entity.pos.x - range/2;
              const hitY = entity.isCrouching ? entity.pos.y - 20 : entity.pos.y - 45;

              let hitSomething = false;

              entitiesRef.current.forEach(target => {
                  if (target !== entity && !target.isDead) {
                      const dy = (target.pos.y - 35) - hitY;
                      if (Math.abs(target.pos.x - entity.pos.x) < range && Math.abs(dy) < 60 && 
                          ((entity.facingRight && target.pos.x > entity.pos.x) || (!entity.facingRight && target.pos.x < entity.pos.x))) {

                          if (!entity.isCrouching && target.isCrouching) {
                              spawnParticles(target.pos.x, target.pos.y - 40, '#aaa', 2, 2);
                              return; 
                          }

                          target.health -= dmg;
                          hitSomething = true;

                          target.vel.x = entity.facingRight ? knockbackX : -knockbackX; 
                          target.vel.y = knockbackY; 
                          target.stunFrames = 20; 

                          shakeRef.current = Math.floor(dmg / 2);
                          spawnParticles(target.pos.x, target.pos.y - 40, target.color, hitEffectSize, 10);
                          playHitSound();

                          if (target.health <= 0) {
                              target.health = 0;
                              target.isDead = true;
                              target.isLoser = true;
                              target.vel.x = entity.facingRight ? 30 : -30;
                              target.vel.y = -20;
                              triggerWin(entity.id);
                          }
                      }
                  }
              });

              if (hitSomething && entity.heldWeapon) {
                  entity.ammo--;
              }
          }

          // 弹药耗尽检查
          if (entity.heldWeapon && entity.ammo <= 0) {
              entity.heldWeapon = null;
              spawnParticles(entity.pos.x, entity.pos.y - 40, '#888', 5, 5); 
          }
      }
    });

    particlesRef.current.forEach(p => {
        p.pos.x += p.vel.x;
        p.pos.y += p.vel.y;
        p.life--;
        p.vel.y += p.gravity || 0;

        // 生长和衰减
        if (p.growth) p.size += p.growth;
        if (p.alphaDecay !== undefined && p.currentAlpha !== undefined) {
            p.currentAlpha -= p.alphaDecay;
            if (p.currentAlpha < 0) p.currentAlpha = 0;
        }
    });
    particlesRef.current = particlesRef.current.filter(p => p.life > 0 && (p.currentAlpha === undefined || p.currentAlpha > 0));

    setStats({...statsRef.current});
    setPlayers([...entitiesRef.current]);
  };

  const drawBackground = (ctx: CanvasRenderingContext2D, width: number, height: number) => {
      ctx.fillStyle = '#1e1e2e';
      ctx.fillRect(0, 0, width, height);

      ctx.strokeStyle = '#313244';
      ctx.lineWidth = 2;
      const gridSize = 100;
      for (let x = 0; x < width; x += gridSize) {
          ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, height); ctx.stroke();
      }
      for (let y = 0; y < height; y += gridSize) {
          ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(width, y); ctx.stroke();
      }

      ctx.fillStyle = '#45475a';
      ctx.strokeStyle = '#89b4fa';
      ctx.lineWidth = 3;

      PLATFORMS.forEach(plat => {
          ctx.fillRect(plat.x, plat.y, plat.width, plat.height);
          ctx.strokeRect(plat.x, plat.y, plat.width, plat.height);
          ctx.fillStyle = '#181825';
          for(let i=10; i<plat.width; i+=40) {
              ctx.fillRect(plat.x + i, plat.y + 5, 20, 10);
          }
          ctx.fillStyle = '#45475a';
      });

      ctx.fillStyle = '#11111b';
      ctx.fillRect(0, GROUND_Y, width, height - GROUND_Y);
      ctx.strokeStyle = '#a6e3a1';
      ctx.lineWidth = 4;
      ctx.beginPath(); ctx.moveTo(0, GROUND_Y); ctx.lineTo(width, GROUND_Y); ctx.stroke();
  };

  const drawEntity = (ctx: CanvasRenderingContext2D, entity: Entity) => {
      ctx.save();
      ctx.translate(entity.pos.x, entity.pos.y);

      if (entity.isLoser) {
          ctx.rotate(frameRef.current * 0.1 * (entity.vel.x > 0 ? 1 : -1));
          ctx.globalAlpha = 0.8;
      }
      if (!entity.facingRight) ctx.scale(-1, 1);

      const color = entity.isLoser ? '#6c7086' : entity.color;
      ctx.strokeStyle = '#111'; // 黑色轮廓
      ctx.fillStyle = color;

      ctx.lineWidth = 14; 
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';

      let headY = -70; let neckY = -55; let hipY = -30; 
      if (entity.isCrouching) { headY = -45; neckY = -30; hipY = -15; }

      const drawBodyParts = (isOutline: boolean) => {
          ctx.lineWidth = isOutline ? 18 : 10;
          ctx.strokeStyle = isOutline ? '#000' : color;

          // 腿
          ctx.beginPath();
          if (entity.isWinner && gameState === GameState.VICTORY_ANIMATION) {
              ctx.moveTo(0, hipY); ctx.lineTo(-10, hipY + 45); 
              ctx.moveTo(0, hipY); ctx.lineTo(10, hipY + 45);  
          } else if (entity.isCrouching) {
              ctx.moveTo(0, hipY); ctx.lineTo(-20, -5); ctx.lineTo(-10, 0);
              ctx.moveTo(0, hipY); ctx.lineTo(20, -5); ctx.lineTo(10, 0);
          } else if (!entity.isGrounded) { 
              ctx.moveTo(0, hipY); ctx.lineTo(-15, 10); ctx.lineTo(-10, 25);
              ctx.moveTo(0, hipY); ctx.lineTo(20, 5); ctx.lineTo(25, 20);
          } else if (Math.abs(entity.vel.x) > 0.1) { 
              const runCycle = Math.sin(frameRef.current * 0.6);
              ctx.moveTo(0, hipY); ctx.lineTo(-20 * Math.cos(runCycle), 0);
              ctx.moveTo(0, hipY); ctx.lineTo(20 * Math.cos(runCycle), 0);
          } else {
              ctx.moveTo(0, hipY); ctx.lineTo(-12, 0);
              ctx.moveTo(0, hipY); ctx.lineTo(12, 0);
          }
          ctx.stroke();

          // 躯干
          ctx.beginPath(); ctx.moveTo(0, neckY); ctx.lineTo(0, hipY); ctx.stroke();

          // 手臂
          ctx.beginPath();
          if (entity.heldWeapon) {
               // 持武器姿态
               const armAngle = entity.heldWeapon === 'pistol' ? 0 : -0.5;
               ctx.moveTo(0, neckY); ctx.lineTo(-15, neckY + 15);
               ctx.moveTo(0, neckY); ctx.lineTo(30, neckY + (entity.heldWeapon === 'pistol' ? -5 : 5));
          } else if (entity.isAttacking) {
              const punchExtend = 35 + (entity.attackFrame * 2);
              ctx.moveTo(0, neckY); ctx.lineTo(-15, neckY + 15);
              ctx.moveTo(0, neckY); ctx.lineTo(punchExtend, neckY - 10);
          } else {
              ctx.moveTo(0, neckY); ctx.lineTo(20, neckY + 15); 
              ctx.moveTo(0, neckY); ctx.lineTo(-20, neckY + 15); 
          }
          ctx.stroke();
      };

      drawBodyParts(true);  
      drawBodyParts(false); 

      // 头部
      ctx.lineWidth = 4;
      ctx.strokeStyle = '#000';
      ctx.fillStyle = '#fff';
      ctx.beginPath();
      ctx.arc(0, headY, 18, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();

      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.rect(-18, headY - 10, 36, 8);
      ctx.fill();
      if (Math.abs(entity.vel.x) > 1 || entity.vel.y !== 0) {
          ctx.beginPath();
          ctx.moveTo(-18, headY - 6);
          ctx.lineTo(-40 - Math.random()*10, headY - 15);
          ctx.lineTo(-40 - Math.random()*10, headY + 5);
          ctx.fill();
      }

      // === 武器绘制 ===
      if (entity.heldWeapon) {
          ctx.translate(35, neckY); // 手部位置

          if (entity.isAttacking && entity.heldWeapon !== 'pistol' && entity.heldWeapon !== 'bomb' && entity.heldWeapon !== 'atom_bomb' && entity.heldWeapon !== 'missile' && entity.heldWeapon !== 'dragon') {
               const swing = Math.sin(frameRef.current * 0.8) * 1.5;
               ctx.rotate(swing);
          }

          if (entity.heldWeapon === 'pistol') {
              ctx.translate(0, -5);
              ctx.fillStyle = '#333'; ctx.strokeStyle = '#111'; ctx.lineWidth = 2;
              ctx.fillRect(-10, -5, 30, 8); 
              ctx.fillRect(-10, -5, 8, 15);
              ctx.fillStyle = '#0f0';
              for(let i=0; i<entity.ammo; i++) ctx.fillRect(-8 + i*4, -12, 2, 2);

          } else if (entity.heldWeapon === 'bomb') {
              ctx.translate(0, -5);
              ctx.fillStyle = '#222'; ctx.beginPath(); ctx.arc(0, 0, 12, 0, Math.PI*2); ctx.fill();
              ctx.fillStyle = '#f00'; ctx.font = '12px bold'; ctx.fillText('💣', -6, 4);
              ctx.fillStyle = '#fff'; ctx.font = '10px sans-serif'; ctx.fillText(`x${entity.ammo}`, -5, -15);

          } else if (entity.heldWeapon === 'atom_bomb') {
              ctx.translate(0, -5);
              ctx.fillStyle = '#facc15'; ctx.strokeStyle = '#000'; ctx.lineWidth = 2;
              ctx.beginPath(); ctx.ellipse(0, 0, 15, 25, 0, 0, Math.PI*2); ctx.fill(); ctx.stroke();
              ctx.fillStyle = '#000'; 
              ctx.beginPath(); ctx.arc(0, 2, 4, 0, Math.PI*2); ctx.fill();
              ctx.beginPath(); ctx.moveTo(0, 2); ctx.lineTo(-8, -6); ctx.lineTo(8, -6); ctx.fill();

          } else if (entity.heldWeapon === 'missile') {
              // 手持状态下的东风
              ctx.translate(5, -5);
              ctx.scale(0.6, 0.6); // 缩小一点
              ctx.rotate(Math.PI/2); // 竖着拿
              // 弹体
              ctx.fillStyle = '#dfe6e9'; ctx.strokeStyle = '#2d3436'; ctx.lineWidth = 2;
              ctx.fillRect(-8, -30, 16, 60); ctx.strokeRect(-8, -30, 16, 60);
              // 弹头
              ctx.fillStyle = '#d63031'; 
              ctx.beginPath(); ctx.moveTo(-8, -30); ctx.lineTo(8, -30); ctx.lineTo(0, -45); ctx.closePath(); ctx.fill(); ctx.stroke();
              // 尾翼
              ctx.fillStyle = '#636e72';
              ctx.beginPath(); ctx.moveTo(-8, 20); ctx.lineTo(-15, 35); ctx.lineTo(-8, 30); ctx.fill();
              ctx.beginPath(); ctx.moveTo(8, 20); ctx.lineTo(15, 35); ctx.lineTo(8, 30); ctx.fill();

              ctx.restore();
              ctx.fillStyle = '#ff4757'; ctx.font = '10px sans-serif'; ctx.fillText(`🚀${entity.ammo}`, -15, -15);

          } else if (entity.heldWeapon === 'dragon') {
              ctx.translate(0, -5);
              ctx.fillStyle = '#FFD700'; 
              ctx.beginPath(); ctx.arc(0, 0, 10, 0, Math.PI*2); ctx.fill();
              ctx.strokeStyle = '#FFA500'; ctx.lineWidth = 2; ctx.stroke();
              ctx.fillStyle = '#fff'; ctx.font = '12px serif'; ctx.fillText('🐲', -6, 4);
          } else if (entity.heldWeapon === 'stick') {
              ctx.rotate(-Math.PI / 4);
              ctx.fillStyle = '#ffd700'; ctx.strokeStyle = '#d4af37'; ctx.lineWidth = 4;
              const len = 100;
              ctx.fillRect(0, -4, len, 8);
              ctx.fillStyle = '#ff0000'; ctx.fillRect(20, -3, len - 40, 6);
              ctx.fillStyle = '#fff'; ctx.fillRect(0, -10, (entity.ammo/10)*len, 2);

          } else if (entity.heldWeapon === 'sword') {
              ctx.rotate(-Math.PI / 4);
              ctx.fillStyle = '#4a4a4a'; ctx.fillRect(-10, -3, 20, 6);
              ctx.fillStyle = '#ffd700'; ctx.fillRect(10, -10, 5, 20);
              ctx.fillStyle = '#e5e7eb'; ctx.beginPath(); ctx.moveTo(15, -4); ctx.lineTo(70, -4); ctx.lineTo(80, 0); ctx.lineTo(70, 4); ctx.lineTo(15, 4); ctx.fill();
              ctx.fillStyle = '#fff'; ctx.fillRect(15, 0, 50, 1); 

          } else if (entity.heldWeapon === 'blade') {
              ctx.rotate(-Math.PI / 4);
              ctx.fillStyle = '#5c4033'; ctx.fillRect(-20, -4, 40, 8);
              ctx.fillStyle = '#94a3b8';
              ctx.beginPath(); ctx.moveTo(20, -4); ctx.lineTo(80, -20); ctx.lineTo(85, 0); ctx.lineTo(20, 15); ctx.fill();
              ctx.beginPath(); ctx.arc(70, -10, 3, 0, Math.PI*2); ctx.fillStyle = '#000'; ctx.fill();
          }

          if (entity.heldWeapon && entity.heldWeapon !== 'missile') { // 导弹自己有倒计时渲染
              ctx.fillStyle = 'rgba(255,255,255,0.5)';
              ctx.fillRect(-15, -20, 30, 2); 
              const timeLeftPct = entity.weaponDuration / WEAPON_LIFETIME;
              ctx.fillStyle = timeLeftPct < 0.3 ? '#ff0000' : '#00ff00';
              ctx.fillRect(-15, -20, 30 * timeLeftPct, 2);
          }

          ctx.restore();
      }

      ctx.restore();
  };

  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    let shakeX = 0, shakeY = 0;
    if (shakeRef.current > 0) {
        shakeX = (Math.random() - 0.5) * shakeRef.current * 2;
        shakeY = (Math.random() - 0.5) * shakeRef.current * 2;
    }
    ctx.save();
    ctx.translate(shakeX, shakeY);

    drawBackground(ctx, canvas.width, canvas.height);

    // 掉落物
    fallingItemsRef.current.forEach(item => {
        ctx.save();
        ctx.translate(item.pos.x, item.pos.y);

        if (!item.onGround) {
            ctx.strokeStyle = '#fff'; ctx.lineWidth = 2;
            ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(15, -50); ctx.moveTo(30, 0); ctx.lineTo(15, -50); ctx.stroke();
            ctx.fillStyle = '#ff6b6b'; ctx.beginPath(); ctx.arc(15, -50, 25, Math.PI, 0); ctx.fill();
        }

        ctx.shadowBlur = 10; ctx.shadowColor = '#ffd700';
        ctx.fillStyle = '#333'; ctx.fillRect(0, 0, 30, 30);
        ctx.strokeStyle = '#ffd700'; ctx.lineWidth = 3; ctx.strokeRect(0, 0, 30, 30);

        // 显示武器图标
        ctx.font = '20px sans-serif'; ctx.textAlign = 'center'; 
        let icon = '?';
        if (item.type === 'pistol') icon = '🔫';
        else if (item.type === 'bomb') icon = '💣';
        else if (item.type === 'stick') icon = '🥖';
        else if (item.type === 'sword') icon = '🗡️';
        else if (item.type === 'blade') icon = '🔪';
        else if (item.type === 'atom_bomb') icon = '☢️';
        else if (item.type === 'missile') icon = '🚀';
        else if (item.type === 'dragon') icon = '🐲';

        ctx.fillText(icon, 15, 22);
        ctx.restore();
    });

    // 投射物
    projectilesRef.current.forEach(p => {
        ctx.save();

        if (p.type === 'dragon') {
            // === 神龙重绘：不再是虫子 ===
            if (p.dragonSegments && p.dragonSegments.length > 0) {
                const totalSegments = p.dragonSegments.length;

                // 1. 绘制龙身 (带渐变宽度)
                ctx.lineCap = 'round';
                ctx.lineJoin = 'round';

                // 绘制每一段
                for(let i=0; i<totalSegments - 1; i++) {
                     const curr = p.dragonSegments[i];
                     const next = p.dragonSegments[i+1];
                     const progress = i / totalSegments;
                     const width = 24 * (1 - progress * 0.6); // 头粗尾细

                     ctx.lineWidth = width;
                     ctx.strokeStyle = '#d97706'; // 金色轮廓
                     ctx.beginPath(); ctx.moveTo(curr.x, curr.y); ctx.lineTo(next.x, next.y); ctx.stroke();

                     ctx.lineWidth = width - 4;
                     ctx.strokeStyle = '#059669'; // 青色身体
                     ctx.beginPath(); ctx.moveTo(curr.x, curr.y); ctx.lineTo(next.x, next.y); ctx.stroke();

                     // 龙脊
                     if (i % 2 === 0) {
                        ctx.fillStyle = '#fbbf24'; // 亮黄龙脊
                        ctx.beginPath(); ctx.arc(curr.x, curr.y - 5, width/4, 0, Math.PI*2); ctx.fill();
                     }

                     // 龙爪 (每5段一个)
                     if (i > 3 && i < totalSegments - 3 && i % 5 === 0) {
                         const dx = next.x - curr.x;
                         const dy = next.y - curr.y;
                         const angle = Math.atan2(dy, dx);
                         ctx.save();
                         ctx.translate(curr.x, curr.y);
                         ctx.rotate(angle);
                         ctx.fillStyle = '#d97706';
                         // 左右爪
                         ctx.fillRect(0, width/2, 10, 4);
                         ctx.fillRect(0, -width/2 - 4, 10, 4);
                         ctx.restore();
                     }
                }

                // 2. 龙头 (更威武)
                const head = p.dragonSegments[0];
                const neck = p.dragonSegments[1];
                ctx.save();
                ctx.translate(head.x, head.y);
                if (neck) {
                    const angle = Math.atan2(head.y - neck.y, head.x - neck.x);
                    ctx.rotate(angle);
                }

                // 头轮廓
                ctx.fillStyle = '#047857'; // 深青
                ctx.beginPath(); ctx.moveTo(10, 0); ctx.lineTo(-15, -12); ctx.lineTo(-15, 12); ctx.fill();

                // 眼睛
                ctx.fillStyle = '#fbbf24'; // 金眼
                ctx.beginPath(); ctx.arc(0, -6, 5, 0, Math.PI*2); ctx.fill();
                ctx.beginPath(); ctx.arc(0, 6, 5, 0, Math.PI*2); ctx.fill();
                ctx.fillStyle = '#000'; // 瞳孔
                ctx.beginPath(); ctx.arc(1, -6, 2, 0, Math.PI*2); ctx.fill();
                ctx.beginPath(); ctx.arc(1, 6, 2, 0, Math.PI*2); ctx.fill();

                // 龙须
                ctx.strokeStyle = '#fff'; ctx.lineWidth = 2;
                ctx.beginPath(); ctx.moveTo(10, -5); ctx.bezierCurveTo(30, -20, 40, 10, 50, -10); ctx.stroke();
                ctx.beginPath(); ctx.moveTo(10, 5); ctx.bezierCurveTo(30, 20, 40, -10, 50, 10); ctx.stroke();

                // 龙角
                ctx.strokeStyle = '#92400e'; ctx.lineWidth = 4;
                ctx.beginPath(); ctx.moveTo(-5, -10); ctx.lineTo(-20, -25); ctx.stroke();
                ctx.beginPath(); ctx.moveTo(-5, 10); ctx.lineTo(-20, 25); ctx.stroke();

                ctx.restore();
            }
        } else {
            ctx.translate(p.pos.x, p.pos.y);

            if (p.type === 'pistol') {
                ctx.fillStyle = '#fff';
                ctx.shadowBlur = 10; ctx.shadowColor = '#ffff00';
                ctx.fillRect(-6, -2, 12, 4);
            } else if (p.type === 'atom_bomb') {
                ctx.fillStyle = '#facc15'; ctx.strokeStyle = '#000'; ctx.lineWidth = 2;
                ctx.beginPath(); ctx.ellipse(0, 0, 10, 15, p.vel.y * 0.1, 0, Math.PI*2); ctx.fill(); ctx.stroke();
                ctx.fillStyle = '#ff4500';
                ctx.beginPath(); ctx.moveTo(-5, -10); ctx.lineTo(0, -20 - Math.random()*10); ctx.lineTo(5, -10); ctx.fill();
            } else if (p.type === 'missile') {
                // === 东风导弹重绘 ===
                const angle = Math.atan2(p.vel.y, p.vel.x);
                ctx.rotate(angle);

                // 弹体 (白色/橄榄绿)
                ctx.fillStyle = '#dfe6e9'; 
                ctx.strokeStyle = '#2d3436'; ctx.lineWidth = 1;
                // 长圆柱体
                ctx.fillRect(-20, -6, 40, 12); 
                ctx.strokeRect(-20, -6, 40, 12);

                // 弹头 (红色)
                ctx.fillStyle = '#d63031';
                ctx.beginPath();
                ctx.moveTo(20, -6); ctx.lineTo(35, 0); ctx.lineTo(20, 6);
                ctx.fill(); ctx.stroke();

                // 尾翼 (大且明显)
                ctx.fillStyle = '#636e72';
                // 上翼
                ctx.beginPath(); ctx.moveTo(-20, -6); ctx.lineTo(-30, -14); ctx.lineTo(-10, -6); ctx.fill(); ctx.stroke();
                // 下翼
                ctx.beginPath(); ctx.moveTo(-20, 6); ctx.lineTo(-30, 14); ctx.lineTo(-10, 6); ctx.fill(); ctx.stroke();

                // 文字细节
                if (Math.abs(angle) < Math.PI/2) {
                    ctx.fillStyle = '#2d3436';
                    ctx.font = '8px sans-serif';
                    ctx.fillText('DF-41', -10, 3);
                }

            } else {
                // 普通炸弹
                ctx.fillStyle = '#000'; ctx.beginPath(); ctx.arc(0, 0, 10, 0, Math.PI*2); ctx.fill();
                if (frameRef.current % 8 < 4) { ctx.fillStyle = '#ff0000'; ctx.beginPath(); ctx.arc(3, -3, 3, 0, Math.PI*2); ctx.fill(); }
            }
        }
        ctx.restore();
    });

    particlesRef.current.forEach(p => {
        ctx.fillStyle = p.color;
        // 支持透明度变化
        const alpha = p.currentAlpha !== undefined ? p.currentAlpha : (p.life / p.maxLife);
        ctx.globalAlpha = alpha;

        ctx.beginPath(); ctx.arc(p.pos.x, p.pos.y, p.size, 0, Math.PI * 2); ctx.fill();
        ctx.globalAlpha = 1.0;
    });

    entitiesRef.current.forEach(entity => drawEntity(ctx, entity));

    // === 闪光特效 (最上层) ===
    if (flashRef.current > 0) {
        ctx.fillStyle = `rgba(255, 255, 255, ${flashRef.current})`;
        ctx.fillRect(-shakeX, -shakeY, canvas.width, canvas.height); // 抵消shake，保证全屏
    }

    ctx.restore();
  };

  const tick = () => {
    update();
    draw();
    requestRef.current = requestAnimationFrame(tick);
  };

  useEffect(() => {
    if (canvasRef.current) {
        canvasRef.current.width = window.innerWidth;
        canvasRef.current.height = window.innerHeight;
    }
    requestRef.current = requestAnimationFrame(tick);
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [gameState]);

  return (
    <canvas 
        ref={canvasRef} 
        className="block w-full h-full bg-slate-900"
    />
  );
};

export default GameCanvas;

import React, { useRef, useEffect, useCallback } from 'react';
import { GameState, Entity, Vector, Particle, GameStats, GameMode, FallingItem, Projectile, WeaponType, Platform } from '../types';
import { playJumpSound, playAttackSound, playHitSound, playShootSound, playExplodeSound, playDragonRoar } from '../services/audioService';

interface GameCanvasProps {
  gameState: GameState;
  setGameState: (state: GameState) => void;
  setStats: React.Dispatch<React.SetStateAction<GameStats>>;
  setPlayers: (players: Entity[]) => void;
  gameMode: GameMode;
}

// === 物理参数 (提速版) ===
const GRAVITY = 0.8; // 重力增加，下落更快，跳跃手感更干脆
const FRICTION = 0.82; // 摩擦力减小，保留一定惯性但更可控
const MOVE_SPEED = 3.5; // 移动加速度大幅提升 (原 1.2)
const JUMP_FORCE = -22; // 跳跃力度增加 (原 -16)
const GROUND_Y = 600;
const ATTACK_COOLDOWN = 18; // 攻击冷却缩短 (原 30)，连招更爽快
const ATTACK_RANGE = 100;
const ATTACK_DAMAGE = 8;

// === 武器生成配置 ===
const MAX_WEAPONS_PER_GAME = 6; 
const WEAPON_SPAWN_INTERVAL = 900; 
const WEAPON_LIFETIME = 15 * 60; 

// === 关卡设计 ===
const PLATFORMS: Platform[] = [
    { x: 300, y: 450, width: 200, height: 20 },
    { x: 800, y: 450, width: 200, height: 20 },
    { x: 500, y: 250, width: 300, height: 20 } 
];

const GameCanvas: React.FC<GameCanvasProps> = ({ gameState, setGameState, setStats, setPlayers, gameMode }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();
  const frameRef = useRef<number>(0);

  const entitiesRef = useRef<Entity[]>([]);
  const particlesRef = useRef<Particle[]>([]);
  const fallingItemsRef = useRef<FallingItem[]>([]);
  const projectilesRef = useRef<Projectile[]>([]);

  // 武器生成控制
  const spawnedWeaponCountRef = useRef<number>(0); 
  const atomBombIndexRef = useRef<number>(-1); 
  const missileIndexRef = useRef<number>(-1); 
  const dragonIndexRef = useRef<number>(-1); 

  const keysRef = useRef<Set<string>>(new Set());
  const statsRef = useRef<GameStats>({ winner: null, mode: gameMode, duration: 0 });
  const shakeRef = useRef<number>(0);
  const flashRef = useRef<number>(0); 

  // 初始化对决
  const initGame = useCallback(() => {
    const newEntities: Entity[] = [];

    // P1 (左侧)
    newEntities.push({
      id: 'p1', type: 'player', playerIndex: 0,
      pos: { x: 100, y: 100 }, vel: { x: 0, y: 0 }, 
      width: 40, height: 70, color: '#3b82f6', 
      isGrounded: false, isCrouching: false, health: 100, maxHealth: 100, isDead: false,
      facingRight: true, attackCooldown: 0, isAttacking: false, attackFrame: 0,
      heldWeapon: null, ammo: 0, weaponDuration: 0, stunFrames: 0
    });

    // P2/CPU (右侧)
    newEntities.push({
      id: 'p2', type: 'player', playerIndex: 1,
      pos: { x: window.innerWidth - 100, y: 100 }, vel: { x: 0, y: 0 },
      width: 40, height: 70, color: '#facc15',
      isGrounded: false, isCrouching: false, health: 100, maxHealth: 100, isDead: false,
      facingRight: false, attackCooldown: 0, isAttacking: false, attackFrame: 0,
      heldWeapon: null, ammo: 0, weaponDuration: 0, stunFrames: 0
    });

    entitiesRef.current = newEntities;
    particlesRef.current = [];
    fallingItemsRef.current = [];
    projectilesRef.current = [];
    spawnedWeaponCountRef.current = 0; 

    const indices = Array.from({length: MAX_WEAPONS_PER_GAME}, (_, i) => i);
    for (let i = indices.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [indices[i], indices[j]] = [indices[j], indices[i]];
    }

    atomBombIndexRef.current = indices[0];
    missileIndexRef.current = indices[1];
    dragonIndexRef.current = indices[2]; 

    statsRef.current = { winner: null, mode: gameMode, duration: 0 };
    frameRef.current = 0;
    shakeRef.current = 0;
    flashRef.current = 0;

    setStats(statsRef.current);
    setPlayers([...entitiesRef.current]);
  }, [gameMode, setStats, setPlayers]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        if (e.repeat) return;
        keysRef.current.add(e.code);
        if (e.code === 'KeyR' && gameState === GameState.GAME_OVER) {
             setGameState(GameState.PLAYING);
        }
    };
    const handleKeyUp = (e: KeyboardEvent) => keysRef.current.delete(e.code);
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, [gameState, setGameState]);

  useEffect(() => {
    if (gameState === GameState.PLAYING) {
      initGame();
    }
  }, [gameState, initGame]);

  const spawnParticles = (x: number, y: number, color: string, count: number, speed = 8, lifeMultiplier = 1) => {
      for(let i=0; i<count; i++) {
          particlesRef.current.push({
              id: Math.random().toString(),
              pos: {x, y},
              vel: { x: (Math.random() - 0.5) * speed, y: (Math.random() - 0.5) * speed },
              life: (20 + Math.random() * 20) * lifeMultiplier,
              maxLife: 40 * lifeMultiplier,
              color: color,
              size: Math.random() * 6 + 3,
              gravity: 0.5 
          });
      }
  };

  const spawnMushroomCloud = (x: number, y: number) => {
    // 1. 蘑菇柄 (上升的烟柱)
    for (let i = 0; i < 20; i++) {
      particlesRef.current.push({
        id: Math.random().toString(),
        pos: { x: x + (Math.random()-0.5)*20, y: y },
        vel: { x: (Math.random()-0.5) * 1, y: -2 - Math.random() * 3 },
        life: 180,
        maxLife: 180,
        color: i % 2 === 0 ? '#555' : '#333',
        size: 15 + Math.random() * 10,
        gravity: -0.05, // 轻微上升
        growth: 0.3, // 膨胀
        alphaDecay: 0.005,
        currentAlpha: 0.8
      });
    }

    // 2. 蘑菇盖 (顶部扩散)
    for (let i = 0; i < 40; i++) {
      const angle = (Math.PI / 40) * i * 2; // 360度
      const speed = 2 + Math.random() * 3;
      particlesRef.current.push({
        id: Math.random().toString(),
        pos: { x: x, y: y - 80 },
        vel: { x: Math.cos(angle) * speed, y: Math.sin(angle) * speed * 0.5 - 1 },
        life: 200,
        maxLife: 200,
        color: Math.random() > 0.5 ? '#ff4500' : '#ff8800', // 橙红火光
        size: 20 + Math.random() * 10,
        gravity: -0.02,
        growth: 0.5, // 快速膨胀
        alphaDecay: 0.008,
        currentAlpha: 0.9
      });
    }

    // 3. 底部冲击波 (贴地尘土)
    for (let i = 0; i < 30; i++) {
        const dir = i % 2 === 0 ? 1 : -1;
        particlesRef.current.push({
            id: Math.random().toString(),
            pos: { x: x, y: y },
            vel: { x: dir * (5 + Math.random()*10), y: -1 },
            life: 100, maxLife: 100,
            color: '#777',
            size: 10,
            gravity: 0,
            growth: 0.8,
            alphaDecay: 0.02,
            currentAlpha: 0.6
        });
    }
  };

  const spawnConfetti = (width: number) => {
      const colors = ['#FFD700', '#FF6347', '#00BFFF', '#32CD32', '#FF69B4', '#FFFFFF'];
      const x = Math.random() * width;
      const y = -10; 
      const color = colors[Math.floor(Math.random() * colors.length)];
      particlesRef.current.push({
          id: Math.random().toString(),
          pos: { x, y },
          vel: { x: (Math.random() - 0.5) * 2, y: Math.random() * 2 + 1 },
          life: 200, maxLife: 200, color, size: Math.random() * 4 + 3, gravity: 0.02 
      });
  };

  const spawnFallingItem = (canvasWidth: number) => {
      let type: WeaponType;

      const count = spawnedWeaponCountRef.current;

      if (count === atomBombIndexRef.current) {
          type = 'atom_bomb';
      } else if (count === missileIndexRef.current) {
          type = 'missile';
      } else if (count === dragonIndexRef.current) {
          type = 'dragon';
      } else {
          const normalPool: WeaponType[] = ['pistol', 'bomb', 'stick', 'sword', 'blade'];
          type = normalPool[Math.floor(Math.random() * normalPool.length)];
      }

      fallingItemsRef.current.push({
          id: Math.random().toString() + "_" + Date.now(),
          type,
          pos: { x: 100 + Math.random() * (canvasWidth - 200), y: -50 },
          vel: { x: (Math.random() - 0.5) * 2, y: 2 },
          width: 30, height: 30,
          onGround: false
      });
      spawnedWeaponCountRef.current++;
  };

  const update = () => {
    if (gameState !== GameState.PLAYING && gameState !== GameState.VICTORY_ANIMATION) return;
    const canvas = canvasRef.current;
    if (!canvas) return;

    frameRef.current++;
    if (shakeRef.current > 0) shakeRef.current--;
    if (flashRef.current > 0) flashRef.current -= 0.02; 
    if (gameState === GameState.PLAYING) statsRef.current.duration += 1/60;

    const triggerWin = (winnerId: string) => {
        if (statsRef.current.winner) return;
        const winner = entitiesRef.current.find(e => e.id === winnerId);
        if (winner) winner.isWinner = true;
        statsRef.current.winner = winnerId === 'p1' ? 'P1' : 'P2';
        setGameState(GameState.VICTORY_ANIMATION);
        setTimeout(() => setGameState(GameState.GAME_OVER), 4000);
    };

    // === 0. 掉落物生成 ===
    if (gameState === GameState.PLAYING && 
        spawnedWeaponCountRef.current < MAX_WEAPONS_PER_GAME && 
        frameRef.current > 60 && 
        frameRef.current % WEAPON_SPAWN_INTERVAL === 0) {
        spawnFallingItem(canvas.width);
    }

    // === 1. 掉落物逻辑 ===
    fallingItemsRef.current.forEach(item => {
        item.vel.y += 0.2; 
        if (item.vel.y > 8) item.vel.y = 8;

        const prevY = item.pos.y;
        item.pos.x += item.vel.x;
        item.pos.y += item.vel.y;

        if (item.pos.y >= GROUND_Y - item.height) {
            item.pos.y = GROUND_Y - item.height;
            item.onGround = true;
            item.vel.y = -item.vel.y * 0.5;
            item.vel.x *= 0.8;
        }

        if (item.vel.y > 0) {
            PLATFORMS.forEach(plat => {
                if (item.pos.x + item.width > plat.x && item.pos.x < plat.x + plat.width) {
                    if (prevY + item.height <= plat.y && item.pos.y + item.height >= plat.y) {
                        item.pos.y = plat.y - item.height;
                        item.onGround = true;
                        item.vel.y = -item.vel.y * 0.5;
                        item.vel.x *= 0.8;
                    }
                }
            });
        }
    });

    // === 2. 投射物逻辑 (子弹、炸弹、导弹、神龙) ===
    projectilesRef.current.forEach(proj => {
        if (!proj.active) return;

        // --- 神龙逻辑 (优化动作) ---
        if (proj.type === 'dragon') {
            const dragonSegmentsCount = 20; // 增加段数，更流畅
            if (!proj.dragonSegments || proj.dragonSegments.length === 0) {
                proj.dragonSegments = Array.from({ length: dragonSegmentsCount }, () => ({ ...proj.pos }));
            }

            if (proj.dragonState === 'enter') {
                if (!proj.dragonPathProgress) proj.dragonPathProgress = 0;
                proj.dragonPathProgress += 0.02;

                shakeRef.current = 8;
                if (Math.random() < 0.1) playExplodeSound();

                const w = canvas.width;
                const h = canvas.height;
                const t = proj.dragonPathProgress * Math.PI * 2;

                // 更复杂的入场轨迹
                const targetX = w/2 + (w/2 - 50) * Math.cos(t) * Math.sin(t*0.5);
                const targetY = h/3 + (h/4) * Math.sin(2*t);

                proj.vel.x = (targetX - proj.pos.x) * 0.2;
                proj.vel.y = (targetY - proj.pos.y) * 0.2;
                proj.pos.x += proj.vel.x;
                proj.pos.y += proj.vel.y;

                if (proj.dragonPathProgress >= 1.5) {
                    proj.dragonState = 'hunt';
                    shakeRef.current = 0;
                }
            } else if (proj.dragonState === 'hunt') {
                const target = entitiesRef.current.find(e => e.id !== proj.ownerId && !e.isDead);
                if (target) {
                    const dx = target.pos.x - proj.pos.x;
                    const dy = (target.pos.y - 40) - proj.pos.y;
                    const dist = Math.sqrt(dx*dx + dy*dy);

                    const speed = 7; // 略微提速
                    // 增加一点惯性，避免转弯太生硬
                    proj.vel.x = (proj.vel.x * 20 + (dx / dist) * speed) / 21;
                    proj.vel.y = (proj.vel.y * 20 + (dy / dist) * speed) / 21;

                    proj.pos.x += proj.vel.x;
                    proj.pos.y += proj.vel.y;

                    if (dist < 50) {
                        const now = frameRef.current;
                        if (!proj.lastHitFrame || now - proj.lastHitFrame > 30) {
                            proj.lastHitFrame = now;
                            if (proj.remainingHits && proj.remainingHits > 0) {
                                proj.remainingHits--;

                                target.health -= 5;
                                target.stunFrames = 20;
                                target.vel.x = (Math.random()-0.5) * 30;
                                target.vel.y = -15;

                                playHitSound();
                                spawnParticles(target.pos.x, target.pos.y, '#FFD700', 20, 8);
                                shakeRef.current = 15;

                                if (target.health <= 0) {
                                    target.health = 0;
                                    target.isDead = true;
                                    target.isLoser = true;
                                    triggerWin(proj.ownerId);
                                }

                                if (proj.remainingHits <= 0) {
                                    proj.active = false;
                                    // 神龙离去特效
                                    spawnParticles(proj.pos.x, proj.pos.y, '#FFD700', 80, 15);
                                }
                            }
                        }
                    }
                } else {
                    proj.vel.y -= 0.5;
                    proj.pos.x += Math.sin(frameRef.current * 0.1) * 5;
                    proj.pos.y += proj.vel.y;
                    if (proj.pos.y < -300) proj.active = false;
                }
            }

            if (proj.dragonSegments && proj.dragonSegments.length > 0) {
                proj.dragonSegments[0] = { ...proj.pos };
                for (let i = 1; i < proj.dragonSegments.length; i++) {
                    const current = proj.dragonSegments[i];
                    const prev = proj.dragonSegments[i-1];
                    const dx = prev.x - current.x;
                    const dy = prev.y - current.y;
                    const d = Math.sqrt(dx*dx + dy*dy);
                    const spacing = 18; 

                    if (d > spacing) {
                        const ratio = (d - spacing) / d;
                        current.x += dx * ratio;
                        current.y += dy * ratio;
                    }
                }
            }
            return; 
        }

        // --- 巡航导弹逻辑 (东风) ---
        if (proj.type === 'missile') {
            if (frameRef.current % 2 === 0) {
                // 浓烟尾迹
                particlesRef.current.push({
                    id: Math.random().toString(),
                    pos: { x: proj.pos.x, y: proj.pos.y },
                    vel: { x: -proj.vel.x * 0.1, y: -proj.vel.y * 0.1 }, // 惯性残留
                    life: 40, maxLife: 40, color: '#aaa', size: 6, gravity: 0, growth: 0.2, alphaDecay: 0.05
                });
                // 火焰中心
                particlesRef.current.push({
                    id: Math.random().toString(),
                    pos: { x: proj.pos.x, y: proj.pos.y },
                    vel: { x: -proj.vel.x * 0.5, y: -proj.vel.y * 0.5 },
                    life: 10, maxLife: 10, color: '#ff5500', size: 4, gravity: 0
                });
            }

            const target = entitiesRef.current.find(e => e.id !== proj.ownerId && !e.isDead);
            if (target) {
                const targetX = target.pos.x;
                const targetY = target.pos.y - 35; 
                const dx = targetX - proj.pos.x;
                const dy = targetY - proj.pos.y;
                const dist = Math.sqrt(dx*dx + dy*dy);

                if (dist > 10) {
                    const speed = 8; // 导弹速度
                    // 增加追踪惯性
                    proj.vel.x = (proj.vel.x * 30 + (dx / dist) * speed) / 31;
                    proj.vel.y = (proj.vel.y * 30 + (dy / dist) * speed) / 31;
                }
            }
        }

        proj.pos.x += proj.vel.x;
        proj.pos.y += proj.vel.y;

        // --- 炸弹/原子弹落地 ---
        if (proj.type === 'bomb' || proj.type === 'atom_bomb') {
            const isNuke = proj.type === 'atom_bomb';
            proj.vel.y += GRAVITY; 
            let hitGround = false;
             if (proj.pos.y >= GROUND_Y) { hitGround = true; }
             else if (proj.vel.y > 0) {
                 PLATFORMS.forEach(plat => {
                     if (proj.pos.x > plat.x && proj.pos.x < plat.x + plat.width && 
                         proj.pos.y >= plat.y && proj.pos.y <= plat.y + 20) {
                         hitGround = true;
                     }
                 });
             }

            if (hitGround) {
                proj.active = false;

                if (isNuke) {
                    // === 核爆逻辑升级 ===
                    shakeRef.current = 120; 
                    flashRef.current = 1.0; 
                    playExplodeSound();

                    // 生成蘑菇云
                    spawnMushroomCloud(proj.pos.x, proj.pos.y - 10);

                    // 冲击波伤害范围极大
                    entitiesRef.current.forEach(target => {
                         if (!target.isDead) {
                             target.health = 0;
                             target.isDead = true;
                             target.isLoser = true;
                             // 被吹飞
                             const dir = target.pos.x - proj.pos.x > 0 ? 1 : -1;
                             target.vel.x = dir * 60;
                             target.vel.y = -60;

                             if (target.id !== proj.ownerId) {
                                 const winner = entitiesRef.current.find(e => e.id === proj.ownerId);
                                 if (winner) triggerWin(winner.id);
                             } else {
                                 const enemy = entitiesRef.current.find(e => e.id !== proj.ownerId);
                                 if (enemy) triggerWin(enemy.id);
                             }
                         }
                    });

                } else {
                    shakeRef.current = 25; 
                    playExplodeSound();
                    spawnParticles(proj.pos.x, proj.pos.y, '#ff4500', 40, 15, 2); 

                    entitiesRef.current.forEach(target => {
                        if (!target.isDead) {
                            const dist = Math.sqrt(Math.pow(target.pos.x - proj.pos.x, 2) + Math.pow(target.pos.y - proj.pos.y, 2));
                            if (dist < 180) {
                                target.health -= 25; 
                                if (target.health <= 0) { target.health = 0; target.isDead = true; target.isLoser = true; }

                                const angle = Math.atan2(target.pos.y - proj.pos.y, target.pos.x - proj.pos.x);
                                target.vel.x = Math.cos(angle) * 30;
                                target.vel.y = Math.sin(angle) * 30;
                                target.stunFrames = 30;

                                if (target.isDead) {
                                    const winner = entitiesRef.current.find(e => e.id === proj.ownerId);
                                    if (winner) triggerWin(winner.id);
                                }
                            }
                        }
                    });
                }
            }
        } else {
            // === 碰撞逻辑 (子弹 & 导弹) ===
            const isMissile = proj.type === 'missile';
            if (proj.pos.x < 0 || proj.pos.x > canvas.width || proj.pos.y > canvas.height + 100 || proj.pos.y < -200) proj.active = false;

            entitiesRef.current.forEach(target => {
                if (target.id !== proj.ownerId && !target.isDead && proj.active) {
                    const hitDist = isMissile ? 50 : 30; 
                    if (Math.abs(proj.pos.x - target.pos.x) < hitDist &&
                        proj.pos.y > target.pos.y - 75 && proj.pos.y < target.pos.y + 10) {

                        proj.active = false;
                        const damage = isMissile ? 35 : 15; // 导弹伤害增加
                        target.health -= damage; 
                        target.stunFrames = isMissile ? 40 : 10;
                        shakeRef.current = isMissile ? 25 : 5;

                        isMissile ? playExplodeSound() : playHitSound();

                        // 导弹击中特效
                        if (isMissile) {
                             spawnParticles(target.pos.x, target.pos.y - 35, '#ff5500', 40, 10);
                             spawnParticles(target.pos.x, target.pos.y - 35, '#555', 20, 5);
                        } else {
                             spawnParticles(target.pos.x, target.pos.y - 35, '#ff0000', 10, 8);
                        }

                        target.vel.x += proj.vel.x * (isMissile ? 1.2 : 0.3); 
                        target.vel.y -= isMissile ? 15 : 5;

                        if (target.health <= 0) {
                            target.health = 0; 
                            target.isDead = true;
                            target.isLoser = true;
                            target.vel.x = proj.vel.x * 0.8;
                            const winner = entitiesRef.current.find(e => e.id === proj.ownerId);
                            if (winner) triggerWin(winner.id);
                        }
                    }
                }
            });
        }
    });
    projectilesRef.current = projectilesRef.current.filter(p => p.active);

    // === 3. 实体更新 ===
    entitiesRef.current.forEach(entity => {
      // 检查武器是否过期
      if (entity.heldWeapon) {
          entity.weaponDuration--;
          if (entity.weaponDuration <= 0) {
              entity.heldWeapon = null;
              spawnParticles(entity.pos.x, entity.pos.y - 40, '#888', 5, 5); // 消失特效
          }
      }

      if (gameState === GameState.VICTORY_ANIMATION && entity.isWinner) {
          entity.isAttacking = false; entity.attackFrame = 0; entity.isCrouching = false;
          const targetX = canvas.width / 2;
          const targetY = canvas.height / 3;
          entity.pos.x += (targetX - entity.pos.x) * 0.05;
          entity.pos.y += (targetY - entity.pos.y) * 0.05;
          entity.pos.y += Math.sin(frameRef.current * 0.08) * 0.8;
          entity.vel.x = 0; entity.vel.y = 0;
          if (frameRef.current % 3 === 0) spawnConfetti(canvas.width);
          return;
      }

      // 拾取武器
      if (!entity.isDead) {
          const canPickUp = !entity.heldWeapon || entity.ammo <= 0;

          if (canPickUp) {
            const itemIndex = fallingItemsRef.current.findIndex(item => {
                const dx = Math.abs(entity.pos.x - (item.pos.x + item.width/2));
                const dy = Math.abs((entity.pos.y - 35) - (item.pos.y + item.height/2));
                return dx < 50 && dy < 60;
            });

            if (itemIndex !== -1) {
                const item = fallingItemsRef.current[itemIndex];
                entity.heldWeapon = item.type;
                entity.weaponDuration = WEAPON_LIFETIME; 
                switch(item.type) {
                    case 'pistol': entity.ammo = 6; break;
                    case 'bomb': entity.ammo = 3; break;
                    case 'stick': entity.ammo = 10; break; 
                    case 'sword': entity.ammo = 8; break;
                    case 'blade': entity.ammo = 5; break; 
                    case 'atom_bomb': entity.ammo = 1; break; 
                    case 'missile': entity.ammo = 2; break; // 导弹只有2发
                    case 'dragon': entity.ammo = 1; break; 
                }
                fallingItemsRef.current.splice(itemIndex, 1);
                playJumpSound();
                spawnParticles(entity.pos.x, entity.pos.y - 30, '#fff', 5, 5);
            }
          }
      }

      // 物理引擎
      const prevY = entity.pos.y;
      entity.vel.y += GRAVITY;

      if (!entity.isLoser && entity.stunFrames > 0) {
           entity.stunFrames--; 
           entity.vel.x *= 0.95; 
      } else if (!entity.isLoser) {
          const currentFriction = entity.isCrouching && entity.isGrounded ? 0.4 : FRICTION;
          entity.vel.x *= currentFriction;
      } else {
          entity.vel.x *= 0.99; 
      }

      entity.pos.x += entity.vel.x;
      entity.pos.y += entity.vel.y;

      // 碰撞检测
      entity.isGrounded = false;
      if (entity.pos.y >= GROUND_Y) {
          if (!entity.isLoser) {
            entity.pos.y = GROUND_Y;
            entity.vel.y = 0;
            entity.isGrounded = true;
          }
      }
      if (entity.vel.y >= 0 && !entity.isDead) {
          PLATFORMS.forEach(plat => {
              if (entity.pos.x > plat.x - 10 && entity.pos.x < plat.x + plat.width + 10) {
                  if (prevY <= plat.y && entity.pos.y >= plat.y) {
                      entity.pos.y = plat.y;
                      entity.vel.y = 0;
                      entity.isGrounded = true;
                  }
              }
          });
      }

      if (!entity.isLoser) {
        if (entity.pos.x < 10) { entity.pos.x = 10; entity.vel.x *= -0.5; }
        if (entity.pos.x > canvas.width - 10) { entity.pos.x = canvas.width - 10; entity.vel.x *= -0.5; }
      }

      if (gameState === GameState.VICTORY_ANIMATION || entity.isDead || entity.stunFrames > 0) return;

      if (entity.attackCooldown > 0) entity.attackCooldown--;
      if (entity.isAttacking) {
          entity.attackFrame++;
          if (entity.attackFrame > 15) { 
              entity.isAttacking = false;
              entity.attackFrame = 0;
          }
      }

      let moveLeft = false, moveRight = false, jump = false, crouch = false, attack = false;

      // Input P1
      if (entity.playerIndex === 0) {
        if (keysRef.current.has('KeyA')) moveLeft = true;
        if (keysRef.current.has('KeyD')) moveRight = true;
        if (keysRef.current.has('KeyW')) jump = true;
        if (keysRef.current.has('KeyS')) crouch = true;
        if (keysRef.current.has('Space')) attack = true;
      }

      // Input P2 / AI
      if (entity.playerIndex === 1) {
          if (gameMode === 'PVP') {
            if (keysRef.current.has('ArrowLeft')) moveLeft = true;
            if (keysRef.current.has('ArrowRight')) moveRight = true;
            if (keysRef.current.has('ArrowUp')) jump = true;
            if (keysRef.current.has('ArrowDown')) crouch = true;
            if (keysRef.current.has('Enter')) attack = true;
          } else {
            // AI Logic
            const p1 = entitiesRef.current.find(e => e.playerIndex === 0);
            if (p1 && !p1.isDead) {
                let targetX = p1.pos.x;
                let targetY = p1.pos.y;

                if (!entity.heldWeapon && fallingItemsRef.current.length > 0) {
                    let minDist = 9999;
                    fallingItemsRef.current.forEach(item => {
                        const d = Math.abs(item.pos.x - entity.pos.x) + Math.abs(item.pos.y - entity.pos.y);
                        if (d < minDist) {
                            minDist = d;
                            targetX = item.pos.x;
                            targetY = item.pos.y;
                        }
                    });
                }

                const distX = targetX - entity.pos.x;
                const distY = targetY - entity.pos.y; 

                if (Math.abs(distX) > 40) {
                    distX > 0 ? moveRight = true : moveLeft = true;
                } else if (!entity.heldWeapon && Math.abs(distX) < 20) {
                     distX > 0 ? moveLeft = true : moveRight = true;
                }

                if (entity.isGrounded) {
                     if (distY < -100 || (Math.random() < 0.02)) {
                         jump = true;
                     }
                }

                const absDistX = Math.abs(p1.pos.x - entity.pos.x);
                entity.facingRight = (p1.pos.x - entity.pos.x) > 0;

                // AI 攻击逻辑
                let attackRange = ATTACK_RANGE;
                if (entity.heldWeapon === 'stick') attackRange = 200;
                if (entity.heldWeapon === 'pistol') attackRange = 600;
                if (entity.heldWeapon === 'atom_bomb') attackRange = 300; 
                if (entity.heldWeapon === 'missile') attackRange = 700; 
                if (entity.heldWeapon === 'dragon') attackRange = 400; 

                if (absDistX < attackRange && Math.abs(p1.pos.y - entity.pos.y) < 100) {
                    if (entity.attackCooldown === 0 && Math.random() < 0.05) attack = true;
                }
            }
          }
      }

      entity.isCrouching = crouch && entity.isGrounded;
      if (!entity.isCrouching) {
          if (moveLeft) { entity.vel.x -= MOVE_SPEED; entity.facingRight = false; }
          if (moveRight) { entity.vel.x += MOVE_SPEED; entity.facingRight = true; }
      }
      if (jump && entity.isGrounded && !entity.isCrouching) {
          entity.vel.y = JUMP_FORCE;
          playJumpSound();
      }

      // === 攻击处理 ===
      if (attack && entity.attackCooldown === 0) {
          entity.attackCooldown = ATTACK_COOLDOWN;
          entity.isAttacking = true;
          entity.attackFrame = 5;

          if (entity.heldWeapon === 'pistol') {
              playShootSound();
              entity.vel.x += entity.facingRight ? -8 : 8;
              entity.vel.y -= 2;

              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'pistol',
                  pos: { x: entity.pos.x + (entity.facingRight ? 40 : -40), y: entity.pos.y - 45 },
                  vel: { x: entity.facingRight ? 20 : -20, y: (Math.random()-0.5) * 2 }, 
                  ownerId: entity.id,
                  width: 12, height: 4, active: true
              });
              entity.ammo--;
          } else if (entity.heldWeapon === 'bomb') {
              entity.vel.x += entity.facingRight ? -2 : 2;
              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'bomb',
                  pos: { x: entity.pos.x, y: entity.pos.y - 60 },
                  vel: { x: entity.facingRight ? 12 : -12, y: -12 },
                  ownerId: entity.id,
                  width: 20, height: 20, active: true
              });
              entity.ammo--;
          } else if (entity.heldWeapon === 'atom_bomb') {
              entity.vel.x += entity.facingRight ? -4 : 4;
              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'atom_bomb',
                  pos: { x: entity.pos.x, y: entity.pos.y - 70 },
                  vel: { x: entity.facingRight ? 8 : -8, y: -10 },
                  ownerId: entity.id,
                  width: 30, height: 40, active: true
              });
              entity.ammo--; 
          } else if (entity.heldWeapon === 'missile') {
              playShootSound(); 
              entity.vel.x += entity.facingRight ? -10 : 10; 
              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'missile',
                  pos: { x: entity.pos.x + (entity.facingRight ? 50 : -50), y: entity.pos.y - 50 },
                  vel: { x: entity.facingRight ? 10 : -10, y: -5 }, 
                  ownerId: entity.id,
                  width: 20, height: 8, active: true
              });
              entity.ammo--; 
          } else if (entity.heldWeapon === 'dragon') {
              playDragonRoar();
              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'dragon',
                  pos: { x: entity.pos.x, y: entity.pos.y - 100 },
                  vel: { x: 0, y: 0 },
                  ownerId: entity.id,
                  width: 40, height: 40, active: true,
                  dragonState: 'enter', 
                  remainingHits: 5,
                  dragonPathProgress: 0,
                  dragonSegments: undefined
              });
              entity.ammo--;
          } else {
              // == 近战武器 ==
              playAttackSound();

              let range = ATTACK_RANGE;
              let dmg = ATTACK_DAMAGE;
              let knockbackX = 15;
              let knockbackY = -8;
              let selfPush = 10;
              let hitEffectSize = 12;

              if (entity.heldWeapon === 'stick') {
                  range = 220; dmg = 12; knockbackX = 20; selfPush = 5; hitEffectSize = 15;
              } else if (entity.heldWeapon === 'sword') {
                  range = 140; dmg = 15; knockbackX = 12; selfPush = 12; entity.attackCooldown = 20; 
              } else if (entity.heldWeapon === 'blade') {
                  range = 160; dmg = 25; knockbackX = 25; knockbackY = -12; selfPush = 2; entity.attackCooldown = 50; 
              }

              entity.vel.x = entity.facingRight ? selfPush : -selfPush;

              const hitX = entity.facingRight ? entity.pos.x + range/2 : entity.pos.x - range/2;
              const hitY = entity.isCrouching ? entity.pos.y - 20 : entity.pos.y - 45;

              let hitSomething = false;

              entitiesRef.current.forEach(target => {
                  if (target !== entity && !target.isDead) {
                      const dy = (target.pos.y - 35) - hitY;
                      if (Math.abs(target.pos.x - entity.pos.x) < range && Math.abs(dy) < 60 && 
                          ((entity.facingRight && target.pos.x > entity.pos.x) || (!entity.facingRight && target.pos.x < entity.pos.x))) {

                          if (!entity.isCrouching && target.isCrouching) {
                              spawnParticles(target.pos.x, target.pos.y - 40, '#aaa', 2, 2);
                              return; 
                          }

                          target.health -= dmg;
                          hitSomething = true;

                          target.vel.x = entity.facingRight ? knockbackX : -knockbackX; 
                          target.vel.y = knockbackY; 
                          target.stunFrames = 20; 

                          shakeRef.current = Math.floor(dmg / 2);
                          spawnParticles(target.pos.x, target.pos.y - 40, target.color, hitEffectSize, 10);
                          playHitSound();

                          if (target.health <= 0) {
                              target.health = 0;
                              target.isDead = true;
                              target.isLoser = true;
                              target.vel.x = entity.facingRight ? 30 : -30;
                              target.vel.y = -20;
                              triggerWin(entity.id);
                          }
                      }
                  }
              });

              if (hitSomething && entity.heldWeapon) {
                  entity.ammo--;
              }
          }

          // 弹药耗尽检查
          if (entity.heldWeapon && entity.ammo <= 0) {
              entity.heldWeapon = null;
              spawnParticles(entity.pos.x, entity.pos.y - 40, '#888', 5, 5); 
          }
      }
    });

    particlesRef.current.forEach(p => {
        ctx.fillStyle = p.color;
        // 支持透明度变化
        const alpha = p.currentAlpha !== undefined ? p.currentAlpha : (p.life / p.maxLife);
        ctx.globalAlpha = alpha;

        ctx.beginPath(); ctx.arc(p.pos.x, p.pos.y, p.size, 0, Math.PI * 2); ctx.fill();
        ctx.globalAlpha = 1.0;
    });

    entitiesRef.current.forEach(entity => drawEntity(ctx, entity));

    // === 闪光特效 (最上层) ===
    if (flashRef.current > 0) {
        ctx.fillStyle = `rgba(255, 255, 255, ${flashRef.current})`;
        ctx.fillRect(-shakeX, -shakeY, canvas.width, canvas.height); // 抵消shake，保证全屏
    }

    ctx.restore();
  };

  const tick = () => {
    update();
    draw();
    requestRef.current = requestAnimationFrame(tick);
  };

  useEffect(() => {
    if (canvasRef.current) {
        canvasRef.current.width = window.innerWidth;
        canvasRef.current.height = window.innerHeight;
    }
    requestRef.current = requestAnimationFrame(tick);
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [gameState]);

  return (
    <canvas 
        ref={canvasRef} 
        className="block w-full h-full bg-slate-900"
    />
  );
};

export default GameCanvas;

import React, { useRef, useEffect, useCallback } from 'react';
import { GameState, Entity, Vector, Particle, GameStats, GameMode, FallingItem, Projectile, WeaponType, Platform } from '../types';
import { playJumpSound, playAttackSound, playHitSound, playShootSound, playExplodeSound, playDragonRoar } from '../services/audioService';

interface GameCanvasProps {
  gameState: GameState;
  setGameState: (state: GameState) => void;
  setStats: React.Dispatch<React.SetStateAction<GameStats>>;
  setPlayers: (players: Entity[]) => void;
  gameMode: GameMode;
}

// === 物理参数 (提速版) ===
const GRAVITY = 0.8; // 重力增加，下落更快，跳跃手感更干脆
const FRICTION = 0.82; // 摩擦力减小，保留一定惯性但更可控
const MOVE_SPEED = 3.5; // 移动加速度大幅提升 (原 1.2)
const JUMP_FORCE = -22; // 跳跃力度增加 (原 -16)
const GROUND_Y = 600;
const ATTACK_COOLDOWN = 18; // 攻击冷却缩短 (原 30)，连招更爽快
const ATTACK_RANGE = 100;
const ATTACK_DAMAGE = 8;

// === 武器生成配置 ===
const MAX_WEAPONS_PER_GAME = 6; 
const WEAPON_SPAWN_INTERVAL = 900; 
const WEAPON_LIFETIME = 15 * 60; 

// === 关卡设计 ===
const PLATFORMS: Platform[] = [
    { x: 300, y: 450, width: 200, height: 20 },
    { x: 800, y: 450, width: 200, height: 20 },
    { x: 500, y: 250, width: 300, height: 20 } 
];

const drawEntity = (ctx: CanvasRenderingContext2D, entity: Entity) => {
    ctx.save();

    const centerX = entity.pos.x;
    const centerY = entity.pos.y; // Feet position

    ctx.translate(centerX, centerY);

    if (entity.isDead) {
         ctx.rotate(Math.PI / 2 * (entity.facingRight ? 1 : -1));
         ctx.translate(0, -10);
    }

    if (!entity.facingRight) ctx.scale(-1, 1);

    // Draw body
    ctx.fillStyle = entity.color;
    ctx.strokeStyle = entity.color;
    ctx.lineWidth = 4;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    const crouchOffset = entity.isCrouching ? 20 : 0;

    // Head
    ctx.beginPath();
    ctx.arc(0, -entity.height + 20 + crouchOffset, 12, 0, Math.PI * 2);
    ctx.fill();

    // Body
    ctx.beginPath();
    ctx.moveTo(0, -entity.height + 32 + crouchOffset);
    ctx.lineTo(0, -25 + crouchOffset);
    ctx.stroke();

    // Legs
    ctx.beginPath();
    ctx.moveTo(0, -25 + crouchOffset);
    if (entity.isCrouching) {
        ctx.lineTo(-15, -5);
        ctx.moveTo(0, -25 + crouchOffset);
        ctx.lineTo(15, -5);
    } else if (Math.abs(entity.vel.x) > 0.1 && entity.isGrounded) {
        const walkCycle = Math.sin(Date.now() / 100) * 10;
        ctx.lineTo(-10 + walkCycle, 0);
        ctx.moveTo(0, -25 + crouchOffset);
        ctx.lineTo(10 - walkCycle, 0);
    } else {
        ctx.lineTo(-10, 0);
        ctx.moveTo(0, -25 + crouchOffset);
        ctx.lineTo(10, 0);
    }
    ctx.stroke();

    // Arms
    ctx.beginPath();
    const shoulderY = -entity.height + 40 + crouchOffset;
    ctx.moveTo(0, shoulderY);

    if (entity.isWinner) {
        ctx.lineTo(-20, shoulderY - 30);
        ctx.moveTo(0, shoulderY);
        ctx.lineTo(20, shoulderY - 30);
    } else if (entity.isAttacking) {
        const attackProgress = entity.attackFrame / 15;
        ctx.lineTo(25, shoulderY - 10 + attackProgress * 20);
    } else if (entity.heldWeapon) {
        ctx.lineTo(15, shoulderY + 5);

        ctx.save();
        ctx.translate(15, shoulderY + 5);

        if (entity.heldWeapon === 'pistol') {
            ctx.fillStyle = '#555';
            ctx.fillRect(0, -5, 15, 5);
            ctx.fillRect(0, 0, 5, 5);
        } else if (entity.heldWeapon === 'sword') {
            ctx.fillStyle = '#ccc';
            ctx.fillRect(0, -25, 4, 30);
            ctx.fillStyle = '#8B4513';
            ctx.fillRect(-3, 0, 10, 2);
        } else if (entity.heldWeapon === 'stick') {
            ctx.fillStyle = '#8B4513';
            ctx.rotate(-Math.PI / 4);
            ctx.fillRect(0, -40, 4, 50);
        } else if (entity.heldWeapon === 'blade') {
            ctx.fillStyle = '#777';
            ctx.beginPath();
            ctx.moveTo(0,0);
            ctx.lineTo(30, -10);
            ctx.lineTo(25, 5);
            ctx.fill();
        } else if (entity.heldWeapon === 'bomb' || entity.heldWeapon === 'atom_bomb') {
            ctx.fillStyle = '#000';
            ctx.beginPath();
            ctx.arc(5, 0, 8, 0, Math.PI*2);
            ctx.fill();
            ctx.strokeStyle = '#fff';
            ctx.beginPath();
            ctx.moveTo(5, -8);
            ctx.quadraticCurveTo(10, -15, 15, -10);
            ctx.stroke();
             if (entity.heldWeapon === 'atom_bomb') {
                ctx.fillStyle = 'yellow';
                ctx.font = '10px Arial';
                ctx.fillText('☢', 2, 4);
            }
        } else if (entity.heldWeapon === 'missile') {
             ctx.fillStyle = 'green';
             ctx.fillRect(0, -5, 20, 10);
             ctx.fillStyle = 'red';
             ctx.fillRect(20, -5, 5, 10);
        } else if (entity.heldWeapon === 'dragon') {
             ctx.font = '20px serif';
             ctx.fillText('🐉', 0, 5);
        }
        ctx.restore();

    } else {
        if (Math.abs(entity.vel.x) > 0.1) {
             const armCycle = Math.cos(Date.now() / 100) * 10;
             ctx.lineTo(armCycle, shoulderY + 15);
        } else {
             ctx.lineTo(0, shoulderY + 20);
        }
    }
    ctx.stroke();

    ctx.restore();
};

const GameCanvas: React.FC<GameCanvasProps> = ({ gameState, setGameState, setStats, setPlayers, gameMode }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();
  const frameRef = useRef<number>(0);

  const entitiesRef = useRef<Entity[]>([]);
  const particlesRef = useRef<Particle[]>([]);
  const fallingItemsRef = useRef<FallingItem[]>([]);
  const projectilesRef = useRef<Projectile[]>([]);

  // 武器生成控制
  const spawnedWeaponCountRef = useRef<number>(0); 
  const atomBombIndexRef = useRef<number>(-1); 
  const missileIndexRef = useRef<number>(-1); 
  const dragonIndexRef = useRef<number>(-1); 

  const keysRef = useRef<Set<string>>(new Set());
  const statsRef = useRef<GameStats>({ winner: null, mode: gameMode, duration: 0 });
  const shakeRef = useRef<number>(0);
  const flashRef = useRef<number>(0); 

  // 初始化对决
  const initGame = useCallback(() => {
    const newEntities: Entity[] = [];

    // P1 (左侧)
    newEntities.push({
      id: 'p1', type: 'player', playerIndex: 0,
      pos: { x: 100, y: 100 }, vel: { x: 0, y: 0 }, 
      width: 40, height: 70, color: '#3b82f6', 
      isGrounded: false, isCrouching: false, health: 100, maxHealth: 100, isDead: false,
      facingRight: true, attackCooldown: 0, isAttacking: false, attackFrame: 0,
      heldWeapon: null, ammo: 0, weaponDuration: 0, stunFrames: 0
    });

    // P2/CPU (右侧)
    newEntities.push({
      id: 'p2', type: 'player', playerIndex: 1,
      pos: { x: window.innerWidth - 100, y: 100 }, vel: { x: 0, y: 0 },
      width: 40, height: 70, color: '#facc15',
      isGrounded: false, isCrouching: false, health: 100, maxHealth: 100, isDead: false,
      facingRight: false, attackCooldown: 0, isAttacking: false, attackFrame: 0,
      heldWeapon: null, ammo: 0, weaponDuration: 0, stunFrames: 0
    });

    entitiesRef.current = newEntities;
    particlesRef.current = [];
    fallingItemsRef.current = [];
    projectilesRef.current = [];
    spawnedWeaponCountRef.current = 0; 

    const indices = Array.from({length: MAX_WEAPONS_PER_GAME}, (_, i) => i);
    for (let i = indices.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [indices[i], indices[j]] = [indices[j], indices[i]];
    }

    atomBombIndexRef.current = indices[0];
    missileIndexRef.current = indices[1];
    dragonIndexRef.current = indices[2]; 

    statsRef.current = { winner: null, mode: gameMode, duration: 0 };
    frameRef.current = 0;
    shakeRef.current = 0;
    flashRef.current = 0;

    setStats(statsRef.current);
    setPlayers([...entitiesRef.current]);
  }, [gameMode, setStats, setPlayers]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        if (e.repeat) return;
        keysRef.current.add(e.code);
        if (e.code === 'KeyR' && gameState === GameState.GAME_OVER) {
             setGameState(GameState.PLAYING);
        }
    };
    const handleKeyUp = (e: KeyboardEvent) => keysRef.current.delete(e.code);
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, [gameState, setGameState]);

  useEffect(() => {
    if (gameState === GameState.PLAYING) {
      initGame();
    }
  }, [gameState, initGame]);

  const spawnParticles = (x: number, y: number, color: string, count: number, speed = 8, lifeMultiplier = 1) => {
      for(let i=0; i<count; i++) {
          particlesRef.current.push({
              id: Math.random().toString(),
              pos: {x, y},
              vel: { x: (Math.random() - 0.5) * speed, y: (Math.random() - 0.5) * speed },
              life: (20 + Math.random() * 20) * lifeMultiplier,
              maxLife: 40 * lifeMultiplier,
              color: color,
              size: Math.random() * 6 + 3,
              gravity: 0.5 
          });
      }
  };

  const spawnMushroomCloud = (x: number, y: number) => {
    // 1. 蘑菇柄 (上升的烟柱)
    for (let i = 0; i < 20; i++) {
      particlesRef.current.push({
        id: Math.random().toString(),
        pos: { x: x + (Math.random()-0.5)*20, y: y },
        vel: { x: (Math.random()-0.5) * 1, y: -2 - Math.random() * 3 },
        life: 180,
        maxLife: 180,
        color: i % 2 === 0 ? '#555' : '#333',
        size: 15 + Math.random() * 10,
        gravity: -0.05, // 轻微上升
        growth: 0.3, // 膨胀
        alphaDecay: 0.005,
        currentAlpha: 0.8
      });
    }

    // 2. 蘑菇盖 (顶部扩散)
    for (let i = 0; i < 40; i++) {
      const angle = (Math.PI / 40) * i * 2; // 360度
      const speed = 2 + Math.random() * 3;
      particlesRef.current.push({
        id: Math.random().toString(),
        pos: { x: x, y: y - 80 },
        vel: { x: Math.cos(angle) * speed, y: Math.sin(angle) * speed * 0.5 - 1 },
        life: 200,
        maxLife: 200,
        color: Math.random() > 0.5 ? '#ff4500' : '#ff8800', // 橙红火光
        size: 20 + Math.random() * 10,
        gravity: -0.02,
        growth: 0.5, // 快速膨胀
        alphaDecay: 0.008,
        currentAlpha: 0.9
      });
    }

    // 3. 底部冲击波 (贴地尘土)
    for (let i = 0; i < 30; i++) {
        const dir = i % 2 === 0 ? 1 : -1;
        particlesRef.current.push({
            id: Math.random().toString(),
            pos: { x: x, y: y },
            vel: { x: dir * (5 + Math.random()*10), y: -1 },
            life: 100, maxLife: 100,
            color: '#777',
            size: 10,
            gravity: 0,
            growth: 0.8,
            alphaDecay: 0.02,
            currentAlpha: 0.6
        });
    }
  };

  const spawnConfetti = (width: number) => {
      const colors = ['#FFD700', '#FF6347', '#00BFFF', '#32CD32', '#FF69B4', '#FFFFFF'];
      const x = Math.random() * width;
      const y = -10; 
      const color = colors[Math.floor(Math.random() * colors.length)];
      particlesRef.current.push({
          id: Math.random().toString(),
          pos: { x, y },
          vel: { x: (Math.random() - 0.5) * 2, y: Math.random() * 2 + 1 },
          life: 200, maxLife: 200, color, size: Math.random() * 4 + 3, gravity: 0.02 
      });
  };

  const spawnFallingItem = (canvasWidth: number) => {
      let type: WeaponType;

      const count = spawnedWeaponCountRef.current;

      if (count === atomBombIndexRef.current) {
          type = 'atom_bomb';
      } else if (count === missileIndexRef.current) {
          type = 'missile';
      } else if (count === dragonIndexRef.current) {
          type = 'dragon';
      } else {
          const normalPool: WeaponType[] = ['pistol', 'bomb', 'stick', 'sword', 'blade'];
          type = normalPool[Math.floor(Math.random() * normalPool.length)];
      }

      fallingItemsRef.current.push({
          id: Math.random().toString() + "_" + Date.now(),
          type,
          pos: { x: 100 + Math.random() * (canvasWidth - 200), y: -50 },
          vel: { x: (Math.random() - 0.5) * 2, y: 2 },
          width: 30, height: 30,
          onGround: false
      });
      spawnedWeaponCountRef.current++;
  };

  const update = () => {
    if (gameState !== GameState.PLAYING && gameState !== GameState.VICTORY_ANIMATION) return;
    const canvas = canvasRef.current;
    if (!canvas) return;

    frameRef.current++;
    if (shakeRef.current > 0) shakeRef.current--;
    if (flashRef.current > 0) flashRef.current -= 0.02; 
    if (gameState === GameState.PLAYING) statsRef.current.duration += 1/60;

    const triggerWin = (winnerId: string) => {
        if (statsRef.current.winner) return;
        const winner = entitiesRef.current.find(e => e.id === winnerId);
        if (winner) winner.isWinner = true;
        statsRef.current.winner = winnerId === 'p1' ? 'P1' : 'P2';
        setGameState(GameState.VICTORY_ANIMATION);
        setTimeout(() => setGameState(GameState.GAME_OVER), 4000);
    };

    // === 0. 掉落物生成 ===
    if (gameState === GameState.PLAYING && 
        spawnedWeaponCountRef.current < MAX_WEAPONS_PER_GAME && 
        frameRef.current > 60 && 
        frameRef.current % WEAPON_SPAWN_INTERVAL === 0) {
        spawnFallingItem(canvas.width);
    }

    // === 1. 掉落物逻辑 ===
    fallingItemsRef.current.forEach(item => {
        item.vel.y += 0.2; 
        if (item.vel.y > 8) item.vel.y = 8;

        const prevY = item.pos.y;
        item.pos.x += item.vel.x;
        item.pos.y += item.vel.y;

        if (item.pos.y >= GROUND_Y - item.height) {
            item.pos.y = GROUND_Y - item.height;
            item.onGround = true;
            item.vel.y = -item.vel.y * 0.5;
            item.vel.x *= 0.8;
        }

        if (item.vel.y > 0) {
            PLATFORMS.forEach(plat => {
                if (item.pos.x + item.width > plat.x && item.pos.x < plat.x + plat.width) {
                    if (prevY + item.height <= plat.y && item.pos.y + item.height >= plat.y) {
                        item.pos.y = plat.y - item.height;
                        item.onGround = true;
                        item.vel.y = -item.vel.y * 0.5;
                        item.vel.x *= 0.8;
                    }
                }
            });
        }
    });

    // === 2. 投射物逻辑 (子弹、炸弹、导弹、神龙) ===
    projectilesRef.current.forEach(proj => {
        if (!proj.active) return;

        // --- 神龙逻辑 (优化动作) ---
        if (proj.type === 'dragon') {
            const dragonSegmentsCount = 20; // 增加段数，更流畅
            if (!proj.dragonSegments || proj.dragonSegments.length === 0) {
                proj.dragonSegments = Array.from({ length: dragonSegmentsCount }, () => ({ ...proj.pos }));
            }

            if (proj.dragonState === 'enter') {
                if (!proj.dragonPathProgress) proj.dragonPathProgress = 0;
                proj.dragonPathProgress += 0.02;

                shakeRef.current = 8;
                if (Math.random() < 0.1) playExplodeSound();

                const w = canvas.width;
                const h = canvas.height;
                const t = proj.dragonPathProgress * Math.PI * 2;

                // 更复杂的入场轨迹
                const targetX = w/2 + (w/2 - 50) * Math.cos(t) * Math.sin(t*0.5);
                const targetY = h/3 + (h/4) * Math.sin(2*t);

                proj.vel.x = (targetX - proj.pos.x) * 0.2;
                proj.vel.y = (targetY - proj.pos.y) * 0.2;
                proj.pos.x += proj.vel.x;
                proj.pos.y += proj.vel.y;

                if (proj.dragonPathProgress >= 1.5) {
                    proj.dragonState = 'hunt';
                    shakeRef.current = 0;
                }
            } else if (proj.dragonState === 'hunt') {
                const target = entitiesRef.current.find(e => e.id !== proj.ownerId && !e.isDead);
                if (target) {
                    const dx = target.pos.x - proj.pos.x;
                    const dy = (target.pos.y - 40) - proj.pos.y;
                    const dist = Math.sqrt(dx*dx + dy*dy);

                    const speed = 7; // 略微提速
                    // 增加一点惯性，避免转弯太生硬
                    proj.vel.x = (proj.vel.x * 20 + (dx / dist) * speed) / 21;
                    proj.vel.y = (proj.vel.y * 20 + (dy / dist) * speed) / 21;

                    proj.pos.x += proj.vel.x;
                    proj.pos.y += proj.vel.y;

                    if (dist < 50) {
                        const now = frameRef.current;
                        if (!proj.lastHitFrame || now - proj.lastHitFrame > 30) {
                            proj.lastHitFrame = now;
                            if (proj.remainingHits && proj.remainingHits > 0) {
                                proj.remainingHits--;

                                target.health -= 5;
                                target.stunFrames = 20;
                                target.vel.x = (Math.random()-0.5) * 30;
                                target.vel.y = -15;

                                playHitSound();
                                spawnParticles(target.pos.x, target.pos.y, '#FFD700', 20, 8);
                                shakeRef.current = 15;

                                if (target.health <= 0) {
                                    target.health = 0;
                                    target.isDead = true;
                                    target.isLoser = true;
                                    triggerWin(proj.ownerId);
                                }

                                if (proj.remainingHits <= 0) {
                                    proj.active = false;
                                    // 神龙离去特效
                                    spawnParticles(proj.pos.x, proj.pos.y, '#FFD700', 80, 15);
                                }
                            }
                        }
                    }
                } else {
                    proj.vel.y -= 0.5;
                    proj.pos.x += Math.sin(frameRef.current * 0.1) * 5;
                    proj.pos.y += proj.vel.y;
                    if (proj.pos.y < -300) proj.active = false;
                }
            }

            if (proj.dragonSegments && proj.dragonSegments.length > 0) {
                proj.dragonSegments[0] = { ...proj.pos };
                for (let i = 1; i < proj.dragonSegments.length; i++) {
                    const current = proj.dragonSegments[i];
                    const prev = proj.dragonSegments[i-1];
                    const dx = prev.x - current.x;
                    const dy = prev.y - current.y;
                    const d = Math.sqrt(dx*dx + dy*dy);
                    const spacing = 18; 

                    if (d > spacing) {
                        const ratio = (d - spacing) / d;
                        current.x += dx * ratio;
                        current.y += dy * ratio;
                    }
                }
            }
            return; 
        }

        // --- 巡航导弹逻辑 (东风) ---
        if (proj.type === 'missile') {
            if (frameRef.current % 2 === 0) {
                // 浓烟尾迹
                particlesRef.current.push({
                    id: Math.random().toString(),
                    pos: { x: proj.pos.x, y: proj.pos.y },
                    vel: { x: -proj.vel.x * 0.1, y: -proj.vel.y * 0.1 }, // 惯性残留
                    life: 40, maxLife: 40, color: '#aaa', size: 6, gravity: 0, growth: 0.2, alphaDecay: 0.05
                });
                // 火焰中心
                particlesRef.current.push({
                    id: Math.random().toString(),
                    pos: { x: proj.pos.x, y: proj.pos.y },
                    vel: { x: -proj.vel.x * 0.5, y: -proj.vel.y * 0.5 },
                    life: 10, maxLife: 10, color: '#ff5500', size: 4, gravity: 0
                });
            }

            const target = entitiesRef.current.find(e => e.id !== proj.ownerId && !e.isDead);
            if (target) {
                const targetX = target.pos.x;
                const targetY = target.pos.y - 35; 
                const dx = targetX - proj.pos.x;
                const dy = targetY - proj.pos.y;
                const dist = Math.sqrt(dx*dx + dy*dy);

                if (dist > 10) {
                    const speed = 8; // 导弹速度
                    // 增加追踪惯性
                    proj.vel.x = (proj.vel.x * 30 + (dx / dist) * speed) / 31;
                    proj.vel.y = (proj.vel.y * 30 + (dy / dist) * speed) / 31;
                }
            }
        }

        proj.pos.x += proj.vel.x;
        proj.pos.y += proj.vel.y;

        // --- 炸弹/原子弹落地 ---
        if (proj.type === 'bomb' || proj.type === 'atom_bomb') {
            const isNuke = proj.type === 'atom_bomb';
            proj.vel.y += GRAVITY; 
            let hitGround = false;
             if (proj.pos.y >= GROUND_Y) { hitGround = true; }
             else if (proj.vel.y > 0) {
                 PLATFORMS.forEach(plat => {
                     if (proj.pos.x > plat.x && proj.pos.x < plat.x + plat.width && 
                         proj.pos.y >= plat.y && proj.pos.y <= plat.y + 20) {
                         hitGround = true;
                     }
                 });
             }

            if (hitGround) {
                proj.active = false;

                if (isNuke) {
                    // === 核爆逻辑升级 ===
                    shakeRef.current = 120; 
                    flashRef.current = 1.0; 
                    playExplodeSound();

                    // 生成蘑菇云
                    spawnMushroomCloud(proj.pos.x, proj.pos.y - 10);

                    // 冲击波伤害范围极大
                    entitiesRef.current.forEach(target => {
                         if (!target.isDead) {
                             target.health = 0;
                             target.isDead = true;
                             target.isLoser = true;
                             // 被吹飞
                             const dir = target.pos.x - proj.pos.x > 0 ? 1 : -1;
                             target.vel.x = dir * 60;
                             target.vel.y = -60;

                             if (target.id !== proj.ownerId) {
                                 const winner = entitiesRef.current.find(e => e.id === proj.ownerId);
                                 if (winner) triggerWin(winner.id);
                             } else {
                                 const enemy = entitiesRef.current.find(e => e.id !== proj.ownerId);
                                 if (enemy) triggerWin(enemy.id);
                             }
                         }
                    });

                } else {
                    shakeRef.current = 25; 
                    playExplodeSound();
                    spawnParticles(proj.pos.x, proj.pos.y, '#ff4500', 40, 15, 2); 

                    entitiesRef.current.forEach(target => {
                        if (!target.isDead) {
                            const dist = Math.sqrt(Math.pow(target.pos.x - proj.pos.x, 2) + Math.pow(target.pos.y - proj.pos.y, 2));
                            if (dist < 180) {
                                target.health -= 25; 
                                if (target.health <= 0) { target.health = 0; target.isDead = true; target.isLoser = true; }

                                const angle = Math.atan2(target.pos.y - proj.pos.y, target.pos.x - proj.pos.x);
                                target.vel.x = Math.cos(angle) * 30;
                                target.vel.y = Math.sin(angle) * 30;
                                target.stunFrames = 30;

                                if (target.isDead) {
                                    const winner = entitiesRef.current.find(e => e.id === proj.ownerId);
                                    if (winner) triggerWin(winner.id);
                                }
                            }
                        }
                    });
                }
            }
        } else {
            // === 碰撞逻辑 (子弹 & 导弹) ===
            const isMissile = proj.type === 'missile';
            if (proj.pos.x < 0 || proj.pos.x > canvas.width || proj.pos.y > canvas.height + 100 || proj.pos.y < -200) proj.active = false;

            entitiesRef.current.forEach(target => {
                if (target.id !== proj.ownerId && !target.isDead && proj.active) {
                    const hitDist = isMissile ? 50 : 30; 
                    if (Math.abs(proj.pos.x - target.pos.x) < hitDist &&
                        proj.pos.y > target.pos.y - 75 && proj.pos.y < target.pos.y + 10) {

                        proj.active = false;
                        const damage = isMissile ? 35 : 15; // 导弹伤害增加
                        target.health -= damage; 
                        target.stunFrames = isMissile ? 40 : 10;
                        shakeRef.current = isMissile ? 25 : 5;

                        isMissile ? playExplodeSound() : playHitSound();

                        // 导弹击中特效
                        if (isMissile) {
                             spawnParticles(target.pos.x, target.pos.y - 35, '#ff5500', 40, 10);
                             spawnParticles(target.pos.x, target.pos.y - 35, '#555', 20, 5);
                        } else {
                             spawnParticles(target.pos.x, target.pos.y - 35, '#ff0000', 10, 8);
                        }

                        target.vel.x += proj.vel.x * (isMissile ? 1.2 : 0.3); 
                        target.vel.y -= isMissile ? 15 : 5;

                        if (target.health <= 0) {
                            target.health = 0; 
                            target.isDead = true;
                            target.isLoser = true;
                            target.vel.x = proj.vel.x * 0.8;
                            const winner = entitiesRef.current.find(e => e.id === proj.ownerId);
                            if (winner) triggerWin(winner.id);
                        }
                    }
                }
            });
        }
    });
    projectilesRef.current = projectilesRef.current.filter(p => p.active);

    // === 3. 实体更新 ===
    entitiesRef.current.forEach(entity => {
      // 检查武器是否过期
      if (entity.heldWeapon) {
          entity.weaponDuration--;
          if (entity.weaponDuration <= 0) {
              entity.heldWeapon = null;
              spawnParticles(entity.pos.x, entity.pos.y - 40, '#888', 5, 5); // 消失特效
          }
      }

      if (gameState === GameState.VICTORY_ANIMATION && entity.isWinner) {
          entity.isAttacking = false; entity.attackFrame = 0; entity.isCrouching = false;
          const targetX = canvas.width / 2;
          const targetY = canvas.height / 3;
          entity.pos.x += (targetX - entity.pos.x) * 0.05;
          entity.pos.y += (targetY - entity.pos.y) * 0.05;
          entity.pos.y += Math.sin(frameRef.current * 0.08) * 0.8;
          entity.vel.x = 0; entity.vel.y = 0;
          if (frameRef.current % 3 === 0) spawnConfetti(canvas.width);
          return;
      }

      // 拾取武器
      if (!entity.isDead) {
          const canPickUp = !entity.heldWeapon || entity.ammo <= 0;

          if (canPickUp) {
            const itemIndex = fallingItemsRef.current.findIndex(item => {
                const dx = Math.abs(entity.pos.x - (item.pos.x + item.width/2));
                const dy = Math.abs((entity.pos.y - 35) - (item.pos.y + item.height/2));
                return dx < 50 && dy < 60;
            });

            if (itemIndex !== -1) {
                const item = fallingItemsRef.current[itemIndex];
                entity.heldWeapon = item.type;
                entity.weaponDuration = WEAPON_LIFETIME; 
                switch(item.type) {
                    case 'pistol': entity.ammo = 6; break;
                    case 'bomb': entity.ammo = 3; break;
                    case 'stick': entity.ammo = 10; break; 
                    case 'sword': entity.ammo = 8; break;
                    case 'blade': entity.ammo = 5; break; 
                    case 'atom_bomb': entity.ammo = 1; break; 
                    case 'missile': entity.ammo = 2; break; // 导弹只有2发
                    case 'dragon': entity.ammo = 1; break; 
                }
                fallingItemsRef.current.splice(itemIndex, 1);
                playJumpSound();
                spawnParticles(entity.pos.x, entity.pos.y - 30, '#fff', 5, 5);
            }
          }
      }

      // 物理引擎
      const prevY = entity.pos.y;
      entity.vel.y += GRAVITY;

      if (!entity.isLoser && entity.stunFrames > 0) {
           entity.stunFrames--; 
           entity.vel.x *= 0.95; 
      } else if (!entity.isLoser) {
          const currentFriction = entity.isCrouching && entity.isGrounded ? 0.4 : FRICTION;
          entity.vel.x *= currentFriction;
      } else {
          entity.vel.x *= 0.99; 
      }

      entity.pos.x += entity.vel.x;
      entity.pos.y += entity.vel.y;

      // 碰撞检测
      entity.isGrounded = false;
      if (entity.pos.y >= GROUND_Y) {
          if (!entity.isLoser) {
            entity.pos.y = GROUND_Y;
            entity.vel.y = 0;
            entity.isGrounded = true;
          }
      }
      if (entity.vel.y >= 0 && !entity.isDead) {
          PLATFORMS.forEach(plat => {
              if (entity.pos.x > plat.x - 10 && entity.pos.x < plat.x + plat.width + 10) {
                  if (prevY <= plat.y && entity.pos.y >= plat.y) {
                      entity.pos.y = plat.y;
                      entity.vel.y = 0;
                      entity.isGrounded = true;
                  }
              }
          });
      }

      if (!entity.isLoser) {
        if (entity.pos.x < 10) { entity.pos.x = 10; entity.vel.x *= -0.5; }
        if (entity.pos.x > canvas.width - 10) { entity.pos.x = canvas.width - 10; entity.vel.x *= -0.5; }
      }

      if (gameState === GameState.VICTORY_ANIMATION || entity.isDead || entity.stunFrames > 0) return;

      if (entity.attackCooldown > 0) entity.attackCooldown--;
      if (entity.isAttacking) {
          entity.attackFrame++;
          if (entity.attackFrame > 15) { 
              entity.isAttacking = false;
              entity.attackFrame = 0;
          }
      }

      let moveLeft = false, moveRight = false, jump = false, crouch = false, attack = false;

      // Input P1
      if (entity.playerIndex === 0) {
        if (keysRef.current.has('KeyA')) moveLeft = true;
        if (keysRef.current.has('KeyD')) moveRight = true;
        if (keysRef.current.has('KeyW')) jump = true;
        if (keysRef.current.has('KeyS')) crouch = true;
        if (keysRef.current.has('Space')) attack = true;
      }

      // Input P2 / AI
      if (entity.playerIndex === 1) {
          if (gameMode === 'PVP') {
            if (keysRef.current.has('ArrowLeft')) moveLeft = true;
            if (keysRef.current.has('ArrowRight')) moveRight = true;
            if (keysRef.current.has('ArrowUp')) jump = true;
            if (keysRef.current.has('ArrowDown')) crouch = true;
            if (keysRef.current.has('Enter')) attack = true;
          } else {
            // AI Logic
            const p1 = entitiesRef.current.find(e => e.playerIndex === 0);
            if (p1 && !p1.isDead) {
                let targetX = p1.pos.x;
                let targetY = p1.pos.y;

                if (!entity.heldWeapon && fallingItemsRef.current.length > 0) {
                    let minDist = 9999;
                    fallingItemsRef.current.forEach(item => {
                        const d = Math.abs(item.pos.x - entity.pos.x) + Math.abs(item.pos.y - entity.pos.y);
                        if (d < minDist) {
                            minDist = d;
                            targetX = item.pos.x;
                            targetY = item.pos.y;
                        }
                    });
                }

                const distX = targetX - entity.pos.x;
                const distY = targetY - entity.pos.y; 

                if (Math.abs(distX) > 40) {
                    distX > 0 ? moveRight = true : moveLeft = true;
                } else if (!entity.heldWeapon && Math.abs(distX) < 20) {
                     distX > 0 ? moveLeft = true : moveRight = true;
                }

                if (entity.isGrounded) {
                     if (distY < -100 || (Math.random() < 0.02)) {
                         jump = true;
                     }
                }

                const absDistX = Math.abs(p1.pos.x - entity.pos.x);
                entity.facingRight = (p1.pos.x - entity.pos.x) > 0;

                // AI 攻击逻辑
                let attackRange = ATTACK_RANGE;
                if (entity.heldWeapon === 'stick') attackRange = 200;
                if (entity.heldWeapon === 'pistol') attackRange = 600;
                if (entity.heldWeapon === 'atom_bomb') attackRange = 300; 
                if (entity.heldWeapon === 'missile') attackRange = 700; 
                if (entity.heldWeapon === 'dragon') attackRange = 400; 

                if (absDistX < attackRange && Math.abs(p1.pos.y - entity.pos.y) < 100) {
                    if (entity.attackCooldown === 0 && Math.random() < 0.05) attack = true;
                }
            }
          }
      }

      entity.isCrouching = crouch && entity.isGrounded;
      if (!entity.isCrouching) {
          if (moveLeft) { entity.vel.x -= MOVE_SPEED; entity.facingRight = false; }
          if (moveRight) { entity.vel.x += MOVE_SPEED; entity.facingRight = true; }
      }
      if (jump && entity.isGrounded && !entity.isCrouching) {
          entity.vel.y = JUMP_FORCE;
          playJumpSound();
      }

      // === 攻击处理 ===
      if (attack && entity.attackCooldown === 0) {
          entity.attackCooldown = ATTACK_COOLDOWN;
          entity.isAttacking = true;
          entity.attackFrame = 5;

          if (entity.heldWeapon === 'pistol') {
              playShootSound();
              entity.vel.x += entity.facingRight ? -8 : 8;
              entity.vel.y -= 2;

              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'pistol',
                  pos: { x: entity.pos.x + (entity.facingRight ? 40 : -40), y: entity.pos.y - 45 },
                  vel: { x: entity.facingRight ? 20 : -20, y: (Math.random()-0.5) * 2 }, 
                  ownerId: entity.id,
                  width: 12, height: 4, active: true
              });
              entity.ammo--;
          } else if (entity.heldWeapon === 'bomb') {
              entity.vel.x += entity.facingRight ? -2 : 2;
              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'bomb',
                  pos: { x: entity.pos.x, y: entity.pos.y - 60 },
                  vel: { x: entity.facingRight ? 12 : -12, y: -12 },
                  ownerId: entity.id,
                  width: 20, height: 20, active: true
              });
              entity.ammo--;
          } else if (entity.heldWeapon === 'atom_bomb') {
              entity.vel.x += entity.facingRight ? -4 : 4;
              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'atom_bomb',
                  pos: { x: entity.pos.x, y: entity.pos.y - 70 },
                  vel: { x: entity.facingRight ? 8 : -8, y: -10 },
                  ownerId: entity.id,
                  width: 30, height: 40, active: true
              });
              entity.ammo--; 
          } else if (entity.heldWeapon === 'missile') {
              playShootSound(); 
              entity.vel.x += entity.facingRight ? -10 : 10; 
              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'missile',
                  pos: { x: entity.pos.x + (entity.facingRight ? 50 : -50), y: entity.pos.y - 50 },
                  vel: { x: entity.facingRight ? 10 : -10, y: -5 }, 
                  ownerId: entity.id,
                  width: 20, height: 8, active: true
              });
              entity.ammo--; 
          } else if (entity.heldWeapon === 'dragon') {
              playDragonRoar();
              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'dragon',
                  pos: { x: entity.pos.x, y: entity.pos.y - 100 },
                  vel: { x: 0, y: 0 },
                  ownerId: entity.id,
                  width: 40, height: 40, active: true,
                  dragonState: 'enter', 
                  remainingHits: 5,
                  dragonPathProgress: 0,
                  dragonSegments: undefined
              });
              entity.ammo--;
          } else {
              // == 近战武器 ==
              playAttackSound();

              let range = ATTACK_RANGE;
              let dmg = ATTACK_DAMAGE;
              let knockbackX = 15;
              let knockbackY = -8;
              let selfPush = 10;
              let hitEffectSize = 12;

              if (entity.heldWeapon === 'stick') {
                  range = 220; dmg = 12; knockbackX = 20; selfPush = 5; hitEffectSize = 15;
              } else if (entity.heldWeapon === 'sword') {
                  range = 140; dmg = 15; knockbackX = 12; selfPush = 12; entity.attackCooldown = 20; 
              } else if (entity.heldWeapon === 'blade') {
                  range = 160; dmg = 25; knockbackX = 25; knockbackY = -12; selfPush = 2; entity.attackCooldown = 50; 
              }

              entity.vel.x = entity.facingRight ? selfPush : -selfPush;

              const hitX = entity.facingRight ? entity.pos.x + range/2 : entity.pos.x - range/2;
              const hitY = entity.isCrouching ? entity.pos.y - 20 : entity.pos.y - 45;

              let hitSomething = false;

              entitiesRef.current.forEach(target => {
                  if (target !== entity && !target.isDead) {
                      const dy = (target.pos.y - 35) - hitY;
                      if (Math.abs(target.pos.x - entity.pos.x) < range && Math.abs(dy) < 60 && 
                          ((entity.facingRight && target.pos.x > entity.pos.x) || (!entity.facingRight && target.pos.x < entity.pos.x))) {

                          if (!entity.isCrouching && target.isCrouching) {
                              spawnParticles(target.pos.x, target.pos.y - 40, '#aaa', 2, 2);
                              return; 
                          }

                          target.health -= dmg;
                          hitSomething = true;

                          target.vel.x = entity.facingRight ? knockbackX : -knockbackX; 
                          target.vel.y = knockbackY; 
                          target.stunFrames = 20; 

                          shakeRef.current = Math.floor(dmg / 2);
                          spawnParticles(target.pos.x, target.pos.y - 40, target.color, hitEffectSize, 10);
                          playHitSound();

                          if (target.health <= 0) {
                              target.health = 0;
                              target.isDead = true;
                              target.isLoser = true;
                              target.vel.x = entity.facingRight ? 30 : -30;
                              target.vel.y = -20;
                              triggerWin(entity.id);
                          }
                      }
                  }
              });

              if (hitSomething && entity.heldWeapon) {
                  entity.ammo--;
              }
          }

          // 弹药耗尽检查
          if (entity.heldWeapon && entity.ammo <= 0) {
              entity.heldWeapon = null;
              spawnParticles(entity.pos.x, entity.pos.y - 40, '#888', 5, 5); 
          }
      }
    });

    particlesRef.current.forEach(p => {
        p.life--;
        p.pos.x += p.vel.x;
        p.pos.y += p.vel.y;
        if (p.gravity) p.vel.y += p.gravity;

        if (p.growth) { p.size += p.growth; }
        if (p.alphaDecay) {
            p.currentAlpha = p.currentAlpha !== undefined ? p.currentAlpha - p.alphaDecay : 1.0;
        }
    });
    particlesRef.current = particlesRef.current.filter(p => p.life > 0 && (p.currentAlpha === undefined || p.currentAlpha > 0));
  };

  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Shake logic
    let shakeX = 0;
    let shakeY = 0;
    if (shakeRef.current > 0) {
        const magnitude = shakeRef.current;
        shakeX = (Math.random() - 0.5) * magnitude;
        shakeY = (Math.random() - 0.5) * magnitude;
    }

    ctx.save();
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Apply Shake
    ctx.translate(shakeX, shakeY);

    // Draw Platforms
    ctx.fillStyle = '#334155'; // Slate-700
    PLATFORMS.forEach(plat => {
        ctx.fillRect(plat.x, plat.y, plat.width, plat.height);
        // Highlight top
        ctx.fillStyle = '#475569';
        ctx.fillRect(plat.x, plat.y, plat.width, 4);
        ctx.fillStyle = '#334155';
    });

    // Ground
    ctx.fillStyle = '#1e293b'; // Slate-800
    ctx.fillRect(0, GROUND_Y, canvas.width, canvas.height - GROUND_Y);
    // Ground Line
    ctx.beginPath();
    ctx.strokeStyle = '#334155';
    ctx.lineWidth = 2;
    ctx.moveTo(0, GROUND_Y);
    ctx.lineTo(canvas.width, GROUND_Y);
    ctx.stroke();

    // Draw Falling Items
    fallingItemsRef.current.forEach(item => {
        ctx.save();
        ctx.translate(item.pos.x + item.width/2, item.pos.y + item.height/2);
        // Simple item box
        ctx.fillStyle = '#4f46e5'; // Indigo
        ctx.fillRect(-item.width/2, -item.height/2, item.width, item.height);
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2;
        ctx.strokeRect(-item.width/2, -item.height/2, item.width, item.height);

        // Icon
        ctx.fillStyle = '#fff';
        ctx.font = '16px Arial';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        let icon = '?';
        switch(item.type) {
            case 'pistol': icon = '🔫'; break;
            case 'bomb': icon = '💣'; break;
            case 'atom_bomb': icon = '☢️'; break;
            case 'missile': icon = '🚀'; break;
            case 'dragon': icon = '🐉'; break;
            case 'stick': icon = '🦯'; break;
            case 'sword': icon = '🗡️'; break;
            case 'blade': icon = '🔪'; break;
        }
        ctx.fillText(icon, 0, 0);
        ctx.restore();
    });

    // Draw Entities
    entitiesRef.current.forEach(entity => {
        if (!entity.isDead || entity.isLoser) { 
            drawEntity(ctx, entity);
        }
    });

    // Draw Projectiles
    projectilesRef.current.forEach(proj => {
        ctx.save();
        ctx.translate(proj.pos.x, proj.pos.y);

        if (proj.type === 'dragon') {
            // Head
            ctx.fillStyle = '#FFD700';
            ctx.beginPath();
            ctx.arc(0, 0, 20, 0, Math.PI * 2);
            ctx.fill();
            ctx.fillStyle = 'red';
            ctx.beginPath();
            ctx.arc(8, -5, 5, 0, Math.PI * 2);
            ctx.fill();
        } else if (proj.type === 'missile') {
            const angle = Math.atan2(proj.vel.y, proj.vel.x);
            ctx.rotate(angle);
            ctx.fillStyle = '#333';
            ctx.fillRect(-10, -5, 20, 10);
            ctx.fillStyle = 'red';
            ctx.fillRect(10, -5, 5, 10);
            ctx.fillStyle = '#555';
            ctx.beginPath();
            ctx.moveTo(-10, -5); ctx.lineTo(-15, -10); ctx.lineTo(-5, -5);
            ctx.fill();
            ctx.beginPath();
            ctx.moveTo(-10, 5); ctx.lineTo(-15, 10); ctx.lineTo(-5, 5);
            ctx.fill();
        } else if (proj.type === 'bomb' || proj.type === 'atom_bomb') {
             ctx.fillStyle = '#000';
             ctx.beginPath();
             ctx.arc(0, 0, proj.width/2, 0, Math.PI * 2);
             ctx.fill();
             if (Math.random() > 0.5) {
                 ctx.fillStyle = 'orange';
                 ctx.fillRect(proj.width/2, -proj.height/2 - 5, 4, 4);
             }
        } else {
            // Bullet
            ctx.fillStyle = '#fff';
            ctx.fillRect(-proj.width/2, -proj.height/2, proj.width, proj.height);
        }
        ctx.restore();

        // Dragon segments
        if (proj.type === 'dragon' && proj.dragonSegments) {
             proj.dragonSegments.forEach((seg, i) => {
                 ctx.beginPath();
                 const size = 15 - i * 0.5;
                 ctx.fillStyle = `rgba(255, 215, 0, ${1 - i/25})`;
                 ctx.arc(seg.x, seg.y, Math.max(2, size), 0, Math.PI * 2);
                 ctx.fill();
             });
        }
    });

    // Draw Particles
    particlesRef.current.forEach(p => {
      ctx.save();
      ctx.fillStyle = p.color;
      const alpha = p.currentAlpha !== undefined ? p.currentAlpha : (p.life / p.maxLife);
      ctx.globalAlpha = alpha;
      ctx.beginPath(); 
      ctx.arc(p.pos.x, p.pos.y, p.size, 0, Math.PI * 2); 
      ctx.fill();
      ctx.restore();
    });

    ctx.restore();

    // Flash (Screen Space)
    if (flashRef.current > 0) {
      ctx.save();
      ctx.fillStyle = `rgba(255, 255, 255, ${Math.min(1, flashRef.current)})`;
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.restore();
    }
  };

  const tick = () => {
    update();
    draw();
    requestRef.current = requestAnimationFrame(tick);
  };

  useEffect(() => {
    if (canvasRef.current) {
        canvasRef.current.width = window.innerWidth;
        canvasRef.current.height = window.innerHeight;
    }
    requestRef.current = requestAnimationFrame(tick);
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [gameState]);

  return (
    <canvas 
        ref={canvasRef} 
        className="block w-full h-full bg-slate-900"
    />
  );
};

export default GameCanvas;

import React, { useRef, useEffect, useCallback } from 'react';
import { GameState, Entity, Vector, Particle, GameStats, GameMode, FallingItem, Projectile, WeaponType, Platform } from '../types';
import { playJumpSound, playAttackSound, playHitSound, playShootSound, playExplodeSound, playDragonRoar } from '../services/audioService';

interface GameCanvasProps {
  gameState: GameState;
  setGameState: (state: GameState) => void;
  setStats: React.Dispatch<React.SetStateAction<GameStats>>;
  setPlayers: (players: Entity[]) => void;
  gameMode: GameMode;
}

// === 物理参数 (提速版) ===
const GRAVITY = 0.8; // 重力增加，下落更快，跳跃手感更干脆
const FRICTION = 0.82; // 摩擦力减小，保留一定惯性但更可控
const MOVE_SPEED = 2; // 移动加速度调整
const JUMP_FORCE = -22; // 跳跃力度增加 (原 -16)
const GROUND_Y = 600;
const ATTACK_COOLDOWN = 18; // 攻击冷却缩短 (原 30)，连招更爽快
const ATTACK_RANGE = 100;
const ATTACK_DAMAGE = 8;

// === 武器生成配置 ===
const MAX_WEAPONS_PER_GAME = 6; 
const WEAPON_SPAWN_INTERVAL = 900; 
const WEAPON_LIFETIME = 15 * 60; 

// === 关卡设计 ===
const PLATFORMS: Platform[] = [
    { x: 300, y: 450, width: 200, height: 20 },
    { x: 800, y: 450, width: 200, height: 20 },
    { x: 500, y: 250, width: 300, height: 20 } 
];

const drawEntity = (ctx: CanvasRenderingContext2D, entity: Entity) => {
    ctx.save();

    const centerX = entity.pos.x;
    const centerY = entity.pos.y; // Feet position

    ctx.translate(centerX, centerY);

    if (entity.isDead) {
         ctx.rotate(Math.PI / 2 * (entity.facingRight ? 1 : -1));
         ctx.translate(0, -10);
    }

    if (!entity.facingRight) ctx.scale(-1, 1);

    // Draw body
    ctx.fillStyle = entity.color;
    ctx.strokeStyle = entity.color;
    ctx.lineWidth = 4;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    const crouchOffset = entity.isCrouching ? 20 : 0;

    // Head
    ctx.beginPath();
    ctx.arc(0, -entity.height + 20 + crouchOffset, 12, 0, Math.PI * 2);
    ctx.fill();

    // Body
    ctx.beginPath();
    ctx.moveTo(0, -entity.height + 32 + crouchOffset);
    ctx.lineTo(0, -25 + crouchOffset);
    ctx.stroke();

    // Legs
    ctx.beginPath();
    ctx.moveTo(0, -25 + crouchOffset);
    if (entity.isCrouching) {
        ctx.lineTo(-15, -5);
        ctx.moveTo(0, -25 + crouchOffset);
        ctx.lineTo(15, -5);
    } else if (Math.abs(entity.vel.x) > 0.1 && entity.isGrounded) {
        const walkCycle = Math.sin(Date.now() / 100) * 10;
        ctx.lineTo(-10 + walkCycle, 0);
        ctx.moveTo(0, -25 + crouchOffset);
        ctx.lineTo(10 - walkCycle, 0);
    } else {
        ctx.lineTo(-10, 0);
        ctx.moveTo(0, -25 + crouchOffset);
        ctx.lineTo(10, 0);
    }
    ctx.stroke();

    // Arms
    ctx.beginPath();
    const shoulderY = -entity.height + 40 + crouchOffset;
    ctx.moveTo(0, shoulderY);

    if (entity.isWinner) {
        ctx.lineTo(-20, shoulderY - 30);
        ctx.moveTo(0, shoulderY);
        ctx.lineTo(20, shoulderY - 30);
    } else if (entity.isAttacking) {
        const attackProgress = entity.attackFrame / 15;
        ctx.lineTo(25, shoulderY - 10 + attackProgress * 20);
    } else if (entity.heldWeapon) {
        ctx.lineTo(15, shoulderY + 5);

        ctx.save();
        ctx.translate(15, shoulderY + 5);

        if (entity.heldWeapon === 'pistol') {
            ctx.fillStyle = '#555';
            ctx.fillRect(0, -5, 15, 5);
            ctx.fillRect(0, 0, 5, 5);
        } else if (entity.heldWeapon === 'sword') {
            ctx.fillStyle = '#ccc';
            ctx.fillRect(0, -25, 4, 30);
            ctx.fillStyle = '#8B4513';
            ctx.fillRect(-3, 0, 10, 2);
        } else if (entity.heldWeapon === 'stick') {
            ctx.fillStyle = '#8B4513';
            ctx.rotate(-Math.PI / 4);
            ctx.fillRect(0, -40, 4, 50);
        } else if (entity.heldWeapon === 'blade') {
            ctx.fillStyle = '#777';
            ctx.beginPath();
            ctx.moveTo(0,0);
            ctx.lineTo(30, -10);
            ctx.lineTo(25, 5);
            ctx.fill();
        } else if (entity.heldWeapon === 'bomb' || entity.heldWeapon === 'atom_bomb') {
            ctx.fillStyle = '#000';
            ctx.beginPath();
            ctx.arc(5, 0, 8, 0, Math.PI*2);
            ctx.fill();
            ctx.strokeStyle = '#fff';
            ctx.beginPath();
            ctx.moveTo(5, -8);
            ctx.quadraticCurveTo(10, -15, 15, -10);
            ctx.stroke();
             if (entity.heldWeapon === 'atom_bomb') {
                ctx.fillStyle = 'yellow';
                ctx.font = '10px Arial';
                ctx.fillText('☢', 2, 4);
            }
        } else if (entity.heldWeapon === 'missile') {
             ctx.fillStyle = 'green';
             ctx.fillRect(0, -5, 20, 10);
             ctx.fillStyle = 'red';
             ctx.fillRect(20, -5, 5, 10);
        } else if (entity.heldWeapon === 'dragon') {
             ctx.font = '20px serif';
             ctx.fillText('🐉', 0, 5);
        }
        ctx.restore();

    } else {
        if (Math.abs(entity.vel.x) > 0.1) {
             const armCycle = Math.cos(Date.now() / 100) * 10;
             ctx.lineTo(armCycle, shoulderY + 15);
        } else {
             ctx.lineTo(0, shoulderY + 20);
        }
    }
    ctx.stroke();

    ctx.restore();
};

const GameCanvas: React.FC<GameCanvasProps> = ({ gameState, setGameState, setStats, setPlayers, gameMode }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();
  const frameRef = useRef<number>(0);

  const entitiesRef = useRef<Entity[]>([]);
  const particlesRef = useRef<Particle[]>([]);
  const fallingItemsRef = useRef<FallingItem[]>([]);
  const projectilesRef = useRef<Projectile[]>([]);

  // 武器生成控制
  const spawnedWeaponCountRef = useRef<number>(0); 
  const atomBombIndexRef = useRef<number>(-1); 
  const missileIndexRef = useRef<number>(-1); 
  const dragonIndexRef = useRef<number>(-1); 

  const keysRef = useRef<Set<string>>(new Set());
  const statsRef = useRef<GameStats>({ winner: null, mode: gameMode, duration: 0 });
  const shakeRef = useRef<number>(0);
  const flashRef = useRef<number>(0); 

  // 初始化对决
  const initGame = useCallback(() => {
    const newEntities: Entity[] = [];

    // P1 (左侧)
    newEntities.push({
      id: 'p1', type: 'player', playerIndex: 0,
      pos: { x: 100, y: 100 }, vel: { x: 0, y: 0 }, 
      width: 40, height: 70, color: '#3b82f6', 
      isGrounded: false, isCrouching: false, health: 100, maxHealth: 100, isDead: false,
      facingRight: true, attackCooldown: 0, isAttacking: false, attackFrame: 0,
      heldWeapon: null, ammo: 0, weaponDuration: 0, stunFrames: 0
    });

    // P2/CPU (右侧)
    newEntities.push({
      id: 'p2', type: 'player', playerIndex: 1,
      pos: { x: window.innerWidth - 100, y: 100 }, vel: { x: 0, y: 0 },
      width: 40, height: 70, color: '#facc15',
      isGrounded: false, isCrouching: false, health: 100, maxHealth: 100, isDead: false,
      facingRight: false, attackCooldown: 0, isAttacking: false, attackFrame: 0,
      heldWeapon: null, ammo: 0, weaponDuration: 0, stunFrames: 0
    });

    entitiesRef.current = newEntities;
    particlesRef.current = [];
    fallingItemsRef.current = [];
    projectilesRef.current = [];
    spawnedWeaponCountRef.current = 0; 

    const indices = Array.from({length: MAX_WEAPONS_PER_GAME}, (_, i) => i);
    for (let i = indices.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [indices[i], indices[j]] = [indices[j], indices[i]];
    }

    atomBombIndexRef.current = indices[0];
    missileIndexRef.current = indices[1];
    dragonIndexRef.current = indices[2]; 

    statsRef.current = { winner: null, mode: gameMode, duration: 0 };
    frameRef.current = 0;
    shakeRef.current = 0;
    flashRef.current = 0;

    setStats(statsRef.current);
    setPlayers([...entitiesRef.current]);
  }, [gameMode, setStats, setPlayers]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        if (e.repeat) return;
        keysRef.current.add(e.code);
        if (e.code === 'KeyR' && gameState === GameState.GAME_OVER) {
             setGameState(GameState.PLAYING);
        }
    };
    const handleKeyUp = (e: KeyboardEvent) => keysRef.current.delete(e.code);
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, [gameState, setGameState]);

  useEffect(() => {
    if (gameState === GameState.PLAYING) {
      initGame();
    }
  }, [gameState, initGame]);

  const spawnParticles = (x: number, y: number, color: string, count: number, speed = 8, lifeMultiplier = 1) => {
      for(let i=0; i<count; i++) {
          particlesRef.current.push({
              id: Math.random().toString(),
              pos: {x, y},
              vel: { x: (Math.random() - 0.5) * speed, y: (Math.random() - 0.5) * speed },
              life: (20 + Math.random() * 20) * lifeMultiplier,
              maxLife: 40 * lifeMultiplier,
              color: color,
              size: Math.random() * 6 + 3,
              gravity: 0.5 
          });
      }
  };

  const spawnMushroomCloud = (x: number, y: number) => {
    // 1. 蘑菇柄 (上升的烟柱)
    for (let i = 0; i < 20; i++) {
      particlesRef.current.push({
        id: Math.random().toString(),
        pos: { x: x + (Math.random()-0.5)*20, y: y },
        vel: { x: (Math.random()-0.5) * 1, y: -2 - Math.random() * 3 },
        life: 180,
        maxLife: 180,
        color: i % 2 === 0 ? '#555' : '#333',
        size: 15 + Math.random() * 10,
        gravity: -0.05, // 轻微上升
        growth: 0.3, // 膨胀
        alphaDecay: 0.005,
        currentAlpha: 0.8
      });
    }

    // 2. 蘑菇盖 (顶部扩散)
    for (let i = 0; i < 40; i++) {
      const angle = (Math.PI / 40) * i * 2; // 360度
      const speed = 2 + Math.random() * 3;
      particlesRef.current.push({
        id: Math.random().toString(),
        pos: { x: x, y: y - 80 },
        vel: { x: Math.cos(angle) * speed, y: Math.sin(angle) * speed * 0.5 - 1 },
        life: 200,
        maxLife: 200,
        color: Math.random() > 0.5 ? '#ff4500' : '#ff8800', // 橙红火光
        size: 20 + Math.random() * 10,
        gravity: -0.02,
        growth: 0.5, // 快速膨胀
        alphaDecay: 0.008,
        currentAlpha: 0.9
      });
    }

    // 3. 底部冲击波 (贴地尘土)
    for (let i = 0; i < 30; i++) {
        const dir = i % 2 === 0 ? 1 : -1;
        particlesRef.current.push({
            id: Math.random().toString(),
            pos: { x: x, y: y },
            vel: { x: dir * (5 + Math.random()*10), y: -1 },
            life: 100, maxLife: 100,
            color: '#777',
            size: 10,
            gravity: 0,
            growth: 0.8,
            alphaDecay: 0.02,
            currentAlpha: 0.6
        });
    }
  };

  const spawnConfetti = (width: number) => {
      const colors = ['#FFD700', '#FF6347', '#00BFFF', '#32CD32', '#FF69B4', '#FFFFFF'];
      const x = Math.random() * width;
      const y = -10; 
      const color = colors[Math.floor(Math.random() * colors.length)];
      particlesRef.current.push({
          id: Math.random().toString(),
          pos: { x, y },
          vel: { x: (Math.random() - 0.5) * 2, y: Math.random() * 2 + 1 },
          life: 200, maxLife: 200, color, size: Math.random() * 4 + 3, gravity: 0.02 
      });
  };

  const spawnFallingItem = (canvasWidth: number) => {
      let type: WeaponType;

      const count = spawnedWeaponCountRef.current;

      if (count === atomBombIndexRef.current) {
          type = 'atom_bomb';
      } else if (count === missileIndexRef.current) {
          type = 'missile';
      } else if (count === dragonIndexRef.current) {
          type = 'dragon';
      } else {
          const normalPool: WeaponType[] = ['pistol', 'bomb', 'stick', 'sword', 'blade'];
          type = normalPool[Math.floor(Math.random() * normalPool.length)];
      }

      fallingItemsRef.current.push({
          id: Math.random().toString() + "_" + Date.now(),
          type,
          pos: { x: 100 + Math.random() * (canvasWidth - 200), y: -50 },
          vel: { x: (Math.random() - 0.5) * 2, y: 2 },
          width: 30, height: 30,
          onGround: false
      });
      spawnedWeaponCountRef.current++;
  };

  const update = () => {
    if (gameState !== GameState.PLAYING && gameState !== GameState.VICTORY_ANIMATION) return;
    const canvas = canvasRef.current;
    if (!canvas) return;

    frameRef.current++;
    if (shakeRef.current > 0) shakeRef.current--;
    if (flashRef.current > 0) flashRef.current -= 0.02; 
    if (gameState === GameState.PLAYING) statsRef.current.duration += 1/60;

    const triggerWin = (winnerId: string) => {
        if (statsRef.current.winner) return;
        const winner = entitiesRef.current.find(e => e.id === winnerId);
        if (winner) winner.isWinner = true;
        statsRef.current.winner = winnerId === 'p1' ? 'P1' : 'P2';
        setGameState(GameState.VICTORY_ANIMATION);
        setTimeout(() => setGameState(GameState.GAME_OVER), 4000);
    };

    // === 0. 掉落物生成 ===
    if (gameState === GameState.PLAYING && 
        spawnedWeaponCountRef.current < MAX_WEAPONS_PER_GAME && 
        frameRef.current > 60 && 
        frameRef.current % WEAPON_SPAWN_INTERVAL === 0) {
        spawnFallingItem(canvas.width);
    }

    // === 1. 掉落物逻辑 ===
    fallingItemsRef.current.forEach(item => {
        item.vel.y += 0.2; 
        if (item.vel.y > 8) item.vel.y = 8;

        const prevY = item.pos.y;
        item.pos.x += item.vel.x;
        item.pos.y += item.vel.y;

        if (item.pos.y >= GROUND_Y - item.height) {
            item.pos.y = GROUND_Y - item.height;
            item.onGround = true;
            item.vel.y = -item.vel.y * 0.5;
            item.vel.x *= 0.8;
        }

        if (item.vel.y > 0) {
            PLATFORMS.forEach(plat => {
                if (item.pos.x + item.width > plat.x && item.pos.x < plat.x + plat.width) {
                    if (prevY + item.height <= plat.y && item.pos.y + item.height >= plat.y) {
                        item.pos.y = plat.y - item.height;
                        item.onGround = true;
                        item.vel.y = -item.vel.y * 0.5;
                        item.vel.x *= 0.8;
                    }
                }
            });
        }
    });

    // === 2. 投射物逻辑 (子弹、炸弹、导弹、神龙) ===
    projectilesRef.current.forEach(proj => {
        if (!proj.active) return;

        // --- 神龙逻辑 (优化动作) ---
        if (proj.type === 'dragon') {
            const dragonSegmentsCount = 20; // 增加段数，更流畅
            if (!proj.dragonSegments || proj.dragonSegments.length === 0) {
                proj.dragonSegments = Array.from({ length: dragonSegmentsCount }, () => ({ ...proj.pos }));
            }

            if (proj.dragonState === 'enter') {
                if (!proj.dragonPathProgress) proj.dragonPathProgress = 0;
                proj.dragonPathProgress += 0.02;

                shakeRef.current = 8;
                if (Math.random() < 0.1) playExplodeSound();

                const w = canvas.width;
                const h = canvas.height;
                const t = proj.dragonPathProgress * Math.PI * 2;

                // 更复杂的入场轨迹
                const targetX = w/2 + (w/2 - 50) * Math.cos(t) * Math.sin(t*0.5);
                const targetY = h/3 + (h/4) * Math.sin(2*t);

                proj.vel.x = (targetX - proj.pos.x) * 0.2;
                proj.vel.y = (targetY - proj.pos.y) * 0.2;
                proj.pos.x += proj.vel.x;
                proj.pos.y += proj.vel.y;

                if (proj.dragonPathProgress >= 1.5) {
                    proj.dragonState = 'hunt';
                    shakeRef.current = 0;
                }
            } else if (proj.dragonState === 'hunt') {
                const target = entitiesRef.current.find(e => e.id !== proj.ownerId && !e.isDead);
                if (target) {
                    const dx = target.pos.x - proj.pos.x;
                    const dy = (target.pos.y - 40) - proj.pos.y;
                    const dist = Math.sqrt(dx*dx + dy*dy);

                    const speed = 7; // 略微提速
                    // 增加一点惯性，避免转弯太生硬
                    proj.vel.x = (proj.vel.x * 20 + (dx / dist) * speed) / 21;
                    proj.vel.y = (proj.vel.y * 20 + (dy / dist) * speed) / 21;

                    proj.pos.x += proj.vel.x;
                    proj.pos.y += proj.vel.y;

                    if (dist < 50) {
                        const now = frameRef.current;
                        if (!proj.lastHitFrame || now - proj.lastHitFrame > 30) {
                            proj.lastHitFrame = now;
                            if (proj.remainingHits && proj.remainingHits > 0) {
                                proj.remainingHits--;

                                target.health -= 5;
                                target.stunFrames = 20;
                                target.vel.x = (Math.random()-0.5) * 30;
                                target.vel.y = -15;

                                playHitSound();
                                spawnParticles(target.pos.x, target.pos.y, '#FFD700', 20, 8);
                                shakeRef.current = 15;

                                if (target.health <= 0) {
                                    target.health = 0;
                                    target.isDead = true;
                                    target.isLoser = true;
                                    triggerWin(proj.ownerId);
                                }

                                if (proj.remainingHits <= 0) {
                                    proj.active = false;
                                    // 神龙离去特效
                                    spawnParticles(proj.pos.x, proj.pos.y, '#FFD700', 80, 15);
                                }
                            }
                        }
                    }
                } else {
                    proj.vel.y -= 0.5;
                    proj.pos.x += Math.sin(frameRef.current * 0.1) * 5;
                    proj.pos.y += proj.vel.y;
                    if (proj.pos.y < -300) proj.active = false;
                }
            }

            if (proj.dragonSegments && proj.dragonSegments.length > 0) {
                proj.dragonSegments[0] = { ...proj.pos };
                for (let i = 1; i < proj.dragonSegments.length; i++) {
                    const current = proj.dragonSegments[i];
                    const prev = proj.dragonSegments[i-1];
                    const dx = prev.x - current.x;
                    const dy = prev.y - current.y;
                    const d = Math.sqrt(dx*dx + dy*dy);
                    const spacing = 18; 

                    if (d > spacing) {
                        const ratio = (d - spacing) / d;
                        current.x += dx * ratio;
                        current.y += dy * ratio;
                    }
                }
            }
            return; 
        }

        // --- 巡航导弹逻辑 (东风) ---
        if (proj.type === 'missile') {
            if (frameRef.current % 2 === 0) {
                // 浓烟尾迹
                particlesRef.current.push({
                    id: Math.random().toString(),
                    pos: { x: proj.pos.x, y: proj.pos.y },
                    vel: { x: -proj.vel.x * 0.1, y: -proj.vel.y * 0.1 }, // 惯性残留
                    life: 40, maxLife: 40, color: '#aaa', size: 6, gravity: 0, growth: 0.2, alphaDecay: 0.05
                });
                // 火焰中心
                particlesRef.current.push({
                    id: Math.random().toString(),
                    pos: { x: proj.pos.x, y: proj.pos.y },
                    vel: { x: -proj.vel.x * 0.5, y: -proj.vel.y * 0.5 },
                    life: 10, maxLife: 10, color: '#ff5500', size: 4, gravity: 0
                });
            }

            const target = entitiesRef.current.find(e => e.id !== proj.ownerId && !e.isDead);
            if (target) {
                const targetX = target.pos.x;
                const targetY = target.pos.y - 35; 
                const dx = targetX - proj.pos.x;
                const dy = targetY - proj.pos.y;
                const dist = Math.sqrt(dx*dx + dy*dy);

                if (dist > 10) {
                    const speed = 8; // 导弹速度
                    // 增加追踪惯性
                    proj.vel.x = (proj.vel.x * 30 + (dx / dist) * speed) / 31;
                    proj.vel.y = (proj.vel.y * 30 + (dy / dist) * speed) / 31;
                }
            }
        }

        proj.pos.x += proj.vel.x;
        proj.pos.y += proj.vel.y;

        // --- 炸弹/原子弹落地 ---
        if (proj.type === 'bomb' || proj.type === 'atom_bomb') {
            const isNuke = proj.type === 'atom_bomb';
            proj.vel.y += GRAVITY; 
            let hitGround = false;
             if (proj.pos.y >= GROUND_Y) { hitGround = true; }
             else if (proj.vel.y > 0) {
                 PLATFORMS.forEach(plat => {
                     if (proj.pos.x > plat.x && proj.pos.x < plat.x + plat.width && 
                         proj.pos.y >= plat.y && proj.pos.y <= plat.y + 20) {
                         hitGround = true;
                     }
                 });
             }

            if (hitGround) {
                proj.active = false;

                if (isNuke) {
                    // === 核爆逻辑升级 ===
                    shakeRef.current = 120; 
                    flashRef.current = 1.0; 
                    playExplodeSound();

                    // 生成蘑菇云
                    spawnMushroomCloud(proj.pos.x, proj.pos.y - 10);

                    // 冲击波伤害范围极大
                    entitiesRef.current.forEach(target => {
                         if (!target.isDead) {
                             target.health = 0;
                             target.isDead = true;
                             target.isLoser = true;
                             // 被吹飞
                             const dir = target.pos.x - proj.pos.x > 0 ? 1 : -1;
                             target.vel.x = dir * 60;
                             target.vel.y = -60;

                             if (target.id !== proj.ownerId) {
                                 const winner = entitiesRef.current.find(e => e.id === proj.ownerId);
                                 if (winner) triggerWin(winner.id);
                             } else {
                                 const enemy = entitiesRef.current.find(e => e.id !== proj.ownerId);
                                 if (enemy) triggerWin(enemy.id);
                             }
                         }
                    });

                } else {
                    shakeRef.current = 25; 
                    playExplodeSound();
                    spawnParticles(proj.pos.x, proj.pos.y, '#ff4500', 40, 15, 2); 

                    entitiesRef.current.forEach(target => {
                        if (!target.isDead) {
                            const dist = Math.sqrt(Math.pow(target.pos.x - proj.pos.x, 2) + Math.pow(target.pos.y - proj.pos.y, 2));
                            if (dist < 180) {
                                target.health -= 25; 
                                if (target.health <= 0) { target.health = 0; target.isDead = true; target.isLoser = true; }

                                const angle = Math.atan2(target.pos.y - proj.pos.y, target.pos.x - proj.pos.x);
                                target.vel.x = Math.cos(angle) * 30;
                                target.vel.y = Math.sin(angle) * 30;
                                target.stunFrames = 30;

                                if (target.isDead) {
                                    const winner = entitiesRef.current.find(e => e.id === proj.ownerId);
                                    if (winner) triggerWin(winner.id);
                                }
                            }
                        }
                    });
                }
            }
        } else {
            // === 碰撞逻辑 (子弹 & 导弹) ===
            const isMissile = proj.type === 'missile';
            if (proj.pos.x < 0 || proj.pos.x > canvas.width || proj.pos.y > canvas.height + 100 || proj.pos.y < -200) proj.active = false;

            entitiesRef.current.forEach(target => {
                if (target.id !== proj.ownerId && !target.isDead && proj.active) {
                    const hitDist = isMissile ? 50 : 30; 
                    if (Math.abs(proj.pos.x - target.pos.x) < hitDist &&
                        proj.pos.y > target.pos.y - 75 && proj.pos.y < target.pos.y + 10) {

                        proj.active = false;
                        const damage = isMissile ? 35 : 15; // 导弹伤害增加
                        target.health -= damage; 
                        target.stunFrames = isMissile ? 40 : 10;
                        shakeRef.current = isMissile ? 25 : 5;

                        isMissile ? playExplodeSound() : playHitSound();

                        // 导弹击中特效
                        if (isMissile) {
                             spawnParticles(target.pos.x, target.pos.y - 35, '#ff5500', 40, 10);
                             spawnParticles(target.pos.x, target.pos.y - 35, '#555', 20, 5);
                        } else {
                             spawnParticles(target.pos.x, target.pos.y - 35, '#ff0000', 10, 8);
                        }

                        target.vel.x += proj.vel.x * (isMissile ? 1.2 : 0.3); 
                        target.vel.y -= isMissile ? 15 : 5;

                        if (target.health <= 0) {
                            target.health = 0; 
                            target.isDead = true;
                            target.isLoser = true;
                            target.vel.x = proj.vel.x * 0.8;
                            const winner = entitiesRef.current.find(e => e.id === proj.ownerId);
                            if (winner) triggerWin(winner.id);
                        }
                    }
                }
            });
        }
    });
    projectilesRef.current = projectilesRef.current.filter(p => p.active);

    // === 3. 实体更新 ===
    entitiesRef.current.forEach(entity => {
      // 检查武器是否过期
      if (entity.heldWeapon) {
          entity.weaponDuration--;
          if (entity.weaponDuration <= 0) {
              entity.heldWeapon = null;
              spawnParticles(entity.pos.x, entity.pos.y - 40, '#888', 5, 5); // 消失特效
          }
      }

      if (gameState === GameState.VICTORY_ANIMATION && entity.isWinner) {
          entity.isAttacking = false; entity.attackFrame = 0; entity.isCrouching = false;
          const targetX = canvas.width / 2;
          const targetY = canvas.height / 3;
          entity.pos.x += (targetX - entity.pos.x) * 0.05;
          entity.pos.y += (targetY - entity.pos.y) * 0.05;
          entity.pos.y += Math.sin(frameRef.current * 0.08) * 0.8;
          entity.vel.x = 0; entity.vel.y = 0;
          if (frameRef.current % 3 === 0) spawnConfetti(canvas.width);
          return;
      }

      // 拾取武器
      if (!entity.isDead) {
          const canPickUp = !entity.heldWeapon || entity.ammo <= 0;

          if (canPickUp) {
            const itemIndex = fallingItemsRef.current.findIndex(item => {
                const dx = Math.abs(entity.pos.x - (item.pos.x + item.width/2));
                const dy = Math.abs((entity.pos.y - 35) - (item.pos.y + item.height/2));
                return dx < 50 && dy < 60;
            });

            if (itemIndex !== -1) {
                const item = fallingItemsRef.current[itemIndex];
                entity.heldWeapon = item.type;
                entity.weaponDuration = WEAPON_LIFETIME; 
                switch(item.type) {
                    case 'pistol': entity.ammo = 6; break;
                    case 'bomb': entity.ammo = 3; break;
                    case 'stick': entity.ammo = 10; break; 
                    case 'sword': entity.ammo = 8; break;
                    case 'blade': entity.ammo = 5; break; 
                    case 'atom_bomb': entity.ammo = 1; break; 
                    case 'missile': entity.ammo = 2; break; // 导弹只有2发
                    case 'dragon': entity.ammo = 1; break; 
                }
                fallingItemsRef.current.splice(itemIndex, 1);
                playJumpSound();
                spawnParticles(entity.pos.x, entity.pos.y - 30, '#fff', 5, 5);
            }
          }
      }

      // 物理引擎
      const prevY = entity.pos.y;
      entity.vel.y += GRAVITY;

      if (!entity.isLoser && entity.stunFrames > 0) {
           entity.stunFrames--; 
           entity.vel.x *= 0.95; 
      } else if (!entity.isLoser) {
          const currentFriction = entity.isCrouching && entity.isGrounded ? 0.4 : FRICTION;
          entity.vel.x *= currentFriction;
      } else {
          entity.vel.x *= 0.99; 
      }

      entity.pos.x += entity.vel.x;
      entity.pos.y += entity.vel.y;

      // 碰撞检测
      entity.isGrounded = false;
      if (entity.pos.y >= GROUND_Y) {
          if (!entity.isLoser) {
            entity.pos.y = GROUND_Y;
            entity.vel.y = 0;
            entity.isGrounded = true;
          }
      }
      if (entity.vel.y >= 0 && !entity.isDead) {
          PLATFORMS.forEach(plat => {
              if (entity.pos.x > plat.x - 10 && entity.pos.x < plat.x + plat.width + 10) {
                  if (prevY <= plat.y && entity.pos.y >= plat.y) {
                      entity.pos.y = plat.y;
                      entity.vel.y = 0;
                      entity.isGrounded = true;
                  }
              }
          });
      }

      if (!entity.isLoser) {
        if (entity.pos.x < 10) { entity.pos.x = 10; entity.vel.x *= -0.5; }
        if (entity.pos.x > canvas.width - 10) { entity.pos.x = canvas.width - 10; entity.vel.x *= -0.5; }
      }

      if (gameState === GameState.VICTORY_ANIMATION || entity.isDead || entity.stunFrames > 0) return;

      if (entity.attackCooldown > 0) entity.attackCooldown--;
      if (entity.isAttacking) {
          entity.attackFrame++;
          if (entity.attackFrame > 15) { 
              entity.isAttacking = false;
              entity.attackFrame = 0;
          }
      }

      let moveLeft = false, moveRight = false, jump = false, crouch = false, attack = false;

      // Input P1
      if (entity.playerIndex === 0) {
        if (keysRef.current.has('KeyA')) moveLeft = true;
        if (keysRef.current.has('KeyD')) moveRight = true;
        if (keysRef.current.has('KeyW')) jump = true;
        if (keysRef.current.has('KeyS')) crouch = true;
        if (keysRef.current.has('Space')) attack = true;
      }

      // Input P2 / AI
      if (entity.playerIndex === 1) {
          if (gameMode === 'PVP') {
            if (keysRef.current.has('ArrowLeft')) moveLeft = true;
            if (keysRef.current.has('ArrowRight')) moveRight = true;
            if (keysRef.current.has('ArrowUp')) jump = true;
            if (keysRef.current.has('ArrowDown')) crouch = true;
            if (keysRef.current.has('Enter')) attack = true;
          } else {
            // AI Logic
            const p1 = entitiesRef.current.find(e => e.playerIndex === 0);
            if (p1 && !p1.isDead) {
                let targetX = p1.pos.x;
                let targetY = p1.pos.y;

                if (!entity.heldWeapon && fallingItemsRef.current.length > 0) {
                    let minDist = 9999;
                    fallingItemsRef.current.forEach(item => {
                        const d = Math.abs(item.pos.x - entity.pos.x) + Math.abs(item.pos.y - entity.pos.y);
                        if (d < minDist) {
                            minDist = d;
                            targetX = item.pos.x;
                            targetY = item.pos.y;
                        }
                    });
                }

                const distX = targetX - entity.pos.x;
                const distY = targetY - entity.pos.y; 

                if (Math.abs(distX) > 40) {
                    distX > 0 ? moveRight = true : moveLeft = true;
                } else if (!entity.heldWeapon && Math.abs(distX) < 20) {
                     distX > 0 ? moveLeft = true : moveRight = true;
                }

                if (entity.isGrounded) {
                     if (distY < -100 || (Math.random() < 0.02)) {
                         jump = true;
                     }
                }

                const absDistX = Math.abs(p1.pos.x - entity.pos.x);
                entity.facingRight = (p1.pos.x - entity.pos.x) > 0;

                // AI 攻击逻辑
                let attackRange = ATTACK_RANGE;
                if (entity.heldWeapon === 'stick') attackRange = 200;
                if (entity.heldWeapon === 'pistol') attackRange = 600;
                if (entity.heldWeapon === 'atom_bomb') attackRange = 300; 
                if (entity.heldWeapon === 'missile') attackRange = 700; 
                if (entity.heldWeapon === 'dragon') attackRange = 400; 

                if (absDistX < attackRange && Math.abs(p1.pos.y - entity.pos.y) < 100) {
                    if (entity.attackCooldown === 0 && Math.random() < 0.05) attack = true;
                }
            }
          }
      }

      entity.isCrouching = crouch && entity.isGrounded;
      if (!entity.isCrouching) {
          if (moveLeft) { entity.vel.x -= MOVE_SPEED; entity.facingRight = false; }
          if (moveRight) { entity.vel.x += MOVE_SPEED; entity.facingRight = true; }
      }
      if (jump && entity.isGrounded && !entity.isCrouching) {
          entity.vel.y = JUMP_FORCE;
          playJumpSound();
      }

      // === 攻击处理 ===
      if (attack && entity.attackCooldown === 0) {
          entity.attackCooldown = ATTACK_COOLDOWN;
          entity.isAttacking = true;
          entity.attackFrame = 5;

          if (entity.heldWeapon === 'pistol') {
              playShootSound();
              entity.vel.x += entity.facingRight ? -8 : 8;
              entity.vel.y -= 2;

              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'pistol',
                  pos: { x: entity.pos.x + (entity.facingRight ? 40 : -40), y: entity.pos.y - 45 },
                  vel: { x: entity.facingRight ? 20 : -20, y: (Math.random()-0.5) * 2 }, 
                  ownerId: entity.id,
                  width: 12, height: 4, active: true
              });
              entity.ammo--;
          } else if (entity.heldWeapon === 'bomb') {
              entity.vel.x += entity.facingRight ? -2 : 2;
              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'bomb',
                  pos: { x: entity.pos.x, y: entity.pos.y - 60 },
                  vel: { x: entity.facingRight ? 12 : -12, y: -12 },
                  ownerId: entity.id,
                  width: 20, height: 20, active: true
              });
              entity.ammo--;
          } else if (entity.heldWeapon === 'atom_bomb') {
              entity.vel.x += entity.facingRight ? -4 : 4;
              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'atom_bomb',
                  pos: { x: entity.pos.x, y: entity.pos.y - 70 },
                  vel: { x: entity.facingRight ? 8 : -8, y: -10 },
                  ownerId: entity.id,
                  width: 30, height: 40, active: true
              });
              entity.ammo--; 
          } else if (entity.heldWeapon === 'missile') {
              playShootSound(); 
              entity.vel.x += entity.facingRight ? -10 : 10; 
              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'missile',
                  pos: { x: entity.pos.x + (entity.facingRight ? 50 : -50), y: entity.pos.y - 50 },
                  vel: { x: entity.facingRight ? 10 : -10, y: -5 }, 
                  ownerId: entity.id,
                  width: 20, height: 8, active: true
              });
              entity.ammo--; 
          } else if (entity.heldWeapon === 'dragon') {
              playDragonRoar();
              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'dragon',
                  pos: { x: entity.pos.x, y: entity.pos.y - 100 },
                  vel: { x: 0, y: 0 },
                  ownerId: entity.id,
                  width: 40, height: 40, active: true,
                  dragonState: 'enter', 
                  remainingHits: 5,
                  dragonPathProgress: 0,
                  dragonSegments: undefined
              });
              entity.ammo--;
          } else {
              // == 近战武器 ==
              playAttackSound();

              let range = ATTACK_RANGE;
              let dmg = ATTACK_DAMAGE;
              let knockbackX = 15;
              let knockbackY = -8;
              let selfPush = 10;
              let hitEffectSize = 12;

              if (entity.heldWeapon === 'stick') {
                  range = 220; dmg = 12; knockbackX = 20; selfPush = 5; hitEffectSize = 15;
              } else if (entity.heldWeapon === 'sword') {
                  range = 140; dmg = 15; knockbackX = 12; selfPush = 12; entity.attackCooldown = 20; 
              } else if (entity.heldWeapon === 'blade') {
                  range = 160; dmg = 25; knockbackX = 25; knockbackY = -12; selfPush = 2; entity.attackCooldown = 50; 
              }

              entity.vel.x = entity.facingRight ? selfPush : -selfPush;

              const hitX = entity.facingRight ? entity.pos.x + range/2 : entity.pos.x - range/2;
              const hitY = entity.isCrouching ? entity.pos.y - 20 : entity.pos.y - 45;

              let hitSomething = false;

              entitiesRef.current.forEach(target => {
                  if (target !== entity && !target.isDead) {
                      const dy = (target.pos.y - 35) - hitY;
                      if (Math.abs(target.pos.x - entity.pos.x) < range && Math.abs(dy) < 60 && 
                          ((entity.facingRight && target.pos.x > entity.pos.x) || (!entity.facingRight && target.pos.x < entity.pos.x))) {

                          if (!entity.isCrouching && target.isCrouching) {
                              spawnParticles(target.pos.x, target.pos.y - 40, '#aaa', 2, 2);
                              return; 
                          }

                          target.health -= dmg;
                          hitSomething = true;

                          target.vel.x = entity.facingRight ? knockbackX : -knockbackX; 
                          target.vel.y = knockbackY; 
                          target.stunFrames = 20; 

                          shakeRef.current = Math.floor(dmg / 2);
                          spawnParticles(target.pos.x, target.pos.y - 40, target.color, hitEffectSize, 10);
                          playHitSound();

                          if (target.health <= 0) {
                              target.health = 0;
                              target.isDead = true;
                              target.isLoser = true;
                              target.vel.x = entity.facingRight ? 30 : -30;
                              target.vel.y = -20;
                              triggerWin(entity.id);
                          }
                      }
                  }
              });

              if (hitSomething && entity.heldWeapon) {
                  entity.ammo--;
              }
          }

          // 弹药耗尽检查
          if (entity.heldWeapon && entity.ammo <= 0) {
              entity.heldWeapon = null;
              spawnParticles(entity.pos.x, entity.pos.y - 40, '#888', 5, 5); 
          }
      }
    });

    particlesRef.current.forEach(p => {
        p.life--;
        p.pos.x += p.vel.x;
        p.pos.y += p.vel.y;
        if (p.gravity) p.vel.y += p.gravity;

        if (p.growth) { p.size += p.growth; }
        if (p.alphaDecay) {
            p.currentAlpha = p.currentAlpha !== undefined ? p.currentAlpha - p.alphaDecay : 1.0;
        }
    });
    particlesRef.current = particlesRef.current.filter(p => p.life > 0 && (p.currentAlpha === undefined || p.currentAlpha > 0));
  };

  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Shake logic
    let shakeX = 0;
    let shakeY = 0;
    if (shakeRef.current > 0) {
        const magnitude = shakeRef.current;
        shakeX = (Math.random() - 0.5) * magnitude;
        shakeY = (Math.random() - 0.5) * magnitude;
    }

    ctx.save();
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Apply Shake
    ctx.translate(shakeX, shakeY);

    // Draw Platforms
    ctx.fillStyle = '#334155'; // Slate-700
    PLATFORMS.forEach(plat => {
        ctx.fillRect(plat.x, plat.y, plat.width, plat.height);
        // Highlight top
        ctx.fillStyle = '#475569';
        ctx.fillRect(plat.x, plat.y, plat.width, 4);
        ctx.fillStyle = '#334155';
    });

    // Ground
    ctx.fillStyle = '#1e293b'; // Slate-800
    ctx.fillRect(0, GROUND_Y, canvas.width, canvas.height - GROUND_Y);
    // Ground Line
    ctx.beginPath();
    ctx.strokeStyle = '#334155';
    ctx.lineWidth = 2;
    ctx.moveTo(0, GROUND_Y);
    ctx.lineTo(canvas.width, GROUND_Y);
    ctx.stroke();

    // Draw Falling Items
    fallingItemsRef.current.forEach(item => {
        ctx.save();
        ctx.translate(item.pos.x + item.width/2, item.pos.y + item.height/2);
        // Simple item box
        ctx.fillStyle = '#4f46e5'; // Indigo
        ctx.fillRect(-item.width/2, -item.height/2, item.width, item.height);
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2;
        ctx.strokeRect(-item.width/2, -item.height/2, item.width, item.height);

        // Icon
        ctx.fillStyle = '#fff';
        ctx.font = '16px Arial';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        let icon = '?';
        switch(item.type) {
            case 'pistol': icon = '🔫'; break;
            case 'bomb': icon = '💣'; break;
            case 'atom_bomb': icon = '☢️'; break;
            case 'missile': icon = '🚀'; break;
            case 'dragon': icon = '🐉'; break;
            case 'stick': icon = '🦯'; break;
            case 'sword': icon = '🗡️'; break;
            case 'blade': icon = '🔪'; break;
        }
        ctx.fillText(icon, 0, 0);
        ctx.restore();
    });

    // Draw Entities
    entitiesRef.current.forEach(entity => {
        if (!entity.isDead || entity.isLoser) { 
            drawEntity(ctx, entity);
        }
    });

    // Draw Projectiles
    projectilesRef.current.forEach(proj => {
        ctx.save();
        ctx.translate(proj.pos.x, proj.pos.y);

        if (proj.type === 'dragon') {
            // Head
            ctx.fillStyle = '#FFD700';
            ctx.beginPath();
            ctx.arc(0, 0, 20, 0, Math.PI * 2);
            ctx.fill();
            ctx.fillStyle = 'red';
            ctx.beginPath();
            ctx.arc(8, -5, 5, 0, Math.PI * 2);
            ctx.fill();
        } else if (proj.type === 'missile') {
            const angle = Math.atan2(proj.vel.y, proj.vel.x);
            ctx.rotate(angle);
            ctx.fillStyle = '#333';
            ctx.fillRect(-10, -5, 20, 10);
            ctx.fillStyle = 'red';
            ctx.fillRect(10, -5, 5, 10);
            ctx.fillStyle = '#555';
            ctx.beginPath();
            ctx.moveTo(-10, -5); ctx.lineTo(-15, -10); ctx.lineTo(-5, -5);
            ctx.fill();
            ctx.beginPath();
            ctx.moveTo(-10, 5); ctx.lineTo(-15, 10); ctx.lineTo(-5, 5);
            ctx.fill();
        } else if (proj.type === 'bomb' || proj.type === 'atom_bomb') {
             ctx.fillStyle = '#000';
             ctx.beginPath();
             ctx.arc(0, 0, proj.width/2, 0, Math.PI * 2);
             ctx.fill();
             if (Math.random() > 0.5) {
                 ctx.fillStyle = 'orange';
                 ctx.fillRect(proj.width/2, -proj.height/2 - 5, 4, 4);
             }
        } else {
            // Bullet
            ctx.fillStyle = '#fff';
            ctx.fillRect(-proj.width/2, -proj.height/2, proj.width, proj.height);
        }
        ctx.restore();

        // Dragon segments
        if (proj.type === 'dragon' && proj.dragonSegments) {
             proj.dragonSegments.forEach((seg, i) => {
                 ctx.beginPath();
                 const size = 15 - i * 0.5;
                 ctx.fillStyle = `rgba(255, 215, 0, ${1 - i/25})`;
                 ctx.arc(seg.x, seg.y, Math.max(2, size), 0, Math.PI * 2);
                 ctx.fill();
             });
        }
    });

    // Draw Particles
    particlesRef.current.forEach(p => {
      ctx.save();
      ctx.fillStyle = p.color;
      const alpha = p.currentAlpha !== undefined ? p.currentAlpha : (p.life / p.maxLife);
      ctx.globalAlpha = alpha;
      ctx.beginPath(); 
      ctx.arc(p.pos.x, p.pos.y, p.size, 0, Math.PI * 2); 
      ctx.fill();
      ctx.restore();
    });

    ctx.restore();

    // Flash (Screen Space)
    if (flashRef.current > 0) {
      ctx.save();
      ctx.fillStyle = `rgba(255, 255, 255, ${Math.min(1, flashRef.current)})`;
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.restore();
    }
  };

  const tick = () => {
    update();
    draw();
    requestRef.current = requestAnimationFrame(tick);
  };

  useEffect(() => {
    if (canvasRef.current) {
        canvasRef.current.width = window.innerWidth;
        canvasRef.current.height = window.innerHeight;
    }
    requestRef.current = requestAnimationFrame(tick);
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [gameState]);

  return (
    <canvas 
        ref={canvasRef} 
        className="block w-full h-full bg-slate-900"
    />
  );
};

export default GameCanvas;

export enum GameState {
  MENU,
  PLAYING,
  GAME_OVER,
  VICTORY_ANIMATION
}

export type GameMode = 'PVE' | 'PVP';

export interface Vector {
  x: number;
  y: number;
}

// 移除了 stick, blade，新增 bomber
export type WeaponType = 'pistol' | 'bomb' | 'sword' | 'atom_bomb' | 'missile' | 'dragon' | 'bomber';

export interface Platform {
  x: number;
  y: number;
  width: number;
  height: number;
}

export interface Entity {
  id: string;
  pos: Vector;
  vel: Vector;
  width: number;
  height: number;
  color: string;
  isGrounded: boolean;
  isCrouching: boolean;
  health: number;
  maxHealth: number;
  isDead: boolean;
  facingRight: boolean;
  attackCooldown: number;
  isAttacking: boolean;
  attackFrame: number;
  type: 'player'; 
  playerIndex: number; 
  isWinner?: boolean;
  isLoser?: boolean;
  heldWeapon?: WeaponType | null;
  ammo: number; // 弹药量 或 近战武器耐久度
  weaponDuration: number; // 新增：武器剩余存在时间 (帧)
  stunFrames: number; // 受击硬直/击飞状态
}

export interface FallingItem {
  id: string;
  type: WeaponType;
  pos: Vector;
  vel: Vector;
  width: number;
  height: number;
  onGround: boolean;
}

export interface Projectile {
  id: string;
  type: WeaponType;
  pos: Vector;
  vel: Vector;
  ownerId: string;
  width: number;
  height: number;
  active: boolean;
  targetId?: string; // 追踪目标ID

  // 神龙特有属性
  dragonState?: 'enter' | 'hunt';
  dragonPathProgress?: number; // 入场动画进度
  dragonSegments?: Vector[]; // 龙身位置数组
  remainingHits?: number; // 剩余攻击次数
  lastHitFrame?: number; // 上次攻击时间

  // 轰炸机特有属性
  bomberState?: 'fly_in' | 'bombing' | 'fly_out';
  bombDropCount?: number;
}

export interface Particle {
  id: string;
  pos: Vector;
  vel: Vector;
  life: number;
  maxLife: number;
  color: string;
  size: number;
  gravity?: number; 

  // 新增属性用于高级特效 (蘑菇云等)
  growth?: number; // 尺寸增长速率
  alphaDecay?: number; // 透明度衰减速率 (默认是 life/maxLife，此项可覆盖)
  currentAlpha?: number;
}

export interface GameStats {
  winner: string | null;
  mode: GameMode;
  duration: number;
}

import React, { useRef, useEffect, useCallback } from 'react';
import { GameState, Entity, Vector, Particle, GameStats, GameMode, FallingItem, Projectile, WeaponType, Platform } from '../types';
import { playJumpSound, playAttackSound, playHitSound, playShootSound, playExplodeSound, playDragonRoar } from '../services/audioService';

interface GameCanvasProps {
  gameState: GameState;
  setGameState: (state: GameState) => void;
  setStats: React.Dispatch<React.SetStateAction<GameStats>>;
  setPlayers: (players: Entity[]) => void;
  gameMode: GameMode;
}

// === 物理参数 (提速版) ===
const GRAVITY = 0.8; 
const FRICTION = 0.82; 
const MOVE_SPEED = 2; 
const JUMP_FORCE = -22; 
const GROUND_Y = 600;
const ATTACK_COOLDOWN = 18; 
const ATTACK_RANGE = 100;
const ATTACK_DAMAGE = 8;

// === 武器生成配置 ===
const MAX_WEAPONS_PER_GAME = 6; 
const WEAPON_SPAWN_INTERVAL = 900; 
const WEAPON_LIFETIME = 15 * 60; 

// === 关卡设计 ===
const PLATFORMS: Platform[] = [
    { x: 300, y: 450, width: 200, height: 20 },
    { x: 800, y: 450, width: 200, height: 20 },
    { x: 500, y: 250, width: 300, height: 20 } 
];

const drawEntity = (ctx: CanvasRenderingContext2D, entity: Entity) => {
    ctx.save();

    const centerX = entity.pos.x;
    const centerY = entity.pos.y; // Feet position

    ctx.translate(centerX, centerY);

    if (entity.isDead) {
         ctx.rotate(Math.PI / 2 * (entity.facingRight ? 1 : -1));
         ctx.translate(0, -10);
    }

    if (!entity.facingRight) ctx.scale(-1, 1);

    // Draw body
    ctx.fillStyle = entity.color;
    ctx.strokeStyle = entity.color;
    ctx.lineWidth = 4;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    const crouchOffset = entity.isCrouching ? 20 : 0;

    // Head
    ctx.beginPath();
    ctx.arc(0, -entity.height + 20 + crouchOffset, 12, 0, Math.PI * 2);
    ctx.fill();

    // Body
    ctx.beginPath();
    ctx.moveTo(0, -entity.height + 32 + crouchOffset);
    ctx.lineTo(0, -25 + crouchOffset);
    ctx.stroke();

    // Legs
    ctx.beginPath();
    ctx.moveTo(0, -25 + crouchOffset);
    if (entity.isCrouching) {
        ctx.lineTo(-15, -5);
        ctx.moveTo(0, -25 + crouchOffset);
        ctx.lineTo(15, -5);
    } else if (Math.abs(entity.vel.x) > 0.1 && entity.isGrounded) {
        const walkCycle = Math.sin(Date.now() / 100) * 10;
        ctx.lineTo(-10 + walkCycle, 0);
        ctx.moveTo(0, -25 + crouchOffset);
        ctx.lineTo(10 - walkCycle, 0);
    } else {
        ctx.lineTo(-10, 0);
        ctx.moveTo(0, -25 + crouchOffset);
        ctx.lineTo(10, 0);
    }
    ctx.stroke();

    // Arms
    ctx.beginPath();
    const shoulderY = -entity.height + 40 + crouchOffset;
    ctx.moveTo(0, shoulderY);

    if (entity.isWinner) {
        ctx.lineTo(-20, shoulderY - 30);
        ctx.moveTo(0, shoulderY);
        ctx.lineTo(20, shoulderY - 30);
    } else if (entity.isAttacking) {
        const attackProgress = entity.attackFrame / 15;
        ctx.lineTo(25, shoulderY - 10 + attackProgress * 20);
    } else if (entity.heldWeapon) {
        ctx.lineTo(15, shoulderY + 5);

        ctx.save();
        ctx.translate(15, shoulderY + 5);

        if (entity.heldWeapon === 'pistol') {
            ctx.fillStyle = '#555';
            ctx.fillRect(0, -5, 15, 5);
            ctx.fillRect(0, 0, 5, 5);
        } else if (entity.heldWeapon === 'sword') {
            ctx.fillStyle = '#ccc';
            ctx.fillRect(0, -25, 4, 30);
            ctx.fillStyle = '#8B4513';
            ctx.fillRect(-3, 0, 10, 2);
        } else if (entity.heldWeapon === 'bomb' || entity.heldWeapon === 'atom_bomb') {
            ctx.fillStyle = '#000';
            ctx.beginPath();
            ctx.arc(5, 0, 8, 0, Math.PI*2);
            ctx.fill();
            ctx.strokeStyle = '#fff';
            ctx.beginPath();
            ctx.moveTo(5, -8);
            ctx.quadraticCurveTo(10, -15, 15, -10);
            ctx.stroke();
             if (entity.heldWeapon === 'atom_bomb') {
                ctx.fillStyle = 'yellow';
                ctx.font = '10px Arial';
                ctx.fillText('☢', 2, 4);
            }
        } else if (entity.heldWeapon === 'missile') {
             ctx.fillStyle = 'green';
             ctx.fillRect(0, -5, 20, 10);
             ctx.fillStyle = 'red';
             ctx.fillRect(20, -5, 5, 10);
        } else if (entity.heldWeapon === 'dragon') {
             ctx.font = '20px serif';
             ctx.fillText('🐉', 0, 5);
        } else if (entity.heldWeapon === 'bomber') {
             // 无线电/对讲机外观
             ctx.fillStyle = '#333';
             ctx.fillRect(0, -10, 10, 16);
             ctx.fillStyle = '#000';
             ctx.fillRect(2, -15, 2, 5); // 天线
             ctx.fillStyle = '#f00';
             ctx.beginPath(); ctx.arc(5, -5, 2, 0, Math.PI*2); ctx.fill(); // 信号灯
        }
        ctx.restore();

    } else {
        if (Math.abs(entity.vel.x) > 0.1) {
             const armCycle = Math.cos(Date.now() / 100) * 10;
             ctx.lineTo(armCycle, shoulderY + 15);
        } else {
             ctx.lineTo(0, shoulderY + 20);
        }
    }
    ctx.stroke();

    ctx.restore();
};

const GameCanvas: React.FC<GameCanvasProps> = ({ gameState, setGameState, setStats, setPlayers, gameMode }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();
  const frameRef = useRef<number>(0);

  const entitiesRef = useRef<Entity[]>([]);
  const particlesRef = useRef<Particle[]>([]);
  const fallingItemsRef = useRef<FallingItem[]>([]);
  const projectilesRef = useRef<Projectile[]>([]);

  // 武器生成控制
  const spawnedWeaponCountRef = useRef<number>(0); 
  const atomBombIndexRef = useRef<number>(-1); 
  const missileIndexRef = useRef<number>(-1); 
  const dragonIndexRef = useRef<number>(-1); 

  const keysRef = useRef<Set<string>>(new Set());
  const statsRef = useRef<GameStats>({ winner: null, mode: gameMode, duration: 0 });
  const shakeRef = useRef<number>(0);
  const flashRef = useRef<number>(0); 

  // 初始化对决
  const initGame = useCallback(() => {
    const newEntities: Entity[] = [];

    // P1 (左侧)
    newEntities.push({
      id: 'p1', type: 'player', playerIndex: 0,
      pos: { x: 100, y: 100 }, vel: { x: 0, y: 0 }, 
      width: 40, height: 70, color: '#3b82f6', 
      isGrounded: false, isCrouching: false, health: 100, maxHealth: 100, isDead: false,
      facingRight: true, attackCooldown: 0, isAttacking: false, attackFrame: 0,
      heldWeapon: null, ammo: 0, weaponDuration: 0, stunFrames: 0
    });

    // P2/CPU (右侧)
    newEntities.push({
      id: 'p2', type: 'player', playerIndex: 1,
      pos: { x: window.innerWidth - 100, y: 100 }, vel: { x: 0, y: 0 },
      width: 40, height: 70, color: '#facc15',
      isGrounded: false, isCrouching: false, health: 100, maxHealth: 100, isDead: false,
      facingRight: false, attackCooldown: 0, isAttacking: false, attackFrame: 0,
      heldWeapon: null, ammo: 0, weaponDuration: 0, stunFrames: 0
    });

    entitiesRef.current = newEntities;
    particlesRef.current = [];
    fallingItemsRef.current = [];
    projectilesRef.current = [];
    spawnedWeaponCountRef.current = 0; 

    const indices = Array.from({length: MAX_WEAPONS_PER_GAME}, (_, i) => i);
    for (let i = indices.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [indices[i], indices[j]] = [indices[j], indices[i]];
    }

    atomBombIndexRef.current = indices[0];
    missileIndexRef.current = indices[1];
    dragonIndexRef.current = indices[2]; 

    statsRef.current = { winner: null, mode: gameMode, duration: 0 };
    frameRef.current = 0;
    shakeRef.current = 0;
    flashRef.current = 0;

    setStats(statsRef.current);
    setPlayers([...entitiesRef.current]);
  }, [gameMode, setStats, setPlayers]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        if (e.repeat) return;
        keysRef.current.add(e.code);
        if (e.code === 'KeyR' && gameState === GameState.GAME_OVER) {
             setGameState(GameState.PLAYING);
        }
    };
    const handleKeyUp = (e: KeyboardEvent) => keysRef.current.delete(e.code);
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, [gameState, setGameState]);

  useEffect(() => {
    if (gameState === GameState.PLAYING) {
      initGame();
    }
  }, [gameState, initGame]);

  const spawnParticles = (x: number, y: number, color: string, count: number, speed = 8, lifeMultiplier = 1) => {
      for(let i=0; i<count; i++) {
          particlesRef.current.push({
              id: Math.random().toString(),
              pos: {x, y},
              vel: { x: (Math.random() - 0.5) * speed, y: (Math.random() - 0.5) * speed },
              life: (20 + Math.random() * 20) * lifeMultiplier,
              maxLife: 40 * lifeMultiplier,
              color: color,
              size: Math.random() * 6 + 3,
              gravity: 0.5 
          });
      }
  };

  const spawnMushroomCloud = (x: number, y: number) => {
    // 1. 蘑菇柄 (上升的烟柱)
    for (let i = 0; i < 20; i++) {
      particlesRef.current.push({
        id: Math.random().toString(),
        pos: { x: x + (Math.random()-0.5)*20, y: y },
        vel: { x: (Math.random()-0.5) * 1, y: -2 - Math.random() * 3 },
        life: 180,
        maxLife: 180,
        color: i % 2 === 0 ? '#555' : '#333',
        size: 15 + Math.random() * 10,
        gravity: -0.05, // 轻微上升
        growth: 0.3, // 膨胀
        alphaDecay: 0.005,
        currentAlpha: 0.8
      });
    }

    // 2. 蘑菇盖 (顶部扩散)
    for (let i = 0; i < 40; i++) {
      const angle = (Math.PI / 40) * i * 2; // 360度
      const speed = 2 + Math.random() * 3;
      particlesRef.current.push({
        id: Math.random().toString(),
        pos: { x: x, y: y - 80 },
        vel: { x: Math.cos(angle) * speed, y: Math.sin(angle) * speed * 0.5 - 1 },
        life: 200,
        maxLife: 200,
        color: Math.random() > 0.5 ? '#ff4500' : '#ff8800', // 橙红火光
        size: 20 + Math.random() * 10,
        gravity: -0.02,
        growth: 0.5, // 快速膨胀
        alphaDecay: 0.008,
        currentAlpha: 0.9
      });
    }

    // 3. 底部冲击波 (贴地尘土)
    for (let i = 0; i < 30; i++) {
        const dir = i % 2 === 0 ? 1 : -1;
        particlesRef.current.push({
            id: Math.random().toString(),
            pos: { x: x, y: y },
            vel: { x: dir * (5 + Math.random()*10), y: -1 },
            life: 100, maxLife: 100,
            color: '#777',
            size: 10,
            gravity: 0,
            growth: 0.8,
            alphaDecay: 0.02,
            currentAlpha: 0.6
        });
    }
  };

  const spawnConfetti = (width: number) => {
      const colors = ['#FFD700', '#FF6347', '#00BFFF', '#32CD32', '#FF69B4', '#FFFFFF'];
      const x = Math.random() * width;
      const y = -10; 
      const color = colors[Math.floor(Math.random() * colors.length)];
      particlesRef.current.push({
          id: Math.random().toString(),
          pos: { x, y },
          vel: { x: (Math.random() - 0.5) * 2, y: Math.random() * 2 + 1 },
          life: 200, maxLife: 200, color, size: Math.random() * 4 + 3, gravity: 0.02 
      });
  };

  const spawnFallingItem = (canvasWidth: number) => {
      let type: WeaponType;

      const count = spawnedWeaponCountRef.current;

      if (count === atomBombIndexRef.current) {
          type = 'atom_bomb';
      } else if (count === missileIndexRef.current) {
          type = 'missile';
      } else if (count === dragonIndexRef.current) {
          type = 'dragon';
      } else {
          // 移除 stick 和 blade，加入 bomber
          const normalPool: WeaponType[] = ['pistol', 'bomb', 'sword', 'bomber'];
          type = normalPool[Math.floor(Math.random() * normalPool.length)];
      }

      fallingItemsRef.current.push({
          id: Math.random().toString() + "_" + Date.now(),
          type,
          pos: { x: 100 + Math.random() * (canvasWidth - 200), y: -50 },
          vel: { x: (Math.random() - 0.5) * 2, y: 2 },
          width: 30, height: 30,
          onGround: false
      });
      spawnedWeaponCountRef.current++;
  };

  const update = () => {
    if (gameState !== GameState.PLAYING && gameState !== GameState.VICTORY_ANIMATION) return;
    const canvas = canvasRef.current;
    if (!canvas) return;

    frameRef.current++;
    if (shakeRef.current > 0) shakeRef.current--;
    if (flashRef.current > 0) flashRef.current -= 0.02; 
    if (gameState === GameState.PLAYING) statsRef.current.duration += 1/60;

    const triggerWin = (winnerId: string) => {
        if (statsRef.current.winner) return;
        const winner = entitiesRef.current.find(e => e.id === winnerId);
        if (winner) winner.isWinner = true;
        statsRef.current.winner = winnerId === 'p1' ? 'P1' : 'P2';
        setGameState(GameState.VICTORY_ANIMATION);
        setTimeout(() => setGameState(GameState.GAME_OVER), 4000);
    };

    // === 0. 掉落物生成 ===
    if (gameState === GameState.PLAYING && 
        spawnedWeaponCountRef.current < MAX_WEAPONS_PER_GAME && 
        frameRef.current > 60 && 
        frameRef.current % WEAPON_SPAWN_INTERVAL === 0) {
        spawnFallingItem(canvas.width);
    }

    // === 1. 掉落物逻辑 ===
    fallingItemsRef.current.forEach(item => {
        item.vel.y += 0.2; 
        if (item.vel.y > 8) item.vel.y = 8;

        const prevY = item.pos.y;
        item.pos.x += item.vel.x;
        item.pos.y += item.vel.y;

        if (item.pos.y >= GROUND_Y - item.height) {
            item.pos.y = GROUND_Y - item.height;
            item.onGround = true;
            item.vel.y = -item.vel.y * 0.5;
            item.vel.x *= 0.8;
        }

        if (item.vel.y > 0) {
            PLATFORMS.forEach(plat => {
                if (item.pos.x + item.width > plat.x && item.pos.x < plat.x + plat.width) {
                    if (prevY + item.height <= plat.y && item.pos.y + item.height >= plat.y) {
                        item.pos.y = plat.y - item.height;
                        item.onGround = true;
                        item.vel.y = -item.vel.y * 0.5;
                        item.vel.x *= 0.8;
                    }
                }
            });
        }
    });

    // === 2. 投射物逻辑 (子弹、炸弹、导弹、神龙、轰炸机) ===
    projectilesRef.current.forEach(proj => {
        if (!proj.active) return;

        // --- 轰炸机逻辑 ---
        if (proj.type === 'bomber') {
            const target = entitiesRef.current.find(e => e.id !== proj.ownerId && !e.isDead);
            const targetX = target ? target.pos.x : canvas.width / 2;
            const flyHeight = 150;

            // 确保Y轴高度
            proj.pos.y += (flyHeight - proj.pos.y) * 0.1;

            if (proj.bomberState === 'fly_in') {
                // 飞向目标X
                const dx = targetX - proj.pos.x;
                const dir = dx > 0 ? 1 : -1;

                // 快速接近
                proj.vel.x = dir * 10; 

                // 到达目标附近，开始投弹
                if (Math.abs(dx) < 60) {
                    proj.bomberState = 'bombing';
                    proj.bombDropCount = 0;
                    proj.lastHitFrame = frameRef.current;
                }
            } else if (proj.bomberState === 'bombing') {
                // 减速投弹
                proj.vel.x = proj.vel.x > 0 ? 5 : -5;

                const interval = 12; // 投弹间隔帧数
                if (frameRef.current - (proj.lastHitFrame || 0) > interval) {
                    proj.lastHitFrame = frameRef.current;
                    // 投掷炸弹
                    projectilesRef.current.push({
                        id: Math.random().toString(),
                        type: 'bomb',
                        pos: { x: proj.pos.x, y: proj.pos.y + 20 },
                        vel: { x: proj.vel.x * 0.5, y: 5 }, // 继承一点惯性
                        ownerId: proj.ownerId,
                        width: 20, height: 20, active: true
                    });
                    if (proj.bombDropCount !== undefined) proj.bombDropCount++;

                    if (proj.bombDropCount && proj.bombDropCount >= 3) {
                         proj.bomberState = 'fly_out';
                    }
                }
            } else if (proj.bomberState === 'fly_out') {
                // 加速飞离
                proj.vel.x = proj.vel.x > 0 ? 15 : -15;
                if (proj.pos.x < -200 || proj.pos.x > canvas.width + 200) {
                    proj.active = false;
                }
            }

            proj.pos.x += proj.vel.x;
            return;
        }

        // --- 神龙逻辑 (优化动作) ---
        if (proj.type === 'dragon') {
            const dragonSegmentsCount = 20; // 增加段数，更流畅
            if (!proj.dragonSegments || proj.dragonSegments.length === 0) {
                proj.dragonSegments = Array.from({ length: dragonSegmentsCount }, () => ({ ...proj.pos }));
            }

            if (proj.dragonState === 'enter') {
                if (!proj.dragonPathProgress) proj.dragonPathProgress = 0;
                proj.dragonPathProgress += 0.02;

                shakeRef.current = 8;
                if (Math.random() < 0.1) playExplodeSound();

                const w = canvas.width;
                const h = canvas.height;
                const t = proj.dragonPathProgress * Math.PI * 2;

                // 更复杂的入场轨迹
                const targetX = w/2 + (w/2 - 50) * Math.cos(t) * Math.sin(t*0.5);
                const targetY = h/3 + (h/4) * Math.sin(2*t);

                proj.vel.x = (targetX - proj.pos.x) * 0.2;
                proj.vel.y = (targetY - proj.pos.y) * 0.2;
                proj.pos.x += proj.vel.x;
                proj.pos.y += proj.vel.y;

                if (proj.dragonPathProgress >= 1.5) {
                    proj.dragonState = 'hunt';
                    shakeRef.current = 0;
                }
            } else if (proj.dragonState === 'hunt') {
                const target = entitiesRef.current.find(e => e.id !== proj.ownerId && !e.isDead);
                if (target) {
                    const dx = target.pos.x - proj.pos.x;
                    const dy = (target.pos.y - 40) - proj.pos.y;
                    const dist = Math.sqrt(dx*dx + dy*dy);

                    const speed = 7; // 略微提速
                    // 增加一点惯性，避免转弯太生硬
                    proj.vel.x = (proj.vel.x * 20 + (dx / dist) * speed) / 21;
                    proj.vel.y = (proj.vel.y * 20 + (dy / dist) * speed) / 21;

                    proj.pos.x += proj.vel.x;
                    proj.pos.y += proj.vel.y;

                    if (dist < 50) {
                        const now = frameRef.current;
                        if (!proj.lastHitFrame || now - proj.lastHitFrame > 30) {
                            proj.lastHitFrame = now;
                            if (proj.remainingHits && proj.remainingHits > 0) {
                                proj.remainingHits--;

                                target.health -= 5;
                                target.stunFrames = 20;
                                target.vel.x = (Math.random()-0.5) * 30;
                                target.vel.y = -15;

                                playHitSound();
                                spawnParticles(target.pos.x, target.pos.y, '#FFD700', 20, 8);
                                shakeRef.current = 15;

                                if (target.health <= 0) {
                                    target.health = 0;
                                    target.isDead = true;
                                    target.isLoser = true;
                                    triggerWin(proj.ownerId);
                                }

                                if (proj.remainingHits <= 0) {
                                    proj.active = false;
                                    // 神龙离去特效
                                    spawnParticles(proj.pos.x, proj.pos.y, '#FFD700', 80, 15);
                                }
                            }
                        }
                    }
                } else {
                    proj.vel.y -= 0.5;
                    proj.pos.x += Math.sin(frameRef.current * 0.1) * 5;
                    proj.pos.y += proj.vel.y;
                    if (proj.pos.y < -300) proj.active = false;
                }
            }

            if (proj.dragonSegments && proj.dragonSegments.length > 0) {
                proj.dragonSegments[0] = { ...proj.pos };
                for (let i = 1; i < proj.dragonSegments.length; i++) {
                    const current = proj.dragonSegments[i];
                    const prev = proj.dragonSegments[i-1];
                    const dx = prev.x - current.x;
                    const dy = prev.y - current.y;
                    const d = Math.sqrt(dx*dx + dy*dy);
                    const spacing = 18; 

                    if (d > spacing) {
                        const ratio = (d - spacing) / d;
                        current.x += dx * ratio;
                        current.y += dy * ratio;
                    }
                }
            }
            return; 
        }

        // --- 巡航导弹逻辑 (东风) ---
        if (proj.type === 'missile') {
            if (frameRef.current % 2 === 0) {
                // 浓烟尾迹
                particlesRef.current.push({
                    id: Math.random().toString(),
                    pos: { x: proj.pos.x, y: proj.pos.y },
                    vel: { x: -proj.vel.x * 0.1, y: -proj.vel.y * 0.1 }, // 惯性残留
                    life: 40, maxLife: 40, color: '#aaa', size: 6, gravity: 0, growth: 0.2, alphaDecay: 0.05
                });
                // 火焰中心
                particlesRef.current.push({
                    id: Math.random().toString(),
                    pos: { x: proj.pos.x, y: proj.pos.y },
                    vel: { x: -proj.vel.x * 0.5, y: -proj.vel.y * 0.5 },
                    life: 10, maxLife: 10, color: '#ff5500', size: 4, gravity: 0
                });
            }

            const target = entitiesRef.current.find(e => e.id !== proj.ownerId && !e.isDead);
            if (target) {
                const targetX = target.pos.x;
                const targetY = target.pos.y - 35; 
                const dx = targetX - proj.pos.x;
                const dy = targetY - proj.pos.y;
                const dist = Math.sqrt(dx*dx + dy*dy);

                if (dist > 10) {
                    const speed = 8; // 导弹速度
                    // 增加追踪惯性
                    proj.vel.x = (proj.vel.x * 30 + (dx / dist) * speed) / 31;
                    proj.vel.y = (proj.vel.y * 30 + (dy / dist) * speed) / 31;
                }
            }
        }

        proj.pos.x += proj.vel.x;
        proj.pos.y += proj.vel.y;

        // --- 炸弹/原子弹落地 ---
        if (proj.type === 'bomb' || proj.type === 'atom_bomb') {
            const isNuke = proj.type === 'atom_bomb';
            proj.vel.y += GRAVITY; 
            let hitGround = false;
             if (proj.pos.y >= GROUND_Y) { hitGround = true; }
             else if (proj.vel.y > 0) {
                 PLATFORMS.forEach(plat => {
                     if (proj.pos.x > plat.x && proj.pos.x < plat.x + plat.width && 
                         proj.pos.y >= plat.y && proj.pos.y <= plat.y + 20) {
                         hitGround = true;
                     }
                 });
             }

            if (hitGround) {
                proj.active = false;

                if (isNuke) {
                    // === 核爆逻辑升级 ===
                    shakeRef.current = 120; 
                    flashRef.current = 1.0; 
                    playExplodeSound();

                    // 生成蘑菇云
                    spawnMushroomCloud(proj.pos.x, proj.pos.y - 10);

                    // 冲击波伤害范围极大
                    entitiesRef.current.forEach(target => {
                         if (!target.isDead) {
                             target.health = 0;
                             target.isDead = true;
                             target.isLoser = true;
                             // 被吹飞
                             const dir = target.pos.x - proj.pos.x > 0 ? 1 : -1;
                             target.vel.x = dir * 60;
                             target.vel.y = -60;

                             if (target.id !== proj.ownerId) {
                                 const winner = entitiesRef.current.find(e => e.id === proj.ownerId);
                                 if (winner) triggerWin(winner.id);
                             } else {
                                 const enemy = entitiesRef.current.find(e => e.id !== proj.ownerId);
                                 if (enemy) triggerWin(enemy.id);
                             }
                         }
                    });

                } else {
                    shakeRef.current = 25; 
                    playExplodeSound();
                    spawnParticles(proj.pos.x, proj.pos.y, '#ff4500', 40, 15, 2); 

                    entitiesRef.current.forEach(target => {
                        if (!target.isDead) {
                            const dist = Math.sqrt(Math.pow(target.pos.x - proj.pos.x, 2) + Math.pow(target.pos.y - proj.pos.y, 2));
                            if (dist < 180) {
                                target.health -= 25; 
                                if (target.health <= 0) { target.health = 0; target.isDead = true; target.isLoser = true; }

                                const angle = Math.atan2(target.pos.y - proj.pos.y, target.pos.x - proj.pos.x);
                                target.vel.x = Math.cos(angle) * 30;
                                target.vel.y = Math.sin(angle) * 30;
                                target.stunFrames = 30;

                                if (target.isDead) {
                                    const winner = entitiesRef.current.find(e => e.id === proj.ownerId);
                                    if (winner) triggerWin(winner.id);
                                }
                            }
                        }
                    });
                }
            }
        } else {
            // === 碰撞逻辑 (子弹 & 导弹) ===
            const isMissile = proj.type === 'missile';
            if (proj.pos.x < 0 || proj.pos.x > canvas.width || proj.pos.y > canvas.height + 100 || proj.pos.y < -200) proj.active = false;

            entitiesRef.current.forEach(target => {
                if (target.id !== proj.ownerId && !target.isDead && proj.active) {
                    const hitDist = isMissile ? 50 : 30; 
                    if (Math.abs(proj.pos.x - target.pos.x) < hitDist &&
                        proj.pos.y > target.pos.y - 75 && proj.pos.y < target.pos.y + 10) {

                        proj.active = false;
                        const damage = isMissile ? 35 : 15; // 导弹伤害增加
                        target.health -= damage; 
                        target.stunFrames = isMissile ? 40 : 10;
                        shakeRef.current = isMissile ? 25 : 5;

                        isMissile ? playExplodeSound() : playHitSound();

                        // 导弹击中特效
                        if (isMissile) {
                             spawnParticles(target.pos.x, target.pos.y - 35, '#ff5500', 40, 10);
                             spawnParticles(target.pos.x, target.pos.y - 35, '#555', 20, 5);
                        } else {
                             spawnParticles(target.pos.x, target.pos.y - 35, '#ff0000', 10, 8);
                        }

                        target.vel.x += proj.vel.x * (isMissile ? 1.2 : 0.3); 
                        target.vel.y -= isMissile ? 15 : 5;

                        if (target.health <= 0) {
                            target.health = 0; 
                            target.isDead = true;
                            target.isLoser = true;
                            target.vel.x = proj.vel.x * 0.8;
                            const winner = entitiesRef.current.find(e => e.id === proj.ownerId);
                            if (winner) triggerWin(winner.id);
                        }
                    }
                }
            });
        }
    });
    projectilesRef.current = projectilesRef.current.filter(p => p.active);

    // === 3. 实体更新 ===
    entitiesRef.current.forEach(entity => {
      // 检查武器是否过期
      if (entity.heldWeapon) {
          entity.weaponDuration--;
          if (entity.weaponDuration <= 0) {
              entity.heldWeapon = null;
              spawnParticles(entity.pos.x, entity.pos.y - 40, '#888', 5, 5); // 消失特效
          }
      }

      if (gameState === GameState.VICTORY_ANIMATION && entity.isWinner) {
          entity.isAttacking = false; entity.attackFrame = 0; entity.isCrouching = false;
          const targetX = canvas.width / 2;
          const targetY = canvas.height / 3;
          entity.pos.x += (targetX - entity.pos.x) * 0.05;
          entity.pos.y += (targetY - entity.pos.y) * 0.05;
          entity.pos.y += Math.sin(frameRef.current * 0.08) * 0.8;
          entity.vel.x = 0; entity.vel.y = 0;
          if (frameRef.current % 3 === 0) spawnConfetti(canvas.width);
          return;
      }

      // 拾取武器
      if (!entity.isDead) {
          const canPickUp = !entity.heldWeapon || entity.ammo <= 0;

          if (canPickUp) {
            const itemIndex = fallingItemsRef.current.findIndex(item => {
                const dx = Math.abs(entity.pos.x - (item.pos.x + item.width/2));
                const dy = Math.abs((entity.pos.y - 35) - (item.pos.y + item.height/2));
                return dx < 50 && dy < 60;
            });

            if (itemIndex !== -1) {
                const item = fallingItemsRef.current[itemIndex];
                entity.heldWeapon = item.type;
                entity.weaponDuration = WEAPON_LIFETIME; 
                switch(item.type) {
                    case 'pistol': entity.ammo = 6; break;
                    case 'bomb': entity.ammo = 3; break;
                    case 'sword': entity.ammo = 8; break;
                    case 'atom_bomb': entity.ammo = 1; break; 
                    case 'missile': entity.ammo = 2; break; // 导弹只有2发
                    case 'dragon': entity.ammo = 1; break; 
                    case 'bomber': entity.ammo = 1; break; // 轰炸机召唤一次
                }
                fallingItemsRef.current.splice(itemIndex, 1);
                playJumpSound();
                spawnParticles(entity.pos.x, entity.pos.y - 30, '#fff', 5, 5);
            }
          }
      }

      // 物理引擎
      const prevY = entity.pos.y;
      entity.vel.y += GRAVITY;

      if (!entity.isLoser && entity.stunFrames > 0) {
           entity.stunFrames--; 
           entity.vel.x *= 0.95; 
      } else if (!entity.isLoser) {
          const currentFriction = entity.isCrouching && entity.isGrounded ? 0.4 : FRICTION;
          entity.vel.x *= currentFriction;
      } else {
          entity.vel.x *= 0.99; 
      }

      entity.pos.x += entity.vel.x;
      entity.pos.y += entity.vel.y;

      // 碰撞检测
      entity.isGrounded = false;
      if (entity.pos.y >= GROUND_Y) {
          if (!entity.isLoser) {
            entity.pos.y = GROUND_Y;
            entity.vel.y = 0;
            entity.isGrounded = true;
          }
      }
      if (entity.vel.y >= 0 && !entity.isDead) {
          PLATFORMS.forEach(plat => {
              if (entity.pos.x > plat.x - 10 && entity.pos.x < plat.x + plat.width + 10) {
                  if (prevY <= plat.y && entity.pos.y >= plat.y) {
                      entity.pos.y = plat.y;
                      entity.vel.y = 0;
                      entity.isGrounded = true;
                  }
              }
          });
      }

      if (!entity.isLoser) {
        if (entity.pos.x < 10) { entity.pos.x = 10; entity.vel.x *= -0.5; }
        if (entity.pos.x > canvas.width - 10) { entity.pos.x = canvas.width - 10; entity.vel.x *= -0.5; }
      }

      if (gameState === GameState.VICTORY_ANIMATION || entity.isDead || entity.stunFrames > 0) return;

      if (entity.attackCooldown > 0) entity.attackCooldown--;
      if (entity.isAttacking) {
          entity.attackFrame++;
          if (entity.attackFrame > 15) { 
              entity.isAttacking = false;
              entity.attackFrame = 0;
          }
      }

      let moveLeft = false, moveRight = false, jump = false, crouch = false, attack = false;

      // Input P1
      if (entity.playerIndex === 0) {
        if (keysRef.current.has('KeyA')) moveLeft = true;
        if (keysRef.current.has('KeyD')) moveRight = true;
        if (keysRef.current.has('KeyW')) jump = true;
        if (keysRef.current.has('KeyS')) crouch = true;
        if (keysRef.current.has('Space')) attack = true;
      }

      // Input P2 / AI
      if (entity.playerIndex === 1) {
          if (gameMode === 'PVP') {
            if (keysRef.current.has('ArrowLeft')) moveLeft = true;
            if (keysRef.current.has('ArrowRight')) moveRight = true;
            if (keysRef.current.has('ArrowUp')) jump = true;
            if (keysRef.current.has('ArrowDown')) crouch = true;
            if (keysRef.current.has('Enter')) attack = true;
          } else {
            // AI Logic
            const p1 = entitiesRef.current.find(e => e.playerIndex === 0);
            if (p1 && !p1.isDead) {
                let targetX = p1.pos.x;
                let targetY = p1.pos.y;

                if (!entity.heldWeapon && fallingItemsRef.current.length > 0) {
                    let minDist = 9999;
                    fallingItemsRef.current.forEach(item => {
                        const d = Math.abs(item.pos.x - entity.pos.x) + Math.abs(item.pos.y - entity.pos.y);
                        if (d < minDist) {
                            minDist = d;
                            targetX = item.pos.x;
                            targetY = item.pos.y;
                        }
                    });
                }

                const distX = targetX - entity.pos.x;
                const distY = targetY - entity.pos.y; 

                if (Math.abs(distX) > 40) {
                    distX > 0 ? moveRight = true : moveLeft = true;
                } else if (!entity.heldWeapon && Math.abs(distX) < 20) {
                     distX > 0 ? moveLeft = true : moveRight = true;
                }

                if (entity.isGrounded) {
                     if (distY < -100 || (Math.random() < 0.02)) {
                         jump = true;
                     }
                }

                const absDistX = Math.abs(p1.pos.x - entity.pos.x);
                entity.facingRight = (p1.pos.x - entity.pos.x) > 0;

                // AI 攻击逻辑
                let attackRange = ATTACK_RANGE;
                if (entity.heldWeapon === 'pistol') attackRange = 600;
                if (entity.heldWeapon === 'atom_bomb') attackRange = 300; 
                if (entity.heldWeapon === 'missile') attackRange = 700; 
                if (entity.heldWeapon === 'dragon') attackRange = 400; 
                if (entity.heldWeapon === 'bomber') attackRange = 800; // 只要有敌人就放

                if (absDistX < attackRange && Math.abs(p1.pos.y - entity.pos.y) < 100) {
                    if (entity.attackCooldown === 0 && Math.random() < 0.05) attack = true;
                }
            }
          }
      }

      entity.isCrouching = crouch && entity.isGrounded;
      if (!entity.isCrouching) {
          if (moveLeft) { entity.vel.x -= MOVE_SPEED; entity.facingRight = false; }
          if (moveRight) { entity.vel.x += MOVE_SPEED; entity.facingRight = true; }
      }
      if (jump && entity.isGrounded && !entity.isCrouching) {
          entity.vel.y = JUMP_FORCE;
          playJumpSound();
      }

      // === 攻击处理 ===
      if (attack && entity.attackCooldown === 0) {
          entity.attackCooldown = ATTACK_COOLDOWN;
          entity.isAttacking = true;
          entity.attackFrame = 5;

          if (entity.heldWeapon === 'pistol') {
              playShootSound();
              entity.vel.x += entity.facingRight ? -8 : 8;
              entity.vel.y -= 2;

              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'pistol',
                  pos: { x: entity.pos.x + (entity.facingRight ? 40 : -40), y: entity.pos.y - 45 },
                  vel: { x: entity.facingRight ? 20 : -20, y: (Math.random()-0.5) * 2 }, 
                  ownerId: entity.id,
                  width: 12, height: 4, active: true
              });
              entity.ammo--;
          } else if (entity.heldWeapon === 'bomb') {
              entity.vel.x += entity.facingRight ? -2 : 2;
              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'bomb',
                  pos: { x: entity.pos.x, y: entity.pos.y - 60 },
                  vel: { x: entity.facingRight ? 12 : -12, y: -12 },
                  ownerId: entity.id,
                  width: 20, height: 20, active: true
              });
              entity.ammo--;
          } else if (entity.heldWeapon === 'atom_bomb') {
              entity.vel.x += entity.facingRight ? -4 : 4;
              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'atom_bomb',
                  pos: { x: entity.pos.x, y: entity.pos.y - 70 },
                  vel: { x: entity.facingRight ? 8 : -8, y: -10 },
                  ownerId: entity.id,
                  width: 30, height: 40, active: true
              });
              entity.ammo--; 
          } else if (entity.heldWeapon === 'missile') {
              playShootSound(); 
              entity.vel.x += entity.facingRight ? -10 : 10; 
              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'missile',
                  pos: { x: entity.pos.x + (entity.facingRight ? 50 : -50), y: entity.pos.y - 50 },
                  vel: { x: entity.facingRight ? 10 : -10, y: -5 }, 
                  ownerId: entity.id,
                  width: 20, height: 8, active: true
              });
              entity.ammo--; 
          } else if (entity.heldWeapon === 'dragon') {
              playDragonRoar();
              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'dragon',
                  pos: { x: entity.pos.x, y: entity.pos.y - 100 },
                  vel: { x: 0, y: 0 },
                  ownerId: entity.id,
                  width: 40, height: 40, active: true,
                  dragonState: 'enter', 
                  remainingHits: 5,
                  dragonPathProgress: 0,
                  dragonSegments: undefined
              });
              entity.ammo--;
          } else if (entity.heldWeapon === 'bomber') {
              // 呼叫轰炸机
              const startX = entity.facingRight ? -100 : canvas.width + 100;
              playShootSound(); // 使用枪声模拟无线电
              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'bomber',
                  pos: { x: startX, y: 100 }, // 高空飞行
                  vel: { x: 0, y: 0 },
                  ownerId: entity.id,
                  width: 60, height: 20, active: true,
                  bomberState: 'fly_in',
                  bombDropCount: 0
              });
              entity.ammo--;
          } else {
              // == 近战武器 ==
              playAttackSound();

              let range = ATTACK_RANGE;
              let dmg = ATTACK_DAMAGE;
              let knockbackX = 15;
              let knockbackY = -8;
              let selfPush = 10;
              let hitEffectSize = 12;

              if (entity.heldWeapon === 'sword') {
                  range = 140; dmg = 15; knockbackX = 12; selfPush = 12; entity.attackCooldown = 20; 
              }

              entity.vel.x = entity.facingRight ? selfPush : -selfPush;

              const hitX = entity.facingRight ? entity.pos.x + range/2 : entity.pos.x - range/2;
              const hitY = entity.isCrouching ? entity.pos.y - 20 : entity.pos.y - 45;

              let hitSomething = false;

              entitiesRef.current.forEach(target => {
                  if (target !== entity && !target.isDead) {
                      const dy = (target.pos.y - 35) - hitY;
                      if (Math.abs(target.pos.x - entity.pos.x) < range && Math.abs(dy) < 60 && 
                          ((entity.facingRight && target.pos.x > entity.pos.x) || (!entity.facingRight && target.pos.x < entity.pos.x))) {

                          if (!entity.isCrouching && target.isCrouching) {
                              spawnParticles(target.pos.x, target.pos.y - 40, '#aaa', 2, 2);
                              return; 
                          }

                          target.health -= dmg;
                          hitSomething = true;

                          target.vel.x = entity.facingRight ? knockbackX : -knockbackX; 
                          target.vel.y = knockbackY; 
                          target.stunFrames = 20; 

                          shakeRef.current = Math.floor(dmg / 2);
                          spawnParticles(target.pos.x, target.pos.y - 40, target.color, hitEffectSize, 10);
                          playHitSound();

                          if (target.health <= 0) {
                              target.health = 0;
                              target.isDead = true;
                              target.isLoser = true;
                              target.vel.x = entity.facingRight ? 30 : -30;
                              target.vel.y = -20;
                              triggerWin(entity.id);
                          }
                      }
                  }
              });

              if (hitSomething && entity.heldWeapon) {
                  entity.ammo--;
              }
          }

          // 弹药耗尽检查
          if (entity.heldWeapon && entity.ammo <= 0) {
              entity.heldWeapon = null;
              spawnParticles(entity.pos.x, entity.pos.y - 40, '#888', 5, 5); 
          }
      }
    });

    particlesRef.current.forEach(p => {
        ctx.fillStyle = p.color;
        // 支持透明度变化
        const alpha = p.currentAlpha !== undefined ? p.currentAlpha : (p.life / p.maxLife);
        ctx.globalAlpha = alpha;

        ctx.beginPath(); ctx.arc(p.pos.x, p.pos.y, p.size, 0, Math.PI * 2); ctx.fill();
        ctx.globalAlpha = 1.0;
    });

    entitiesRef.current.forEach(entity => drawEntity(ctx, entity));

    // === 闪光特效 (最上层) ===
    if (flashRef.current > 0) {
        ctx.fillStyle = `rgba(255, 255, 255, ${flashRef.current})`;
        ctx.fillRect(-shakeX, -shakeY, canvas.width, canvas.height); // 抵消shake，保证全屏
    }

    ctx.restore();
  };

  const tick = () => {
    update();
    draw();
    requestRef.current = requestAnimationFrame(tick);
  };

  useEffect(() => {
    if (canvasRef.current) {
        canvasRef.current.width = window.innerWidth;
        canvasRef.current.height = window.innerHeight;
    }
    requestRef.current = requestAnimationFrame(tick);
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [gameState]);

  return (
    <canvas 
        ref={canvasRef} 
        className="block w-full h-full bg-slate-900"
    />
  );
};

export default GameCanvas;

import React, { useRef, useEffect, useCallback } from 'react';
import { GameState, Entity, Vector, Particle, GameStats, GameMode, FallingItem, Projectile, WeaponType, Platform } from '../types';
import { playJumpSound, playAttackSound, playHitSound, playShootSound, playExplodeSound, playDragonRoar } from '../services/audioService';

interface GameCanvasProps {
  gameState: GameState;
  setGameState: (state: GameState) => void;
  setStats: React.Dispatch<React.SetStateAction<GameStats>>;
  setPlayers: (players: Entity[]) => void;
  gameMode: GameMode;
}

// === 物理参数 (提速版) ===
const GRAVITY = 0.8; 
const FRICTION = 0.82; 
const MOVE_SPEED = 2; 
const JUMP_FORCE = -22; 
const GROUND_Y = 600;
const ATTACK_COOLDOWN = 18; 
const ATTACK_RANGE = 100;
const ATTACK_DAMAGE = 8;

// === 武器生成配置 ===
const MAX_WEAPONS_PER_GAME = 6; 
const WEAPON_SPAWN_INTERVAL = 900; 
const WEAPON_LIFETIME = 15 * 60; 

// === 关卡设计 ===
const PLATFORMS: Platform[] = [
    { x: 300, y: 450, width: 200, height: 20 },
    { x: 800, y: 450, width: 200, height: 20 },
    { x: 500, y: 250, width: 300, height: 20 } 
];

const drawEntity = (ctx: CanvasRenderingContext2D, entity: Entity) => {
    ctx.save();

    const centerX = entity.pos.x;
    const centerY = entity.pos.y; // Feet position

    ctx.translate(centerX, centerY);

    if (entity.isDead) {
         ctx.rotate(Math.PI / 2 * (entity.facingRight ? 1 : -1));
         ctx.translate(0, -10);
    }

    if (!entity.facingRight) ctx.scale(-1, 1);

    // Draw body
    ctx.fillStyle = entity.color;
    ctx.strokeStyle = entity.color;
    ctx.lineWidth = 4;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    const crouchOffset = entity.isCrouching ? 20 : 0;

    // Head
    ctx.beginPath();
    ctx.arc(0, -entity.height + 20 + crouchOffset, 12, 0, Math.PI * 2);
    ctx.fill();

    // Body
    ctx.beginPath();
    ctx.moveTo(0, -entity.height + 32 + crouchOffset);
    ctx.lineTo(0, -25 + crouchOffset);
    ctx.stroke();

    // Legs
    ctx.beginPath();
    ctx.moveTo(0, -25 + crouchOffset);
    if (entity.isCrouching) {
        ctx.lineTo(-15, -5);
        ctx.moveTo(0, -25 + crouchOffset);
        ctx.lineTo(15, -5);
    } else if (Math.abs(entity.vel.x) > 0.1 && entity.isGrounded) {
        const walkCycle = Math.sin(Date.now() / 100) * 10;
        ctx.lineTo(-10 + walkCycle, 0);
        ctx.moveTo(0, -25 + crouchOffset);
        ctx.lineTo(10 - walkCycle, 0);
    } else {
        ctx.lineTo(-10, 0);
        ctx.moveTo(0, -25 + crouchOffset);
        ctx.lineTo(10, 0);
    }
    ctx.stroke();

    // Arms
    ctx.beginPath();
    const shoulderY = -entity.height + 40 + crouchOffset;
    ctx.moveTo(0, shoulderY);

    if (entity.isWinner) {
        ctx.lineTo(-20, shoulderY - 30);
        ctx.moveTo(0, shoulderY);
        ctx.lineTo(20, shoulderY - 30);
    } else if (entity.isAttacking) {
        const attackProgress = entity.attackFrame / 15;
        ctx.lineTo(25, shoulderY - 10 + attackProgress * 20);
    } else if (entity.heldWeapon) {
        ctx.lineTo(15, shoulderY + 5);

        ctx.save();
        ctx.translate(15, shoulderY + 5);

        if (entity.heldWeapon === 'pistol') {
            ctx.fillStyle = '#555';
            ctx.fillRect(0, -5, 15, 5);
            ctx.fillRect(0, 0, 5, 5);
        } else if (entity.heldWeapon === 'sword') {
            ctx.fillStyle = '#ccc';
            ctx.fillRect(0, -25, 4, 30);
            ctx.fillStyle = '#8B4513';
            ctx.fillRect(-3, 0, 10, 2);
        } else if (entity.heldWeapon === 'bomb' || entity.heldWeapon === 'atom_bomb') {
            ctx.fillStyle = '#000';
            ctx.beginPath();
            ctx.arc(5, 0, 8, 0, Math.PI*2);
            ctx.fill();
            ctx.strokeStyle = '#fff';
            ctx.beginPath();
            ctx.moveTo(5, -8);
            ctx.quadraticCurveTo(10, -15, 15, -10);
            ctx.stroke();
             if (entity.heldWeapon === 'atom_bomb') {
                ctx.fillStyle = 'yellow';
                ctx.font = '10px Arial';
                ctx.fillText('☢', 2, 4);
            }
        } else if (entity.heldWeapon === 'missile') {
             ctx.fillStyle = 'green';
             ctx.fillRect(0, -5, 20, 10);
             ctx.fillStyle = 'red';
             ctx.fillRect(20, -5, 5, 10);
        } else if (entity.heldWeapon === 'dragon') {
             ctx.font = '20px serif';
             ctx.fillText('🐉', 0, 5);
        } else if (entity.heldWeapon === 'bomber') {
             // 无线电/对讲机外观
             ctx.fillStyle = '#333';
             ctx.fillRect(0, -10, 10, 16);
             ctx.fillStyle = '#000';
             ctx.fillRect(2, -15, 2, 5); // 天线
             ctx.fillStyle = '#f00';
             ctx.beginPath(); ctx.arc(5, -5, 2, 0, Math.PI*2); ctx.fill(); // 信号灯
        }
        ctx.restore();

    } else {
        if (Math.abs(entity.vel.x) > 0.1) {
             const armCycle = Math.cos(Date.now() / 100) * 10;
             ctx.lineTo(armCycle, shoulderY + 15);
        } else {
             ctx.lineTo(0, shoulderY + 20);
        }
    }
    ctx.stroke();

    ctx.restore();
};

const GameCanvas: React.FC<GameCanvasProps> = ({ gameState, setGameState, setStats, setPlayers, gameMode }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();
  const frameRef = useRef<number>(0);

  const entitiesRef = useRef<Entity[]>([]);
  const particlesRef = useRef<Particle[]>([]);
  const fallingItemsRef = useRef<FallingItem[]>([]);
  const projectilesRef = useRef<Projectile[]>([]);

  // 武器生成控制
  const spawnedWeaponCountRef = useRef<number>(0); 
  const atomBombIndexRef = useRef<number>(-1); 
  const missileIndexRef = useRef<number>(-1); 
  const dragonIndexRef = useRef<number>(-1); 

  const keysRef = useRef<Set<string>>(new Set());
  const statsRef = useRef<GameStats>({ winner: null, mode: gameMode, duration: 0 });
  const shakeRef = useRef<number>(0);
  const flashRef = useRef<number>(0); 

  // 初始化对决
  const initGame = useCallback(() => {
    const newEntities: Entity[] = [];

    // P1 (左侧)
    newEntities.push({
      id: 'p1', type: 'player', playerIndex: 0,
      pos: { x: 100, y: 100 }, vel: { x: 0, y: 0 }, 
      width: 40, height: 70, color: '#3b82f6', 
      isGrounded: false, isCrouching: false, health: 100, maxHealth: 100, isDead: false,
      facingRight: true, attackCooldown: 0, isAttacking: false, attackFrame: 0,
      heldWeapon: null, ammo: 0, weaponDuration: 0, stunFrames: 0
    });

    // P2/CPU (右侧)
    newEntities.push({
      id: 'p2', type: 'player', playerIndex: 1,
      pos: { x: window.innerWidth - 100, y: 100 }, vel: { x: 0, y: 0 },
      width: 40, height: 70, color: '#facc15',
      isGrounded: false, isCrouching: false, health: 100, maxHealth: 100, isDead: false,
      facingRight: false, attackCooldown: 0, isAttacking: false, attackFrame: 0,
      heldWeapon: null, ammo: 0, weaponDuration: 0, stunFrames: 0
    });

    entitiesRef.current = newEntities;
    particlesRef.current = [];
    fallingItemsRef.current = [];
    projectilesRef.current = [];
    spawnedWeaponCountRef.current = 0; 

    const indices = Array.from({length: MAX_WEAPONS_PER_GAME}, (_, i) => i);
    for (let i = indices.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [indices[i], indices[j]] = [indices[j], indices[i]];
    }

    atomBombIndexRef.current = indices[0];
    missileIndexRef.current = indices[1];
    dragonIndexRef.current = indices[2]; 

    statsRef.current = { winner: null, mode: gameMode, duration: 0 };
    frameRef.current = 0;
    shakeRef.current = 0;
    flashRef.current = 0;

    setStats(statsRef.current);
    setPlayers([...entitiesRef.current]);
  }, [gameMode, setStats, setPlayers]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        if (e.repeat) return;
        keysRef.current.add(e.code);
        if (e.code === 'KeyR' && gameState === GameState.GAME_OVER) {
             setGameState(GameState.PLAYING);
        }
    };
    const handleKeyUp = (e: KeyboardEvent) => keysRef.current.delete(e.code);
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, [gameState, setGameState]);

  useEffect(() => {
    if (gameState === GameState.PLAYING) {
      initGame();
    }
  }, [gameState, initGame]);

  const spawnParticles = (x: number, y: number, color: string, count: number, speed = 8, lifeMultiplier = 1) => {
      for(let i=0; i<count; i++) {
          particlesRef.current.push({
              id: Math.random().toString(),
              pos: {x, y},
              vel: { x: (Math.random() - 0.5) * speed, y: (Math.random() - 0.5) * speed },
              life: (20 + Math.random() * 20) * lifeMultiplier,
              maxLife: 40 * lifeMultiplier,
              color: color,
              size: Math.random() * 6 + 3,
              gravity: 0.5 
          });
      }
  };

  const spawnMushroomCloud = (x: number, y: number) => {
    // 1. 蘑菇柄 (上升的烟柱)
    for (let i = 0; i < 20; i++) {
      particlesRef.current.push({
        id: Math.random().toString(),
        pos: { x: x + (Math.random()-0.5)*20, y: y },
        vel: { x: (Math.random()-0.5) * 1, y: -2 - Math.random() * 3 },
        life: 180,
        maxLife: 180,
        color: i % 2 === 0 ? '#555' : '#333',
        size: 15 + Math.random() * 10,
        gravity: -0.05, // 轻微上升
        growth: 0.3, // 膨胀
        alphaDecay: 0.005,
        currentAlpha: 0.8
      });
    }

    // 2. 蘑菇盖 (顶部扩散)
    for (let i = 0; i < 40; i++) {
      const angle = (Math.PI / 40) * i * 2; // 360度
      const speed = 2 + Math.random() * 3;
      particlesRef.current.push({
        id: Math.random().toString(),
        pos: { x: x, y: y - 80 },
        vel: { x: Math.cos(angle) * speed, y: Math.sin(angle) * speed * 0.5 - 1 },
        life: 200,
        maxLife: 200,
        color: Math.random() > 0.5 ? '#ff4500' : '#ff8800', // 橙红火光
        size: 20 + Math.random() * 10,
        gravity: -0.02,
        growth: 0.5, // 快速膨胀
        alphaDecay: 0.008,
        currentAlpha: 0.9
      });
    }

    // 3. 底部冲击波 (贴地尘土)
    for (let i = 0; i < 30; i++) {
        const dir = i % 2 === 0 ? 1 : -1;
        particlesRef.current.push({
            id: Math.random().toString(),
            pos: { x: x, y: y },
            vel: { x: dir * (5 + Math.random()*10), y: -1 },
            life: 100, maxLife: 100,
            color: '#777',
            size: 10,
            gravity: 0,
            growth: 0.8,
            alphaDecay: 0.02,
            currentAlpha: 0.6
        });
    }
  };

  const spawnConfetti = (width: number) => {
      const colors = ['#FFD700', '#FF6347', '#00BFFF', '#32CD32', '#FF69B4', '#FFFFFF'];
      const x = Math.random() * width;
      const y = -10; 
      const color = colors[Math.floor(Math.random() * colors.length)];
      particlesRef.current.push({
          id: Math.random().toString(),
          pos: { x, y },
          vel: { x: (Math.random() - 0.5) * 2, y: Math.random() * 2 + 1 },
          life: 200, maxLife: 200, color, size: Math.random() * 4 + 3, gravity: 0.02 
      });
  };

  const spawnFallingItem = (canvasWidth: number) => {
      let type: WeaponType;

      const count = spawnedWeaponCountRef.current;

      if (count === atomBombIndexRef.current) {
          type = 'atom_bomb';
      } else if (count === missileIndexRef.current) {
          type = 'missile';
      } else if (count === dragonIndexRef.current) {
          type = 'dragon';
      } else {
          // 移除 stick 和 blade，加入 bomber
          const normalPool: WeaponType[] = ['pistol', 'bomb', 'sword', 'bomber'];
          type = normalPool[Math.floor(Math.random() * normalPool.length)];
      }

      fallingItemsRef.current.push({
          id: Math.random().toString() + "_" + Date.now(),
          type,
          pos: { x: 100 + Math.random() * (canvasWidth - 200), y: -50 },
          vel: { x: (Math.random() - 0.5) * 2, y: 2 },
          width: 30, height: 30,
          onGround: false
      });
      spawnedWeaponCountRef.current++;
  };

  const update = () => {
    if (gameState !== GameState.PLAYING && gameState !== GameState.VICTORY_ANIMATION) return;
    const canvas = canvasRef.current;
    if (!canvas) return;

    frameRef.current++;
    if (shakeRef.current > 0) shakeRef.current--;
    if (flashRef.current > 0) flashRef.current -= 0.02; 
    if (gameState === GameState.PLAYING) statsRef.current.duration += 1/60;

    const triggerWin = (winnerId: string) => {
        if (statsRef.current.winner) return;
        const winner = entitiesRef.current.find(e => e.id === winnerId);
        if (winner) winner.isWinner = true;
        statsRef.current.winner = winnerId === 'p1' ? 'P1' : 'P2';
        setGameState(GameState.VICTORY_ANIMATION);
        setTimeout(() => setGameState(GameState.GAME_OVER), 4000);
    };

    // === 0. 掉落物生成 ===
    if (gameState === GameState.PLAYING && 
        spawnedWeaponCountRef.current < MAX_WEAPONS_PER_GAME && 
        frameRef.current > 60 && 
        frameRef.current % WEAPON_SPAWN_INTERVAL === 0) {
        spawnFallingItem(canvas.width);
    }

    // === 1. 掉落物逻辑 ===
    fallingItemsRef.current.forEach(item => {
        item.vel.y += 0.2; 
        if (item.vel.y > 8) item.vel.y = 8;

        const prevY = item.pos.y;
        item.pos.x += item.vel.x;
        item.pos.y += item.vel.y;

        if (item.pos.y >= GROUND_Y - item.height) {
            item.pos.y = GROUND_Y - item.height;
            item.onGround = true;
            item.vel.y = -item.vel.y * 0.5;
            item.vel.x *= 0.8;
        }

        if (item.vel.y > 0) {
            PLATFORMS.forEach(plat => {
                if (item.pos.x + item.width > plat.x && item.pos.x < plat.x + plat.width) {
                    if (prevY + item.height <= plat.y && item.pos.y + item.height >= plat.y) {
                        item.pos.y = plat.y - item.height;
                        item.onGround = true;
                        item.vel.y = -item.vel.y * 0.5;
                        item.vel.x *= 0.8;
                    }
                }
            });
        }
    });

    // === 2. 投射物逻辑 (子弹、炸弹、导弹、神龙、轰炸机) ===
    projectilesRef.current.forEach(proj => {
        if (!proj.active) return;

        // --- 轰炸机逻辑 ---
        if (proj.type === 'bomber') {
            const target = entitiesRef.current.find(e => e.id !== proj.ownerId && !e.isDead);
            const targetX = target ? target.pos.x : canvas.width / 2;
            const flyHeight = 150;

            // 确保Y轴高度
            proj.pos.y += (flyHeight - proj.pos.y) * 0.1;

            if (proj.bomberState === 'fly_in') {
                // 飞向目标X
                const dx = targetX - proj.pos.x;
                const dir = dx > 0 ? 1 : -1;

                // 快速接近
                proj.vel.x = dir * 10; 

                // 到达目标附近，开始投弹
                if (Math.abs(dx) < 60) {
                    proj.bomberState = 'bombing';
                    proj.bombDropCount = 0;
                    proj.lastHitFrame = frameRef.current;
                }
            } else if (proj.bomberState === 'bombing') {
                // 减速投弹
                proj.vel.x = proj.vel.x > 0 ? 5 : -5;

                const interval = 12; // 投弹间隔帧数
                if (frameRef.current - (proj.lastHitFrame || 0) > interval) {
                    proj.lastHitFrame = frameRef.current;
                    // 投掷炸弹
                    projectilesRef.current.push({
                        id: Math.random().toString(),
                        type: 'bomb',
                        pos: { x: proj.pos.x, y: proj.pos.y + 20 },
                        vel: { x: proj.vel.x * 0.5, y: 5 }, // 继承一点惯性
                        ownerId: proj.ownerId,
                        width: 20, height: 20, active: true
                    });
                    if (proj.bombDropCount !== undefined) proj.bombDropCount++;

                    if (proj.bombDropCount && proj.bombDropCount >= 3) {
                         proj.bomberState = 'fly_out';
                    }
                }
            } else if (proj.bomberState === 'fly_out') {
                // 加速飞离
                proj.vel.x = proj.vel.x > 0 ? 15 : -15;
                if (proj.pos.x < -200 || proj.pos.x > canvas.width + 200) {
                    proj.active = false;
                }
            }

            proj.pos.x += proj.vel.x;
            return;
        }

        // --- 神龙逻辑 (优化动作) ---
        if (proj.type === 'dragon') {
            const dragonSegmentsCount = 20; // 增加段数，更流畅
            if (!proj.dragonSegments || proj.dragonSegments.length === 0) {
                proj.dragonSegments = Array.from({ length: dragonSegmentsCount }, () => ({ ...proj.pos }));
            }

            if (proj.dragonState === 'enter') {
                if (!proj.dragonPathProgress) proj.dragonPathProgress = 0;
                proj.dragonPathProgress += 0.02;

                shakeRef.current = 8;
                if (Math.random() < 0.1) playExplodeSound();

                const w = canvas.width;
                const h = canvas.height;
                const t = proj.dragonPathProgress * Math.PI * 2;

                // 更复杂的入场轨迹
                const targetX = w/2 + (w/2 - 50) * Math.cos(t) * Math.sin(t*0.5);
                const targetY = h/3 + (h/4) * Math.sin(2*t);

                proj.vel.x = (targetX - proj.pos.x) * 0.2;
                proj.vel.y = (targetY - proj.pos.y) * 0.2;
                proj.pos.x += proj.vel.x;
                proj.pos.y += proj.vel.y;

                if (proj.dragonPathProgress >= 1.5) {
                    proj.dragonState = 'hunt';
                    shakeRef.current = 0;
                }
            } else if (proj.dragonState === 'hunt') {
                const target = entitiesRef.current.find(e => e.id !== proj.ownerId && !e.isDead);
                if (target) {
                    const dx = target.pos.x - proj.pos.x;
                    const dy = (target.pos.y - 40) - proj.pos.y;
                    const dist = Math.sqrt(dx*dx + dy*dy);

                    const speed = 7; // 略微提速
                    // 增加一点惯性，避免转弯太生硬
                    proj.vel.x = (proj.vel.x * 20 + (dx / dist) * speed) / 21;
                    proj.vel.y = (proj.vel.y * 20 + (dy / dist) * speed) / 21;

                    proj.pos.x += proj.vel.x;
                    proj.pos.y += proj.vel.y;

                    if (dist < 50) {
                        const now = frameRef.current;
                        if (!proj.lastHitFrame || now - proj.lastHitFrame > 30) {
                            proj.lastHitFrame = now;
                            if (proj.remainingHits && proj.remainingHits > 0) {
                                proj.remainingHits--;

                                target.health -= 5;
                                target.stunFrames = 20;
                                target.vel.x = (Math.random()-0.5) * 30;
                                target.vel.y = -15;

                                playHitSound();
                                spawnParticles(target.pos.x, target.pos.y, '#FFD700', 20, 8);
                                shakeRef.current = 15;

                                if (target.health <= 0) {
                                    target.health = 0;
                                    target.isDead = true;
                                    target.isLoser = true;
                                    triggerWin(proj.ownerId);
                                }

                                if (proj.remainingHits <= 0) {
                                    proj.active = false;
                                    // 神龙离去特效
                                    spawnParticles(proj.pos.x, proj.pos.y, '#FFD700', 80, 15);
                                }
                            }
                        }
                    }
                } else {
                    proj.vel.y -= 0.5;
                    proj.pos.x += Math.sin(frameRef.current * 0.1) * 5;
                    proj.pos.y += proj.vel.y;
                    if (proj.pos.y < -300) proj.active = false;
                }
            }

            if (proj.dragonSegments && proj.dragonSegments.length > 0) {
                proj.dragonSegments[0] = { ...proj.pos };
                for (let i = 1; i < proj.dragonSegments.length; i++) {
                    const current = proj.dragonSegments[i];
                    const prev = proj.dragonSegments[i-1];
                    const dx = prev.x - current.x;
                    const dy = prev.y - current.y;
                    const d = Math.sqrt(dx*dx + dy*dy);
                    const spacing = 18; 

                    if (d > spacing) {
                        const ratio = (d - spacing) / d;
                        current.x += dx * ratio;
                        current.y += dy * ratio;
                    }
                }
            }
            return; 
        }

        // --- 巡航导弹逻辑 (东风) ---
        if (proj.type === 'missile') {
            if (frameRef.current % 2 === 0) {
                // 浓烟尾迹
                particlesRef.current.push({
                    id: Math.random().toString(),
                    pos: { x: proj.pos.x, y: proj.pos.y },
                    vel: { x: -proj.vel.x * 0.1, y: -proj.vel.y * 0.1 }, // 惯性残留
                    life: 40, maxLife: 40, color: '#aaa', size: 6, gravity: 0, growth: 0.2, alphaDecay: 0.05
                });
                // 火焰中心
                particlesRef.current.push({
                    id: Math.random().toString(),
                    pos: { x: proj.pos.x, y: proj.pos.y },
                    vel: { x: -proj.vel.x * 0.5, y: -proj.vel.y * 0.5 },
                    life: 10, maxLife: 10, color: '#ff5500', size: 4, gravity: 0
                });
            }

            const target = entitiesRef.current.find(e => e.id !== proj.ownerId && !e.isDead);
            if (target) {
                const targetX = target.pos.x;
                const targetY = target.pos.y - 35; 
                const dx = targetX - proj.pos.x;
                const dy = targetY - proj.pos.y;
                const dist = Math.sqrt(dx*dx + dy*dy);

                if (dist > 10) {
                    const speed = 8; // 导弹速度
                    // 增加追踪惯性
                    proj.vel.x = (proj.vel.x * 30 + (dx / dist) * speed) / 31;
                    proj.vel.y = (proj.vel.y * 30 + (dy / dist) * speed) / 31;
                }
            }
        }

        proj.pos.x += proj.vel.x;
        proj.pos.y += proj.vel.y;

        // --- 炸弹/原子弹落地 ---
        if (proj.type === 'bomb' || proj.type === 'atom_bomb') {
            const isNuke = proj.type === 'atom_bomb';
            proj.vel.y += GRAVITY; 
            let hitGround = false;
             if (proj.pos.y >= GROUND_Y) { hitGround = true; }
             else if (proj.vel.y > 0) {
                 PLATFORMS.forEach(plat => {
                     if (proj.pos.x > plat.x && proj.pos.x < plat.x + plat.width && 
                         proj.pos.y >= plat.y && proj.pos.y <= plat.y + 20) {
                         hitGround = true;
                     }
                 });
             }

            if (hitGround) {
                proj.active = false;

                if (isNuke) {
                    // === 核爆逻辑升级 ===
                    shakeRef.current = 120; 
                    flashRef.current = 1.0; 
                    playExplodeSound();

                    // 生成蘑菇云
                    spawnMushroomCloud(proj.pos.x, proj.pos.y - 10);

                    // 冲击波伤害范围极大
                    entitiesRef.current.forEach(target => {
                         if (!target.isDead) {
                             target.health = 0;
                             target.isDead = true;
                             target.isLoser = true;
                             // 被吹飞
                             const dir = target.pos.x - proj.pos.x > 0 ? 1 : -1;
                             target.vel.x = dir * 60;
                             target.vel.y = -60;

                             if (target.id !== proj.ownerId) {
                                 const winner = entitiesRef.current.find(e => e.id === proj.ownerId);
                                 if (winner) triggerWin(winner.id);
                             } else {
                                 const enemy = entitiesRef.current.find(e => e.id !== proj.ownerId);
                                 if (enemy) triggerWin(enemy.id);
                             }
                         }
                    });

                } else {
                    shakeRef.current = 25; 
                    playExplodeSound();
                    spawnParticles(proj.pos.x, proj.pos.y, '#ff4500', 40, 15, 2); 

                    entitiesRef.current.forEach(target => {
                        if (!target.isDead) {
                            const dist = Math.sqrt(Math.pow(target.pos.x - proj.pos.x, 2) + Math.pow(target.pos.y - proj.pos.y, 2));
                            if (dist < 180) {
                                target.health -= 25; 
                                if (target.health <= 0) { target.health = 0; target.isDead = true; target.isLoser = true; }

                                const angle = Math.atan2(target.pos.y - proj.pos.y, target.pos.x - proj.pos.x);
                                target.vel.x = Math.cos(angle) * 30;
                                target.vel.y = Math.sin(angle) * 30;
                                target.stunFrames = 30;

                                if (target.isDead) {
                                    const winner = entitiesRef.current.find(e => e.id === proj.ownerId);
                                    if (winner) triggerWin(winner.id);
                                }
                            }
                        }
                    });
                }
            }
        } else {
            // === 碰撞逻辑 (子弹 & 导弹) ===
            const isMissile = proj.type === 'missile';
            if (proj.pos.x < 0 || proj.pos.x > canvas.width || proj.pos.y > canvas.height + 100 || proj.pos.y < -200) proj.active = false;

            entitiesRef.current.forEach(target => {
                if (target.id !== proj.ownerId && !target.isDead && proj.active) {
                    const hitDist = isMissile ? 50 : 30; 
                    if (Math.abs(proj.pos.x - target.pos.x) < hitDist &&
                        proj.pos.y > target.pos.y - 75 && proj.pos.y < target.pos.y + 10) {

                        proj.active = false;
                        const damage = isMissile ? 35 : 15; // 导弹伤害增加
                        target.health -= damage; 
                        target.stunFrames = isMissile ? 40 : 10;
                        shakeRef.current = isMissile ? 25 : 5;

                        isMissile ? playExplodeSound() : playHitSound();

                        // 导弹击中特效
                        if (isMissile) {
                             spawnParticles(target.pos.x, target.pos.y - 35, '#ff5500', 40, 10);
                             spawnParticles(target.pos.x, target.pos.y - 35, '#555', 20, 5);
                        } else {
                             spawnParticles(target.pos.x, target.pos.y - 35, '#ff0000', 10, 8);
                        }

                        target.vel.x += proj.vel.x * (isMissile ? 1.2 : 0.3); 
                        target.vel.y -= isMissile ? 15 : 5;

                        if (target.health <= 0) {
                            target.health = 0; 
                            target.isDead = true;
                            target.isLoser = true;
                            target.vel.x = proj.vel.x * 0.8;
                            const winner = entitiesRef.current.find(e => e.id === proj.ownerId);
                            if (winner) triggerWin(winner.id);
                        }
                    }
                }
            });
        }
    });
    projectilesRef.current = projectilesRef.current.filter(p => p.active);

    // === 3. 实体更新 ===
    entitiesRef.current.forEach(entity => {
      // 检查武器是否过期
      if (entity.heldWeapon) {
          entity.weaponDuration--;
          if (entity.weaponDuration <= 0) {
              entity.heldWeapon = null;
              spawnParticles(entity.pos.x, entity.pos.y - 40, '#888', 5, 5); // 消失特效
          }
      }

      if (gameState === GameState.VICTORY_ANIMATION && entity.isWinner) {
          entity.isAttacking = false; entity.attackFrame = 0; entity.isCrouching = false;
          const targetX = canvas.width / 2;
          const targetY = canvas.height / 3;
          entity.pos.x += (targetX - entity.pos.x) * 0.05;
          entity.pos.y += (targetY - entity.pos.y) * 0.05;
          entity.pos.y += Math.sin(frameRef.current * 0.08) * 0.8;
          entity.vel.x = 0; entity.vel.y = 0;
          if (frameRef.current % 3 === 0) spawnConfetti(canvas.width);
          return;
      }

      // 拾取武器
      if (!entity.isDead) {
          const canPickUp = !entity.heldWeapon || entity.ammo <= 0;

          if (canPickUp) {
            const itemIndex = fallingItemsRef.current.findIndex(item => {
                const dx = Math.abs(entity.pos.x - (item.pos.x + item.width/2));
                const dy = Math.abs((entity.pos.y - 35) - (item.pos.y + item.height/2));
                return dx < 50 && dy < 60;
            });

            if (itemIndex !== -1) {
                const item = fallingItemsRef.current[itemIndex];
                entity.heldWeapon = item.type;
                entity.weaponDuration = WEAPON_LIFETIME; 
                switch(item.type) {
                    case 'pistol': entity.ammo = 6; break;
                    case 'bomb': entity.ammo = 3; break;
                    case 'sword': entity.ammo = 8; break;
                    case 'atom_bomb': entity.ammo = 1; break; 
                    case 'missile': entity.ammo = 2; break; // 导弹只有2发
                    case 'dragon': entity.ammo = 1; break; 
                    case 'bomber': entity.ammo = 1; break; // 轰炸机召唤一次
                }
                fallingItemsRef.current.splice(itemIndex, 1);
                playJumpSound();
                spawnParticles(entity.pos.x, entity.pos.y - 30, '#fff', 5, 5);
            }
          }
      }

      // 物理引擎
      const prevY = entity.pos.y;
      entity.vel.y += GRAVITY;

      if (!entity.isLoser && entity.stunFrames > 0) {
           entity.stunFrames--; 
           entity.vel.x *= 0.95; 
      } else if (!entity.isLoser) {
          const currentFriction = entity.isCrouching && entity.isGrounded ? 0.4 : FRICTION;
          entity.vel.x *= currentFriction;
      } else {
          entity.vel.x *= 0.99; 
      }

      entity.pos.x += entity.vel.x;
      entity.pos.y += entity.vel.y;

      // 碰撞检测
      entity.isGrounded = false;
      if (entity.pos.y >= GROUND_Y) {
          if (!entity.isLoser) {
            entity.pos.y = GROUND_Y;
            entity.vel.y = 0;
            entity.isGrounded = true;
          }
      }
      if (entity.vel.y >= 0 && !entity.isDead) {
          PLATFORMS.forEach(plat => {
              if (entity.pos.x > plat.x - 10 && entity.pos.x < plat.x + plat.width + 10) {
                  if (prevY <= plat.y && entity.pos.y >= plat.y) {
                      entity.pos.y = plat.y;
                      entity.vel.y = 0;
                      entity.isGrounded = true;
                  }
              }
          });
      }

      if (!entity.isLoser) {
        if (entity.pos.x < 10) { entity.pos.x = 10; entity.vel.x *= -0.5; }
        if (entity.pos.x > canvas.width - 10) { entity.pos.x = canvas.width - 10; entity.vel.x *= -0.5; }
      }

      if (gameState === GameState.VICTORY_ANIMATION || entity.isDead || entity.stunFrames > 0) return;

      if (entity.attackCooldown > 0) entity.attackCooldown--;
      if (entity.isAttacking) {
          entity.attackFrame++;
          if (entity.attackFrame > 15) { 
              entity.isAttacking = false;
              entity.attackFrame = 0;
          }
      }

      let moveLeft = false, moveRight = false, jump = false, crouch = false, attack = false;

      // Input P1
      if (entity.playerIndex === 0) {
        if (keysRef.current.has('KeyA')) moveLeft = true;
        if (keysRef.current.has('KeyD')) moveRight = true;
        if (keysRef.current.has('KeyW')) jump = true;
        if (keysRef.current.has('KeyS')) crouch = true;
        if (keysRef.current.has('Space')) attack = true;
      }

      // Input P2 / AI
      if (entity.playerIndex === 1) {
          if (gameMode === 'PVP') {
            if (keysRef.current.has('ArrowLeft')) moveLeft = true;
            if (keysRef.current.has('ArrowRight')) moveRight = true;
            if (keysRef.current.has('ArrowUp')) jump = true;
            if (keysRef.current.has('ArrowDown')) crouch = true;
            if (keysRef.current.has('Enter')) attack = true;
          } else {
            // AI Logic
            const p1 = entitiesRef.current.find(e => e.playerIndex === 0);
            if (p1 && !p1.isDead) {
                let targetX = p1.pos.x;
                let targetY = p1.pos.y;

                if (!entity.heldWeapon && fallingItemsRef.current.length > 0) {
                    let minDist = 9999;
                    fallingItemsRef.current.forEach(item => {
                        const d = Math.abs(item.pos.x - entity.pos.x) + Math.abs(item.pos.y - entity.pos.y);
                        if (d < minDist) {
                            minDist = d;
                            targetX = item.pos.x;
                            targetY = item.pos.y;
                        }
                    });
                }

                const distX = targetX - entity.pos.x;
                const distY = targetY - entity.pos.y; 

                if (Math.abs(distX) > 40) {
                    distX > 0 ? moveRight = true : moveLeft = true;
                } else if (!entity.heldWeapon && Math.abs(distX) < 20) {
                     distX > 0 ? moveLeft = true : moveRight = true;
                }

                if (entity.isGrounded) {
                     if (distY < -100 || (Math.random() < 0.02)) {
                         jump = true;
                     }
                }

                const absDistX = Math.abs(p1.pos.x - entity.pos.x);
                entity.facingRight = (p1.pos.x - entity.pos.x) > 0;

                // AI 攻击逻辑
                let attackRange = ATTACK_RANGE;
                if (entity.heldWeapon === 'pistol') attackRange = 600;
                if (entity.heldWeapon === 'atom_bomb') attackRange = 300; 
                if (entity.heldWeapon === 'missile') attackRange = 700; 
                if (entity.heldWeapon === 'dragon') attackRange = 400; 
                if (entity.heldWeapon === 'bomber') attackRange = 800; // 只要有敌人就放

                if (absDistX < attackRange && Math.abs(p1.pos.y - entity.pos.y) < 100) {
                    if (entity.attackCooldown === 0 && Math.random() < 0.05) attack = true;
                }
            }
          }
      }

      entity.isCrouching = crouch && entity.isGrounded;
      if (!entity.isCrouching) {
          if (moveLeft) { entity.vel.x -= MOVE_SPEED; entity.facingRight = false; }
          if (moveRight) { entity.vel.x += MOVE_SPEED; entity.facingRight = true; }
      }
      if (jump && entity.isGrounded && !entity.isCrouching) {
          entity.vel.y = JUMP_FORCE;
          playJumpSound();
      }

      // === 攻击处理 ===
      if (attack && entity.attackCooldown === 0) {
          entity.attackCooldown = ATTACK_COOLDOWN;
          entity.isAttacking = true;
          entity.attackFrame = 5;

          if (entity.heldWeapon === 'pistol') {
              playShootSound();
              entity.vel.x += entity.facingRight ? -8 : 8;
              entity.vel.y -= 2;

              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'pistol',
                  pos: { x: entity.pos.x + (entity.facingRight ? 40 : -40), y: entity.pos.y - 45 },
                  vel: { x: entity.facingRight ? 20 : -20, y: (Math.random()-0.5) * 2 }, 
                  ownerId: entity.id,
                  width: 12, height: 4, active: true
              });
              entity.ammo--;
          } else if (entity.heldWeapon === 'bomb') {
              entity.vel.x += entity.facingRight ? -2 : 2;
              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'bomb',
                  pos: { x: entity.pos.x, y: entity.pos.y - 60 },
                  vel: { x: entity.facingRight ? 12 : -12, y: -12 },
                  ownerId: entity.id,
                  width: 20, height: 20, active: true
              });
              entity.ammo--;
          } else if (entity.heldWeapon === 'atom_bomb') {
              entity.vel.x += entity.facingRight ? -4 : 4;
              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'atom_bomb',
                  pos: { x: entity.pos.x, y: entity.pos.y - 70 },
                  vel: { x: entity.facingRight ? 8 : -8, y: -10 },
                  ownerId: entity.id,
                  width: 30, height: 40, active: true
              });
              entity.ammo--; 
          } else if (entity.heldWeapon === 'missile') {
              playShootSound(); 
              entity.vel.x += entity.facingRight ? -10 : 10; 
              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'missile',
                  pos: { x: entity.pos.x + (entity.facingRight ? 50 : -50), y: entity.pos.y - 50 },
                  vel: { x: entity.facingRight ? 10 : -10, y: -5 }, 
                  ownerId: entity.id,
                  width: 20, height: 8, active: true
              });
              entity.ammo--; 
          } else if (entity.heldWeapon === 'dragon') {
              playDragonRoar();
              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'dragon',
                  pos: { x: entity.pos.x, y: entity.pos.y - 100 },
                  vel: { x: 0, y: 0 },
                  ownerId: entity.id,
                  width: 40, height: 40, active: true,
                  dragonState: 'enter', 
                  remainingHits: 5,
                  dragonPathProgress: 0,
                  dragonSegments: undefined
              });
              entity.ammo--;
          } else if (entity.heldWeapon === 'bomber') {
              // 呼叫轰炸机
              const startX = entity.facingRight ? -100 : canvas.width + 100;
              playShootSound(); // 使用枪声模拟无线电
              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'bomber',
                  pos: { x: startX, y: 100 }, // 高空飞行
                  vel: { x: 0, y: 0 },
                  ownerId: entity.id,
                  width: 60, height: 20, active: true,
                  bomberState: 'fly_in',
                  bombDropCount: 0
              });
              entity.ammo--;
          } else {
              // == 近战武器 ==
              playAttackSound();

              let range = ATTACK_RANGE;
              let dmg = ATTACK_DAMAGE;
              let knockbackX = 15;
              let knockbackY = -8;
              let selfPush = 10;
              let hitEffectSize = 12;

              if (entity.heldWeapon === 'sword') {
                  range = 140; dmg = 15; knockbackX = 12; selfPush = 12; entity.attackCooldown = 20; 
              }

              entity.vel.x = entity.facingRight ? selfPush : -selfPush;

              const hitX = entity.facingRight ? entity.pos.x + range/2 : entity.pos.x - range/2;
              const hitY = entity.isCrouching ? entity.pos.y - 20 : entity.pos.y - 45;

              let hitSomething = false;

              entitiesRef.current.forEach(target => {
                  if (target !== entity && !target.isDead) {
                      const dy = (target.pos.y - 35) - hitY;
                      if (Math.abs(target.pos.x - entity.pos.x) < range && Math.abs(dy) < 60 && 
                          ((entity.facingRight && target.pos.x > entity.pos.x) || (!entity.facingRight && target.pos.x < entity.pos.x))) {

                          if (!entity.isCrouching && target.isCrouching) {
                              spawnParticles(target.pos.x, target.pos.y - 40, '#aaa', 2, 2);
                              return; 
                          }

                          target.health -= dmg;
                          hitSomething = true;

                          target.vel.x = entity.facingRight ? knockbackX : -knockbackX; 
                          target.vel.y = knockbackY; 
                          target.stunFrames = 20; 

                          shakeRef.current = Math.floor(dmg / 2);
                          spawnParticles(target.pos.x, target.pos.y - 40, target.color, hitEffectSize, 10);
                          playHitSound();

                          if (target.health <= 0) {
                              target.health = 0;
                              target.isDead = true;
                              target.isLoser = true;
                              target.vel.x = entity.facingRight ? 30 : -30;
                              target.vel.y = -20;
                              triggerWin(entity.id);
                          }
                      }
                  }
              });

              if (hitSomething && entity.heldWeapon) {
                  entity.ammo--;
              }
          }

          // 弹药耗尽检查
          if (entity.heldWeapon && entity.ammo <= 0) {
              entity.heldWeapon = null;
              spawnParticles(entity.pos.x, entity.pos.y - 40, '#888', 5, 5); 
          }
      }
    });
  };

  const draw = () => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      const shake = shakeRef.current;
      const shakeX = shake > 0 ? (Math.random() - 0.5) * shake : 0;
      const shakeY = shake > 0 ? (Math.random() - 0.5) * shake : 0;

      ctx.save();

      // Clear & Background
      ctx.fillStyle = '#0f172a';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.translate(shakeX, shakeY);

      // Draw Platforms
      ctx.fillStyle = '#334155';
      PLATFORMS.forEach(p => {
          ctx.fillRect(p.x, p.y, p.width, p.height);
          ctx.fillStyle = '#475569';
          ctx.fillRect(p.x, p.y, p.width, 5);
          ctx.fillStyle = '#334155';
      });
      // Draw Ground
      ctx.fillStyle = '#1e293b';
      ctx.fillRect(0, GROUND_Y, canvas.width, canvas.height - GROUND_Y);

      // Draw Falling Items
      fallingItemsRef.current.forEach(item => {
        if (!item.onGround) {
             ctx.fillStyle = 'rgba(0,0,0,0.3)';
             ctx.beginPath(); ctx.ellipse(item.pos.x + item.width/2, GROUND_Y, 15, 5, 0, 0, Math.PI*2); ctx.fill();
        }

        ctx.save();
        ctx.translate(item.pos.x + item.width/2, item.pos.y + item.height/2);

        if (item.type === 'pistol') {
            ctx.fillStyle = '#94a3b8'; ctx.fillRect(-10, -5, 20, 10); ctx.fillStyle='#000'; ctx.fillRect(0,0,5,5);
        } else if (item.type === 'bomb') {
            ctx.fillStyle = '#000'; ctx.beginPath(); ctx.arc(0,0,10,0,Math.PI*2); ctx.fill();
            ctx.strokeStyle='#fff'; ctx.beginPath(); ctx.moveTo(0,-10); ctx.lineTo(5,-15); ctx.stroke();
        } else if (item.type === 'sword') {
             ctx.fillStyle = '#cbd5e1'; ctx.beginPath(); ctx.moveTo(-2, 10); ctx.lineTo(-2, -15); ctx.lineTo(0,-20); ctx.lineTo(2,-15); ctx.lineTo(2,10); ctx.fill();
             ctx.fillStyle = '#8B4513'; ctx.fillRect(-5, 10, 10, 3);
        } else if (item.type === 'atom_bomb') {
             ctx.fillStyle = '#1e1e1e'; ctx.beginPath(); ctx.arc(0,0,12,0,Math.PI*2); ctx.fill();
             ctx.fillStyle = '#eab308'; ctx.font='12px sans-serif'; ctx.fillText('☢', -5, 4);
        } else if (item.type === 'missile') {
             ctx.fillStyle = '#15803d'; ctx.fillRect(-12, -4, 24, 8);
             ctx.fillStyle = '#dc2626'; ctx.fillRect(12, -4, 4, 8);
        } else if (item.type === 'dragon') {
             ctx.font='24px serif'; ctx.fillText('🐉', -12, 8);
        } else if (item.type === 'bomber') {
             ctx.fillStyle = '#4b5563'; ctx.fillRect(-10, -10, 20, 14); 
             ctx.fillStyle = '#ef4444'; ctx.beginPath(); ctx.arc(5,-5,3,0,Math.PI*2); ctx.fill(); 
             ctx.fillRect(5, -18, 2, 8); 
        }
        ctx.restore();
      });

      // Draw Projectiles
      projectilesRef.current.forEach(proj => {
           if (proj.type === 'dragon' && proj.dragonSegments) {
                ctx.strokeStyle = '#fbbf24'; 
                ctx.lineWidth = 20;
                ctx.lineCap = 'round';
                ctx.lineJoin = 'round';
                ctx.beginPath();
                if (proj.dragonSegments.length > 0) {
                     ctx.moveTo(proj.dragonSegments[0].x, proj.dragonSegments[0].y);
                     for(let i=1; i<proj.dragonSegments.length; i++) {
                         ctx.lineTo(proj.dragonSegments[i].x, proj.dragonSegments[i].y);
                     }
                }
                ctx.stroke();
                ctx.fillStyle = '#ef4444'; 
                ctx.beginPath(); ctx.arc(proj.pos.x, proj.pos.y - 10, 5, 0, Math.PI*2); ctx.fill();
                return;
           }

           ctx.save();
           ctx.translate(proj.pos.x, proj.pos.y);

           if (proj.type === 'pistol') { 
               ctx.fillStyle = '#facc15'; ctx.fillRect(-2, -2, 8, 4);
           } else if (proj.type === 'bomb') {
               ctx.fillStyle = '#000'; ctx.beginPath(); ctx.arc(0,0,8,0,Math.PI*2); ctx.fill();
           } else if (proj.type === 'atom_bomb') {
               ctx.fillStyle = '#333'; ctx.beginPath(); ctx.arc(0,0,12,0,Math.PI*2); ctx.fill();
               ctx.fillStyle = 'yellow'; ctx.fillText('☢', -4, 4);
           } else if (proj.type === 'missile') {
               const angle = Math.atan2(proj.vel.y, proj.vel.x);
               ctx.rotate(angle);
               ctx.fillStyle = '#166534'; ctx.fillRect(-10, -4, 20, 8);
               ctx.fillStyle = '#ef4444'; ctx.fillRect(10, -4, 4, 8);
           } else if (proj.type === 'bomber') {
               ctx.fillStyle = '#1f2937'; 
               ctx.beginPath(); ctx.moveTo(20,0); ctx.lineTo(-10, -15); ctx.lineTo(-10, 15); ctx.fill();
               ctx.fillStyle = '#374151';
               ctx.fillRect(-5, -30, 10, 60);
           }

           ctx.restore();
      });

      // Draw Particles
      particlesRef.current.forEach(p => {
          ctx.fillStyle = p.color;
          const alpha = p.currentAlpha !== undefined ? p.currentAlpha : (p.life / p.maxLife);
          ctx.globalAlpha = Math.max(0, alpha);
          ctx.beginPath(); ctx.arc(p.pos.x, p.pos.y, p.size, 0, Math.PI * 2); ctx.fill();
          ctx.globalAlpha = 1.0;
      });

      // Draw Entities
      entitiesRef.current.forEach(entity => drawEntity(ctx, entity));

      // Flash
      if (flashRef.current > 0) {
          ctx.fillStyle = `rgba(255, 255, 255, ${flashRef.current})`;
          ctx.fillRect(-shakeX, -shakeY, canvas.width, canvas.height); 
      }

      ctx.restore();
  };

  const tick = () => {
    update();
    draw();
    requestRef.current = requestAnimationFrame(tick);
  };

  useEffect(() => {
    if (canvasRef.current) {
        canvasRef.current.width = window.innerWidth;
        canvasRef.current.height = window.innerHeight;
    }
    requestRef.current = requestAnimationFrame(tick);
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [gameState]);

  return (
    <canvas 
        ref={canvasRef} 
        className="block w-full h-full bg-slate-900"
    />
  );
};

export default GameCanvas;

export enum GameState {
  MENU,
  PLAYING,
  GAME_OVER,
  VICTORY_ANIMATION
}

export type GameMode = 'PVE' | 'PVP';

export interface Vector {
  x: number;
  y: number;
}

// 移除了 stick, blade, pistol，新增 bomber, pokemon
export type WeaponType = 'bomb' | 'sword' | 'atom_bomb' | 'missile' | 'dragon' | 'bomber' | 'pokemon';

export interface Platform {
  x: number;
  y: number;
  width: number;
  height: number;
}

export interface Entity {
  id: string;
  pos: Vector;
  vel: Vector;
  width: number;
  height: number;
  color: string;
  isGrounded: boolean;
  isCrouching: boolean;
  health: number;
  maxHealth: number;
  isDead: boolean;
  facingRight: boolean;
  attackCooldown: number;
  isAttacking: boolean;
  attackFrame: number;
  type: 'player'; 
  playerIndex: number; 
  isWinner?: boolean;
  isLoser?: boolean;
  heldWeapon?: WeaponType | null;
  ammo: number; // 弹药量 或 近战武器耐久度
  weaponDuration: number; // 新增：武器剩余存在时间 (帧)
  stunFrames: number; // 受击硬直/击飞状态
}

export interface FallingItem {
  id: string;
  type: WeaponType;
  pos: Vector;
  vel: Vector;
  width: number;
  height: number;
  onGround: boolean;
}

export interface Projectile {
  id: string;
  type: WeaponType;
  pos: Vector;
  vel: Vector;
  ownerId: string;
  width: number;
  height: number;
  active: boolean;
  targetId?: string; // 追踪目标ID

  // 神龙特有属性
  dragonState?: 'enter' | 'hunt';
  dragonPathProgress?: number; // 入场动画进度
  dragonSegments?: Vector[]; // 龙身位置数组
  remainingHits?: number; // 剩余攻击次数
  lastHitFrame?: number; // 上次攻击时间

  // 轰炸机特有属性
  bomberState?: 'fly_in' | 'bombing' | 'fly_out';
  bombDropCount?: number;

  // 宝可梦特有属性
  pokemonState?: 'seeking' | 'attacking';
  attackTimer?: number;
}

export interface Particle {
  id: string;
  pos: Vector;
  vel: Vector;
  life: number;
  maxLife: number;
  color: string;
  size: number;
  gravity?: number; 

  // 新增属性用于高级特效 (蘑菇云等)
  growth?: number; // 尺寸增长速率
  alphaDecay?: number; // 透明度衰减速率 (默认是 life/maxLife，此项可覆盖)
  currentAlpha?: number;
}

export interface GameStats {
  winner: string | null;
  mode: GameMode;
  duration: number;
}

import React, { useRef, useEffect, useCallback } from 'react';
import { GameState, Entity, Vector, Particle, GameStats, GameMode, FallingItem, Projectile, WeaponType, Platform } from '../types';
import { playJumpSound, playAttackSound, playHitSound, playShootSound, playExplodeSound, playDragonRoar } from '../services/audioService';

interface GameCanvasProps {
  gameState: GameState;
  setGameState: (state: GameState) => void;
  setStats: React.Dispatch<React.SetStateAction<GameStats>>;
  setPlayers: (players: Entity[]) => void;
  gameMode: GameMode;
}

// === 物理参数 (提速版) ===
const GRAVITY = 0.8; 
const FRICTION = 0.82; 
const MOVE_SPEED = 2; 
const JUMP_FORCE = -22; 
const GROUND_Y = 600;
const ATTACK_COOLDOWN = 18; 
const ATTACK_RANGE = 100;
const ATTACK_DAMAGE = 8;

// === 武器生成配置 ===
const MAX_WEAPONS_PER_GAME = 6; 
const WEAPON_SPAWN_INTERVAL = 900; 
const WEAPON_LIFETIME = 15 * 60; 

// === 关卡设计 ===
const PLATFORMS: Platform[] = [
    { x: 300, y: 450, width: 200, height: 20 },
    { x: 800, y: 450, width: 200, height: 20 },
    { x: 500, y: 250, width: 300, height: 20 } 
];

const drawEntity = (ctx: CanvasRenderingContext2D, entity: Entity) => {
    ctx.save();

    const centerX = entity.pos.x;
    const centerY = entity.pos.y; // Feet position

    ctx.translate(centerX, centerY);

    if (entity.isDead) {
         ctx.rotate(Math.PI / 2 * (entity.facingRight ? 1 : -1));
         ctx.translate(0, -10);
    }

    if (!entity.facingRight) ctx.scale(-1, 1);

    // Draw body
    ctx.fillStyle = entity.color;
    ctx.strokeStyle = entity.color;
    ctx.lineWidth = 4;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    const crouchOffset = entity.isCrouching ? 20 : 0;

    // Head
    ctx.beginPath();
    ctx.arc(0, -entity.height + 20 + crouchOffset, 12, 0, Math.PI * 2);
    ctx.fill();

    // Body
    ctx.beginPath();
    ctx.moveTo(0, -entity.height + 32 + crouchOffset);
    ctx.lineTo(0, -25 + crouchOffset);
    ctx.stroke();

    // Legs
    ctx.beginPath();
    ctx.moveTo(0, -25 + crouchOffset);
    if (entity.isCrouching) {
        ctx.lineTo(-15, -5);
        ctx.moveTo(0, -25 + crouchOffset);
        ctx.lineTo(15, -5);
    } else if (Math.abs(entity.vel.x) > 0.1 && entity.isGrounded) {
        const walkCycle = Math.sin(Date.now() / 100) * 10;
        ctx.lineTo(-10 + walkCycle, 0);
        ctx.moveTo(0, -25 + crouchOffset);
        ctx.lineTo(10 - walkCycle, 0);
    } else {
        ctx.lineTo(-10, 0);
        ctx.moveTo(0, -25 + crouchOffset);
        ctx.lineTo(10, 0);
    }
    ctx.stroke();

    // Arms
    ctx.beginPath();
    const shoulderY = -entity.height + 40 + crouchOffset;
    ctx.moveTo(0, shoulderY);

    if (entity.isWinner) {
        ctx.lineTo(-20, shoulderY - 30);
        ctx.moveTo(0, shoulderY);
        ctx.lineTo(20, shoulderY - 30);
    } else if (entity.isAttacking) {
        const attackProgress = entity.attackFrame / 15;
        ctx.lineTo(25, shoulderY - 10 + attackProgress * 20);
    } else if (entity.heldWeapon) {
        ctx.lineTo(15, shoulderY + 5);

        ctx.save();
        ctx.translate(15, shoulderY + 5);

        if (entity.heldWeapon === 'sword') {
            ctx.fillStyle = '#ccc';
            ctx.fillRect(0, -25, 4, 30);
            ctx.fillStyle = '#8B4513';
            ctx.fillRect(-3, 0, 10, 2);
        } else if (entity.heldWeapon === 'bomb' || entity.heldWeapon === 'atom_bomb') {
            ctx.fillStyle = '#000';
            ctx.beginPath();
            ctx.arc(5, 0, 8, 0, Math.PI*2);
            ctx.fill();
            ctx.strokeStyle = '#fff';
            ctx.beginPath();
            ctx.moveTo(5, -8);
            ctx.quadraticCurveTo(10, -15, 15, -10);
            ctx.stroke();
             if (entity.heldWeapon === 'atom_bomb') {
                ctx.fillStyle = 'yellow';
                ctx.font = '10px Arial';
                ctx.fillText('☢', 2, 4);
            }
        } else if (entity.heldWeapon === 'missile') {
             ctx.fillStyle = 'green';
             ctx.fillRect(0, -5, 20, 10);
             ctx.fillStyle = 'red';
             ctx.fillRect(20, -5, 5, 10);
        } else if (entity.heldWeapon === 'dragon') {
             ctx.font = '20px serif';
             ctx.fillText('🐉', 0, 5);
        } else if (entity.heldWeapon === 'bomber') {
             // 无线电/对讲机外观
             ctx.fillStyle = '#333';
             ctx.fillRect(0, -10, 10, 16);
             ctx.fillStyle = '#000';
             ctx.fillRect(2, -15, 2, 5); // 天线
             ctx.fillStyle = '#f00';
             ctx.beginPath(); ctx.arc(5, -5, 2, 0, Math.PI*2); ctx.fill(); // 信号灯
        } else if (entity.heldWeapon === 'pokemon') {
            // 精灵球
            ctx.fillStyle = 'red'; ctx.beginPath(); ctx.arc(0,0,6, Math.PI, 0); ctx.fill();
            ctx.fillStyle = 'white'; ctx.beginPath(); ctx.arc(0,0,6, 0, Math.PI); ctx.fill();
            ctx.fillStyle = 'black'; ctx.fillRect(-6, -1, 12, 2);
            ctx.fillStyle = 'white'; ctx.beginPath(); ctx.arc(0,0,2, 0, Math.PI*2); ctx.fill();
            ctx.strokeStyle = 'black'; ctx.lineWidth = 1; ctx.beginPath(); ctx.arc(0,0,2, 0, Math.PI*2); ctx.stroke();
        }
        ctx.restore();

    } else {
        if (Math.abs(entity.vel.x) > 0.1) {
             const armCycle = Math.cos(Date.now() / 100) * 10;
             ctx.lineTo(armCycle, shoulderY + 15);
        } else {
             ctx.lineTo(0, shoulderY + 20);
        }
    }
    ctx.stroke();

    ctx.restore();
};

const GameCanvas: React.FC<GameCanvasProps> = ({ gameState, setGameState, setStats, setPlayers, gameMode }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();
  const frameRef = useRef<number>(0);

  const entitiesRef = useRef<Entity[]>([]);
  const particlesRef = useRef<Particle[]>([]);
  const fallingItemsRef = useRef<FallingItem[]>([]);
  const projectilesRef = useRef<Projectile[]>([]);

  // 武器生成控制
  const spawnedWeaponCountRef = useRef<number>(0); 
  const atomBombIndexRef = useRef<number>(-1); 
  const missileIndexRef = useRef<number>(-1); 
  const dragonIndexRef = useRef<number>(-1); 

  const keysRef = useRef<Set<string>>(new Set());
  const statsRef = useRef<GameStats>({ winner: null, mode: gameMode, duration: 0 });
  const shakeRef = useRef<number>(0);
  const flashRef = useRef<number>(0); 

  // 初始化对决
  const initGame = useCallback(() => {
    const newEntities: Entity[] = [];

    // P1 (左侧)
    newEntities.push({
      id: 'p1', type: 'player', playerIndex: 0,
      pos: { x: 100, y: 100 }, vel: { x: 0, y: 0 }, 
      width: 40, height: 70, color: '#3b82f6', 
      isGrounded: false, isCrouching: false, health: 100, maxHealth: 100, isDead: false,
      facingRight: true, attackCooldown: 0, isAttacking: false, attackFrame: 0,
      heldWeapon: null, ammo: 0, weaponDuration: 0, stunFrames: 0
    });

    // P2/CPU (右侧)
    newEntities.push({
      id: 'p2', type: 'player', playerIndex: 1,
      pos: { x: window.innerWidth - 100, y: 100 }, vel: { x: 0, y: 0 },
      width: 40, height: 70, color: '#facc15',
      isGrounded: false, isCrouching: false, health: 100, maxHealth: 100, isDead: false,
      facingRight: false, attackCooldown: 0, isAttacking: false, attackFrame: 0,
      heldWeapon: null, ammo: 0, weaponDuration: 0, stunFrames: 0
    });

    entitiesRef.current = newEntities;
    particlesRef.current = [];
    fallingItemsRef.current = [];
    projectilesRef.current = [];
    spawnedWeaponCountRef.current = 0; 

    const indices = Array.from({length: MAX_WEAPONS_PER_GAME}, (_, i) => i);
    for (let i = indices.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [indices[i], indices[j]] = [indices[j], indices[i]];
    }

    atomBombIndexRef.current = indices[0];
    missileIndexRef.current = indices[1];
    dragonIndexRef.current = indices[2]; 

    statsRef.current = { winner: null, mode: gameMode, duration: 0 };
    frameRef.current = 0;
    shakeRef.current = 0;
    flashRef.current = 0;

    setStats(statsRef.current);
    setPlayers([...entitiesRef.current]);
  }, [gameMode, setStats, setPlayers]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        if (e.repeat) return;
        keysRef.current.add(e.code);
        if (e.code === 'KeyR' && gameState === GameState.GAME_OVER) {
             setGameState(GameState.PLAYING);
        }
    };
    const handleKeyUp = (e: KeyboardEvent) => keysRef.current.delete(e.code);
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, [gameState, setGameState]);

  useEffect(() => {
    if (gameState === GameState.PLAYING) {
      initGame();
    }
  }, [gameState, initGame]);

  const spawnParticles = (x: number, y: number, color: string, count: number, speed = 8, lifeMultiplier = 1) => {
      for(let i=0; i<count; i++) {
          particlesRef.current.push({
              id: Math.random().toString(),
              pos: {x, y},
              vel: { x: (Math.random() - 0.5) * speed, y: (Math.random() - 0.5) * speed },
              life: (20 + Math.random() * 20) * lifeMultiplier,
              maxLife: 40 * lifeMultiplier,
              color: color,
              size: Math.random() * 6 + 3,
              gravity: 0.5 
          });
      }
  };

  const spawnMushroomCloud = (x: number, y: number) => {
    // 1. 蘑菇柄 (上升的烟柱)
    for (let i = 0; i < 20; i++) {
      particlesRef.current.push({
        id: Math.random().toString(),
        pos: { x: x + (Math.random()-0.5)*20, y: y },
        vel: { x: (Math.random()-0.5) * 1, y: -2 - Math.random() * 3 },
        life: 180,
        maxLife: 180,
        color: i % 2 === 0 ? '#555' : '#333',
        size: 15 + Math.random() * 10,
        gravity: -0.05, // 轻微上升
        growth: 0.3, // 膨胀
        alphaDecay: 0.005,
        currentAlpha: 0.8
      });
    }

    // 2. 蘑菇盖 (顶部扩散)
    for (let i = 0; i < 40; i++) {
      const angle = (Math.PI / 40) * i * 2; // 360度
      const speed = 2 + Math.random() * 3;
      particlesRef.current.push({
        id: Math.random().toString(),
        pos: { x: x, y: y - 80 },
        vel: { x: Math.cos(angle) * speed, y: Math.sin(angle) * speed * 0.5 - 1 },
        life: 200,
        maxLife: 200,
        color: Math.random() > 0.5 ? '#ff4500' : '#ff8800', // 橙红火光
        size: 20 + Math.random() * 10,
        gravity: -0.02,
        growth: 0.5, // 快速膨胀
        alphaDecay: 0.008,
        currentAlpha: 0.9
      });
    }

    // 3. 底部冲击波 (贴地尘土)
    for (let i = 0; i < 30; i++) {
        const dir = i % 2 === 0 ? 1 : -1;
        particlesRef.current.push({
            id: Math.random().toString(),
            pos: { x: x, y: y },
            vel: { x: dir * (5 + Math.random()*10), y: -1 },
            life: 100, maxLife: 100,
            color: '#777',
            size: 10,
            gravity: 0,
            growth: 0.8,
            alphaDecay: 0.02,
            currentAlpha: 0.6
        });
    }
  };

  const spawnConfetti = (width: number) => {
      const colors = ['#FFD700', '#FF6347', '#00BFFF', '#32CD32', '#FF69B4', '#FFFFFF'];
      const x = Math.random() * width;
      const y = -10; 
      const color = colors[Math.floor(Math.random() * colors.length)];
      particlesRef.current.push({
          id: Math.random().toString(),
          pos: { x, y },
          vel: { x: (Math.random() - 0.5) * 2, y: Math.random() * 2 + 1 },
          life: 200, maxLife: 200, color, size: Math.random() * 4 + 3, gravity: 0.02 
      });
  };

  const spawnFallingItem = (canvasWidth: number) => {
      let type: WeaponType;

      const count = spawnedWeaponCountRef.current;

      if (count === atomBombIndexRef.current) {
          type = 'atom_bomb';
      } else if (count === missileIndexRef.current) {
          type = 'missile';
      } else if (count === dragonIndexRef.current) {
          type = 'dragon';
      } else {
          // 移除 pistol, 加入 pokemon, bomber
          const normalPool: WeaponType[] = ['bomb', 'sword', 'bomber', 'pokemon'];
          type = normalPool[Math.floor(Math.random() * normalPool.length)];
      }

      fallingItemsRef.current.push({
          id: Math.random().toString() + "_" + Date.now(),
          type,
          pos: { x: 100 + Math.random() * (canvasWidth - 200), y: -50 },
          vel: { x: (Math.random() - 0.5) * 2, y: 2 },
          width: 30, height: 30,
          onGround: false
      });
      spawnedWeaponCountRef.current++;
  };

  const update = () => {
    if (gameState !== GameState.PLAYING && gameState !== GameState.VICTORY_ANIMATION) return;
    const canvas = canvasRef.current;
    if (!canvas) return;

    frameRef.current++;
    if (shakeRef.current > 0) shakeRef.current--;
    if (flashRef.current > 0) flashRef.current -= 0.02; 
    if (gameState === GameState.PLAYING) statsRef.current.duration += 1/60;

    const triggerWin = (winnerId: string) => {
        if (statsRef.current.winner) return;
        const winner = entitiesRef.current.find(e => e.id === winnerId);
        if (winner) winner.isWinner = true;
        statsRef.current.winner = winnerId === 'p1' ? 'P1' : 'P2';
        setGameState(GameState.VICTORY_ANIMATION);
        setTimeout(() => setGameState(GameState.GAME_OVER), 4000);
    };

    // === 0. 掉落物生成 ===
    if (gameState === GameState.PLAYING && 
        spawnedWeaponCountRef.current < MAX_WEAPONS_PER_GAME && 
        frameRef.current > 60 && 
        frameRef.current % WEAPON_SPAWN_INTERVAL === 0) {
        spawnFallingItem(canvas.width);
    }

    // === 1. 掉落物逻辑 ===
    fallingItemsRef.current.forEach(item => {
        item.vel.y += 0.2; 
        if (item.vel.y > 8) item.vel.y = 8;

        const prevY = item.pos.y;
        item.pos.x += item.vel.x;
        item.pos.y += item.vel.y;

        if (item.pos.y >= GROUND_Y - item.height) {
            item.pos.y = GROUND_Y - item.height;
            item.onGround = true;
            item.vel.y = -item.vel.y * 0.5;
            item.vel.x *= 0.8;
        }

        if (item.vel.y > 0) {
            PLATFORMS.forEach(plat => {
                if (item.pos.x + item.width > plat.x && item.pos.x < plat.x + plat.width) {
                    if (prevY + item.height <= plat.y && item.pos.y + item.height >= plat.y) {
                        item.pos.y = plat.y - item.height;
                        item.onGround = true;
                        item.vel.y = -item.vel.y * 0.5;
                        item.vel.x *= 0.8;
                    }
                }
            });
        }
    });

    // === 2. 投射物逻辑 (炸弹、导弹、神龙、轰炸机、宝可梦) ===
    projectilesRef.current.forEach(proj => {
        if (!proj.active) return;

        // --- 宝可梦逻辑 (Pikachu) ---
        if (proj.type === 'pokemon') {
            const target = entitiesRef.current.find(e => e.id !== proj.ownerId && !e.isDead);

            if (proj.pokemonState === 'seeking') {
                if (target) {
                    const dx = target.pos.x - proj.pos.x;
                    const dy = (target.pos.y - 40) - proj.pos.y;
                    const dist = Math.sqrt(dx*dx + dy*dy);

                    // 飞向敌人
                    proj.vel.x = (proj.vel.x * 20 + (dx / dist) * 12) / 21;
                    proj.vel.y = (proj.vel.y * 20 + (dy / dist) * 12) / 21;

                    // 靠近后攻击
                    if (dist < 150) {
                        proj.pokemonState = 'attacking';
                        proj.attackTimer = 0;
                        proj.vel = { x: 0, y: 0 }; // 悬停攻击
                    }
                } else {
                    // 没目标就乱跑
                    proj.vel.x *= 0.9;
                    proj.vel.y *= 0.9;
                }

                proj.pos.x += proj.vel.x;
                proj.pos.y += proj.vel.y;
            } else if (proj.pokemonState === 'attacking') {
                if (proj.attackTimer === undefined) proj.attackTimer = 0;
                proj.attackTimer++;

                // 播放音效
                if (proj.attackTimer % 5 === 0) playDragonRoar(); // 借用龙吼的电流声
                shakeRef.current = 5;

                // 造成一次伤害
                if (proj.attackTimer === 20) {
                     if (target && !target.isDead) {
                         target.health -= 20;
                         target.stunFrames = 40; // 麻痹效果
                         playExplodeSound();
                         shakeRef.current = 10;
                         spawnParticles(target.pos.x, target.pos.y - 30, '#ffff00', 30, 10);

                         if (target.health <= 0) {
                            target.health = 0;
                            target.isDead = true;
                            target.isLoser = true;
                            triggerWin(proj.ownerId);
                         }
                     }
                }

                // 攻击结束
                if (proj.attackTimer > 40) {
                    proj.active = false;
                    spawnParticles(proj.pos.x, proj.pos.y, '#fff', 10, 5); // 消失
                }
            }
            return;
        }

        // --- 轰炸机逻辑 ---
        if (proj.type === 'bomber') {
            const target = entitiesRef.current.find(e => e.id !== proj.ownerId && !e.isDead);
            const targetX = target ? target.pos.x : canvas.width / 2;
            const flyHeight = 150;

            // 确保Y轴高度
            proj.pos.y += (flyHeight - proj.pos.y) * 0.1;

            if (proj.bomberState === 'fly_in') {
                // 飞向目标X
                const dx = targetX - proj.pos.x;
                const dir = dx > 0 ? 1 : -1;

                // 快速接近
                proj.vel.x = dir * 10; 

                // 到达目标附近，开始投弹
                if (Math.abs(dx) < 60) {
                    proj.bomberState = 'bombing';
                    proj.bombDropCount = 0;
                    proj.lastHitFrame = frameRef.current;
                }
            } else if (proj.bomberState === 'bombing') {
                // 减速投弹
                proj.vel.x = proj.vel.x > 0 ? 5 : -5;

                const interval = 12; // 投弹间隔帧数
                if (frameRef.current - (proj.lastHitFrame || 0) > interval) {
                    proj.lastHitFrame = frameRef.current;
                    // 投掷炸弹
                    projectilesRef.current.push({
                        id: Math.random().toString(),
                        type: 'bomb',
                        pos: { x: proj.pos.x, y: proj.pos.y + 20 },
                        vel: { x: proj.vel.x * 0.5, y: 5 }, // 继承一点惯性
                        ownerId: proj.ownerId,
                        width: 20, height: 20, active: true
                    });
                    if (proj.bombDropCount !== undefined) proj.bombDropCount++;

                    if (proj.bombDropCount && proj.bombDropCount >= 3) {
                         proj.bomberState = 'fly_out';
                    }
                }
            } else if (proj.bomberState === 'fly_out') {
                // 加速飞离
                proj.vel.x = proj.vel.x > 0 ? 15 : -15;
                if (proj.pos.x < -200 || proj.pos.x > canvas.width + 200) {
                    proj.active = false;
                }
            }

            proj.pos.x += proj.vel.x;
            return;
        }

        // --- 神龙逻辑 (优化动作) ---
        if (proj.type === 'dragon') {
            const dragonSegmentsCount = 20; // 增加段数，更流畅
            if (!proj.dragonSegments || proj.dragonSegments.length === 0) {
                proj.dragonSegments = Array.from({ length: dragonSegmentsCount }, () => ({ ...proj.pos }));
            }

            if (proj.dragonState === 'enter') {
                if (!proj.dragonPathProgress) proj.dragonPathProgress = 0;
                proj.dragonPathProgress += 0.02;

                shakeRef.current = 8;
                if (Math.random() < 0.1) playExplodeSound();

                const w = canvas.width;
                const h = canvas.height;
                const t = proj.dragonPathProgress * Math.PI * 2;

                // 更复杂的入场轨迹
                const targetX = w/2 + (w/2 - 50) * Math.cos(t) * Math.sin(t*0.5);
                const targetY = h/3 + (h/4) * Math.sin(2*t);

                proj.vel.x = (targetX - proj.pos.x) * 0.2;
                proj.vel.y = (targetY - proj.pos.y) * 0.2;
                proj.pos.x += proj.vel.x;
                proj.pos.y += proj.vel.y;

                if (proj.dragonPathProgress >= 1.5) {
                    proj.dragonState = 'hunt';
                    shakeRef.current = 0;
                }
            } else if (proj.dragonState === 'hunt') {
                const target = entitiesRef.current.find(e => e.id !== proj.ownerId && !e.isDead);
                if (target) {
                    const dx = target.pos.x - proj.pos.x;
                    const dy = (target.pos.y - 40) - proj.pos.y;
                    const dist = Math.sqrt(dx*dx + dy*dy);

                    const speed = 7; // 略微提速
                    // 增加一点惯性，避免转弯太生硬
                    proj.vel.x = (proj.vel.x * 20 + (dx / dist) * speed) / 21;
                    proj.vel.y = (proj.vel.y * 20 + (dy / dist) * speed) / 21;

                    proj.pos.x += proj.vel.x;
                    proj.pos.y += proj.vel.y;

                    if (dist < 50) {
                        const now = frameRef.current;
                        if (!proj.lastHitFrame || now - proj.lastHitFrame > 30) {
                            proj.lastHitFrame = now;
                            if (proj.remainingHits && proj.remainingHits > 0) {
                                proj.remainingHits--;

                                target.health -= 5;
                                target.stunFrames = 20;
                                target.vel.x = (Math.random()-0.5) * 30;
                                target.vel.y = -15;

                                playHitSound();
                                spawnParticles(target.pos.x, target.pos.y, '#FFD700', 20, 8);
                                shakeRef.current = 15;

                                if (target.health <= 0) {
                                    target.health = 0;
                                    target.isDead = true;
                                    target.isLoser = true;
                                    triggerWin(proj.ownerId);
                                }

                                if (proj.remainingHits <= 0) {
                                    proj.active = false;
                                    // 神龙离去特效
                                    spawnParticles(proj.pos.x, proj.pos.y, '#FFD700', 80, 15);
                                }
                            }
                        }
                    }
                } else {
                    proj.vel.y -= 0.5;
                    proj.pos.x += Math.sin(frameRef.current * 0.1) * 5;
                    proj.pos.y += proj.vel.y;
                    if (proj.pos.y < -300) proj.active = false;
                }
            }

            if (proj.dragonSegments && proj.dragonSegments.length > 0) {
                proj.dragonSegments[0] = { ...proj.pos };
                for (let i = 1; i < proj.dragonSegments.length; i++) {
                    const current = proj.dragonSegments[i];
                    const prev = proj.dragonSegments[i-1];
                    const dx = prev.x - current.x;
                    const dy = prev.y - current.y;
                    const d = Math.sqrt(dx*dx + dy*dy);
                    const spacing = 18; 

                    if (d > spacing) {
                        const ratio = (d - spacing) / d;
                        current.x += dx * ratio;
                        current.y += dy * ratio;
                    }
                }
            }
            return; 
        }

        // --- 巡航导弹逻辑 (东风) ---
        if (proj.type === 'missile') {
            if (frameRef.current % 2 === 0) {
                // 浓烟尾迹
                particlesRef.current.push({
                    id: Math.random().toString(),
                    pos: { x: proj.pos.x, y: proj.pos.y },
                    vel: { x: -proj.vel.x * 0.1, y: -proj.vel.y * 0.1 }, // 惯性残留
                    life: 40, maxLife: 40, color: '#aaa', size: 6, gravity: 0, growth: 0.2, alphaDecay: 0.05
                });
                // 火焰中心
                particlesRef.current.push({
                    id: Math.random().toString(),
                    pos: { x: proj.pos.x, y: proj.pos.y },
                    vel: { x: -proj.vel.x * 0.5, y: -proj.vel.y * 0.5 },
                    life: 10, maxLife: 10, color: '#ff5500', size: 4, gravity: 0
                });
            }

            const target = entitiesRef.current.find(e => e.id !== proj.ownerId && !e.isDead);
            if (target) {
                const targetX = target.pos.x;
                const targetY = target.pos.y - 35; 
                const dx = targetX - proj.pos.x;
                const dy = targetY - proj.pos.y;
                const dist = Math.sqrt(dx*dx + dy*dy);

                if (dist > 10) {
                    const speed = 8; // 导弹速度
                    // 增加追踪惯性
                    proj.vel.x = (proj.vel.x * 30 + (dx / dist) * speed) / 31;
                    proj.vel.y = (proj.vel.y * 30 + (dy / dist) * speed) / 31;
                }
            }
        }

        proj.pos.x += proj.vel.x;
        proj.pos.y += proj.vel.y;

        // --- 炸弹/原子弹落地 ---
        if (proj.type === 'bomb' || proj.type === 'atom_bomb') {
            const isNuke = proj.type === 'atom_bomb';
            proj.vel.y += GRAVITY; 
            let hitGround = false;
             if (proj.pos.y >= GROUND_Y) { hitGround = true; }
             else if (proj.vel.y > 0) {
                 PLATFORMS.forEach(plat => {
                     if (proj.pos.x > plat.x && proj.pos.x < plat.x + plat.width && 
                         proj.pos.y >= plat.y && proj.pos.y <= plat.y + 20) {
                         hitGround = true;
                     }
                 });
             }

            if (hitGround) {
                proj.active = false;

                if (isNuke) {
                    // === 核爆逻辑升级 ===
                    shakeRef.current = 120; 
                    flashRef.current = 1.0; 
                    playExplodeSound();

                    // 生成蘑菇云
                    spawnMushroomCloud(proj.pos.x, proj.pos.y - 10);

                    // 冲击波伤害范围极大
                    entitiesRef.current.forEach(target => {
                         if (!target.isDead) {
                             target.health = 0;
                             target.isDead = true;
                             target.isLoser = true;
                             // 被吹飞
                             const dir = target.pos.x - proj.pos.x > 0 ? 1 : -1;
                             target.vel.x = dir * 60;
                             target.vel.y = -60;

                             if (target.id !== proj.ownerId) {
                                 const winner = entitiesRef.current.find(e => e.id === proj.ownerId);
                                 if (winner) triggerWin(winner.id);
                             } else {
                                 const enemy = entitiesRef.current.find(e => e.id !== proj.ownerId);
                                 if (enemy) triggerWin(enemy.id);
                             }
                         }
                    });

                } else {
                    shakeRef.current = 25; 
                    playExplodeSound();
                    spawnParticles(proj.pos.x, proj.pos.y, '#ff4500', 40, 15, 2); 

                    entitiesRef.current.forEach(target => {
                        if (!target.isDead) {
                            const dist = Math.sqrt(Math.pow(target.pos.x - proj.pos.x, 2) + Math.pow(target.pos.y - proj.pos.y, 2));
                            if (dist < 180) {
                                target.health -= 25; 
                                if (target.health <= 0) { target.health = 0; target.isDead = true; target.isLoser = true; }

                                const angle = Math.atan2(target.pos.y - proj.pos.y, target.pos.x - proj.pos.x);
                                target.vel.x = Math.cos(angle) * 30;
                                target.vel.y = Math.sin(angle) * 30;
                                target.stunFrames = 30;

                                if (target.isDead) {
                                    const winner = entitiesRef.current.find(e => e.id === proj.ownerId);
                                    if (winner) triggerWin(winner.id);
                                }
                            }
                        }
                    });
                }
            }
        } else {
            // === 碰撞逻辑 (子弹 & 导弹) ===
            const isMissile = proj.type === 'missile';
            if (proj.pos.x < 0 || proj.pos.x > canvas.width || proj.pos.y > canvas.height + 100 || proj.pos.y < -200) proj.active = false;

            entitiesRef.current.forEach(target => {
                if (target.id !== proj.ownerId && !target.isDead && proj.active) {
                    const hitDist = isMissile ? 50 : 30; 
                    if (Math.abs(proj.pos.x - target.pos.x) < hitDist &&
                        proj.pos.y > target.pos.y - 75 && proj.pos.y < target.pos.y + 10) {

                        proj.active = false;
                        const damage = isMissile ? 35 : 15; // 导弹伤害增加
                        target.health -= damage; 
                        target.stunFrames = isMissile ? 40 : 10;
                        shakeRef.current = isMissile ? 25 : 5;

                        isMissile ? playExplodeSound() : playHitSound();

                        // 导弹击中特效
                        if (isMissile) {
                             spawnParticles(target.pos.x, target.pos.y - 35, '#ff5500', 40, 10);
                             spawnParticles(target.pos.x, target.pos.y - 35, '#555', 20, 5);
                        } else {
                             spawnParticles(target.pos.x, target.pos.y - 35, '#ff0000', 10, 8);
                        }

                        target.vel.x += proj.vel.x * (isMissile ? 1.2 : 0.3); 
                        target.vel.y -= isMissile ? 15 : 5;

                        if (target.health <= 0) {
                            target.health = 0; 
                            target.isDead = true;
                            target.isLoser = true;
                            target.vel.x = proj.vel.x * 0.8;
                            const winner = entitiesRef.current.find(e => e.id === proj.ownerId);
                            if (winner) triggerWin(winner.id);
                        }
                    }
                }
            });
        }
    });
    projectilesRef.current = projectilesRef.current.filter(p => p.active);

    // === 3. 实体更新 ===
    entitiesRef.current.forEach(entity => {
      // 检查武器是否过期
      if (entity.heldWeapon) {
          entity.weaponDuration--;
          if (entity.weaponDuration <= 0) {
              entity.heldWeapon = null;
              spawnParticles(entity.pos.x, entity.pos.y - 40, '#888', 5, 5); // 消失特效
          }
      }

      if (gameState === GameState.VICTORY_ANIMATION && entity.isWinner) {
          entity.isAttacking = false; entity.attackFrame = 0; entity.isCrouching = false;
          const targetX = canvas.width / 2;
          const targetY = canvas.height / 3;
          entity.pos.x += (targetX - entity.pos.x) * 0.05;
          entity.pos.y += (targetY - entity.pos.y) * 0.05;
          entity.pos.y += Math.sin(frameRef.current * 0.08) * 0.8;
          entity.vel.x = 0; entity.vel.y = 0;
          if (frameRef.current % 3 === 0) spawnConfetti(canvas.width);
          return;
      }

      // 拾取武器
      if (!entity.isDead) {
          const canPickUp = !entity.heldWeapon || entity.ammo <= 0;

          if (canPickUp) {
            const itemIndex = fallingItemsRef.current.findIndex(item => {
                const dx = Math.abs(entity.pos.x - (item.pos.x + item.width/2));
                const dy = Math.abs((entity.pos.y - 35) - (item.pos.y + item.height/2));
                return dx < 50 && dy < 60;
            });

            if (itemIndex !== -1) {
                const item = fallingItemsRef.current[itemIndex];
                entity.heldWeapon = item.type;
                entity.weaponDuration = WEAPON_LIFETIME; 
                switch(item.type) {
                    case 'bomb': entity.ammo = 3; break;
                    case 'sword': entity.ammo = 8; break;
                    case 'atom_bomb': entity.ammo = 1; break; 
                    case 'missile': entity.ammo = 2; break; // 导弹只有2发
                    case 'dragon': entity.ammo = 1; break; 
                    case 'bomber': entity.ammo = 1; break; 
                    case 'pokemon': entity.ammo = 1; break; 
                }
                fallingItemsRef.current.splice(itemIndex, 1);
                playJumpSound();
                spawnParticles(entity.pos.x, entity.pos.y - 30, '#fff', 5, 5);
            }
          }
      }

      // 物理引擎
      const prevY = entity.pos.y;
      entity.vel.y += GRAVITY;

      if (!entity.isLoser && entity.stunFrames > 0) {
           entity.stunFrames--; 
           entity.vel.x *= 0.95; 
      } else if (!entity.isLoser) {
          const currentFriction = entity.isCrouching && entity.isGrounded ? 0.4 : FRICTION;
          entity.vel.x *= currentFriction;
      } else {
          entity.vel.x *= 0.99; 
      }

      entity.pos.x += entity.vel.x;
      entity.pos.y += entity.vel.y;

      // 碰撞检测
      entity.isGrounded = false;
      if (entity.pos.y >= GROUND_Y) {
          if (!entity.isLoser) {
            entity.pos.y = GROUND_Y;
            entity.vel.y = 0;
            entity.isGrounded = true;
          }
      }
      if (entity.vel.y >= 0 && !entity.isDead) {
          PLATFORMS.forEach(plat => {
              if (entity.pos.x > plat.x - 10 && entity.pos.x < plat.x + plat.width + 10) {
                  if (prevY <= plat.y && entity.pos.y >= plat.y) {
                      entity.pos.y = plat.y;
                      entity.vel.y = 0;
                      entity.isGrounded = true;
                  }
              }
          });
      }

      if (!entity.isLoser) {
        if (entity.pos.x < 10) { entity.pos.x = 10; entity.vel.x *= -0.5; }
        if (entity.pos.x > canvas.width - 10) { entity.pos.x = canvas.width - 10; entity.vel.x *= -0.5; }
      }

      if (gameState === GameState.VICTORY_ANIMATION || entity.isDead || entity.stunFrames > 0) return;

      if (entity.attackCooldown > 0) entity.attackCooldown--;
      if (entity.isAttacking) {
          entity.attackFrame++;
          if (entity.attackFrame > 15) { 
              entity.isAttacking = false;
              entity.attackFrame = 0;
          }
      }

      let moveLeft = false, moveRight = false, jump = false, crouch = false, attack = false;

      // Input P1
      if (entity.playerIndex === 0) {
        if (keysRef.current.has('KeyA')) moveLeft = true;
        if (keysRef.current.has('KeyD')) moveRight = true;
        if (keysRef.current.has('KeyW')) jump = true;
        if (keysRef.current.has('KeyS')) crouch = true;
        if (keysRef.current.has('Space')) attack = true;
      }

      // Input P2 / AI
      if (entity.playerIndex === 1) {
          if (gameMode === 'PVP') {
            if (keysRef.current.has('ArrowLeft')) moveLeft = true;
            if (keysRef.current.has('ArrowRight')) moveRight = true;
            if (keysRef.current.has('ArrowUp')) jump = true;
            if (keysRef.current.has('ArrowDown')) crouch = true;
            if (keysRef.current.has('Enter')) attack = true;
          } else {
            // AI Logic
            const p1 = entitiesRef.current.find(e => e.playerIndex === 0);
            if (p1 && !p1.isDead) {
                let targetX = p1.pos.x;
                let targetY = p1.pos.y;

                if (!entity.heldWeapon && fallingItemsRef.current.length > 0) {
                    let minDist = 9999;
                    fallingItemsRef.current.forEach(item => {
                        const d = Math.abs(item.pos.x - entity.pos.x) + Math.abs(item.pos.y - entity.pos.y);
                        if (d < minDist) {
                            minDist = d;
                            targetX = item.pos.x;
                            targetY = item.pos.y;
                        }
                    });
                }

                const distX = targetX - entity.pos.x;
                const distY = targetY - entity.pos.y; 

                if (Math.abs(distX) > 40) {
                    distX > 0 ? moveRight = true : moveLeft = true;
                } else if (!entity.heldWeapon && Math.abs(distX) < 20) {
                     distX > 0 ? moveLeft = true : moveRight = true;
                }

                if (entity.isGrounded) {
                     if (distY < -100 || (Math.random() < 0.02)) {
                         jump = true;
                     }
                }

                const absDistX = Math.abs(p1.pos.x - entity.pos.x);
                entity.facingRight = (p1.pos.x - entity.pos.x) > 0;

                // AI 攻击逻辑
                let attackRange = ATTACK_RANGE;
                if (entity.heldWeapon === 'atom_bomb') attackRange = 300; 
                if (entity.heldWeapon === 'missile') attackRange = 700; 
                if (entity.heldWeapon === 'dragon') attackRange = 400; 
                if (entity.heldWeapon === 'bomber') attackRange = 800; 
                if (entity.heldWeapon === 'pokemon') attackRange = 800;

                if (absDistX < attackRange && Math.abs(p1.pos.y - entity.pos.y) < 100) {
                    if (entity.attackCooldown === 0 && Math.random() < 0.05) attack = true;
                }
            }
          }
      }

      entity.isCrouching = crouch && entity.isGrounded;
      if (!entity.isCrouching) {
          if (moveLeft) { entity.vel.x -= MOVE_SPEED; entity.facingRight = false; }
          if (moveRight) { entity.vel.x += MOVE_SPEED; entity.facingRight = true; }
      }
      if (jump && entity.isGrounded && !entity.isCrouching) {
          entity.vel.y = JUMP_FORCE;
          playJumpSound();
      }

      // === 攻击处理 ===
      if (attack && entity.attackCooldown === 0) {
          entity.attackCooldown = ATTACK_COOLDOWN;
          entity.isAttacking = true;
          entity.attackFrame = 5;

          if (entity.heldWeapon === 'bomb') {
              entity.vel.x += entity.facingRight ? -2 : 2;
              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'bomb',
                  pos: { x: entity.pos.x, y: entity.pos.y - 60 },
                  vel: { x: entity.facingRight ? 12 : -12, y: -12 },
                  ownerId: entity.id,
                  width: 20, height: 20, active: true
              });
              entity.ammo--;
          } else if (entity.heldWeapon === 'atom_bomb') {
              entity.vel.x += entity.facingRight ? -4 : 4;
              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'atom_bomb',
                  pos: { x: entity.pos.x, y: entity.pos.y - 70 },
                  vel: { x: entity.facingRight ? 8 : -8, y: -10 },
                  ownerId: entity.id,
                  width: 30, height: 40, active: true
              });
              entity.ammo--; 
          } else if (entity.heldWeapon === 'missile') {
              playShootSound(); 
              entity.vel.x += entity.facingRight ? -10 : 10; 
              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'missile',
                  pos: { x: entity.pos.x + (entity.facingRight ? 50 : -50), y: entity.pos.y - 50 },
                  vel: { x: entity.facingRight ? 10 : -10, y: -5 }, 
                  ownerId: entity.id,
                  width: 20, height: 8, active: true
              });
              entity.ammo--; 
          } else if (entity.heldWeapon === 'dragon') {
              playDragonRoar();
              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'dragon',
                  pos: { x: entity.pos.x, y: entity.pos.y - 100 },
                  vel: { x: 0, y: 0 },
                  ownerId: entity.id,
                  width: 40, height: 40, active: true,
                  dragonState: 'enter', 
                  remainingHits: 5,
                  dragonPathProgress: 0,
                  dragonSegments: undefined
              });
              entity.ammo--;
          } else if (entity.heldWeapon === 'bomber') {
              // 呼叫轰炸机
              const startX = entity.facingRight ? -100 : canvas.width + 100;
              playShootSound(); // 使用枪声模拟无线电
              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'bomber',
                  pos: { x: startX, y: 100 }, // 高空飞行
                  vel: { x: 0, y: 0 },
                  ownerId: entity.id,
                  width: 60, height: 20, active: true,
                  bomberState: 'fly_in',
                  bombDropCount: 0
              });
              entity.ammo--;
          } else if (entity.heldWeapon === 'pokemon') {
              playJumpSound();
              // 召唤皮卡丘
              projectilesRef.current.push({
                  id: Math.random().toString(),
                  type: 'pokemon',
                  pos: { x: entity.pos.x + (entity.facingRight ? 20 : -20), y: entity.pos.y - 40 },
                  vel: { x: entity.facingRight ? 10 : -10, y: -5 },
                  ownerId: entity.id,
                  width: 20, height: 20, active: true,
                  pokemonState: 'seeking',
                  attackTimer: 0
              });
              entity.ammo--;
          } else {
              // == 近战武器 ==
              playAttackSound();

              let range = ATTACK_RANGE;
              let dmg = ATTACK_DAMAGE;
              let knockbackX = 15;
              let knockbackY = -8;
              let selfPush = 10;
              let hitEffectSize = 12;

              if (entity.heldWeapon === 'sword') {
                  range = 140; dmg = 15; knockbackX = 12; selfPush = 12; entity.attackCooldown = 20; 
              }

              entity.vel.x = entity.facingRight ? selfPush : -selfPush;

              const hitX = entity.facingRight ? entity.pos.x + range/2 : entity.pos.x - range/2;
              const hitY = entity.isCrouching ? entity.pos.y - 20 : entity.pos.y - 45;

              let hitSomething = false;

              entitiesRef.current.forEach(target => {
                  if (target !== entity && !target.isDead) {
                      const dy = (target.pos.y - 35) - hitY;
                      if (Math.abs(target.pos.x - entity.pos.x) < range && Math.abs(dy) < 60 && 
                          ((entity.facingRight && target.pos.x > entity.pos.x) || (!entity.facingRight && target.pos.x < entity.pos.x))) {

                          if (!entity.isCrouching && target.isCrouching) {
                              spawnParticles(target.pos.x, target.pos.y - 40, '#aaa', 2, 2);
                              return; 
                          }

                          target.health -= dmg;
                          hitSomething = true;

                          target.vel.x = entity.facingRight ? knockbackX : -knockbackX; 
                          target.vel.y = knockbackY; 
                          target.stunFrames = 20; 

                          shakeRef.current = Math.floor(dmg / 2);
                          spawnParticles(target.pos.x, target.pos.y - 40, target.color, hitEffectSize, 10);
                          playHitSound();

                          if (target.health <= 0) {
                              target.health = 0;
                              target.isDead = true;
                              target.isLoser = true;
                              target.vel.x = entity.facingRight ? 30 : -30;
                              target.vel.y = -20;
                              triggerWin(entity.id);
                          }
                      }
                  }
              });

              if (hitSomething && entity.heldWeapon) {
                  entity.ammo--;
              }
          }

          // 弹药耗尽检查
          if (entity.heldWeapon && entity.ammo <= 0) {
              entity.heldWeapon = null;
              spawnParticles(entity.pos.x, entity.pos.y - 40, '#888', 5, 5); 
          }
      }
    });
  };

  const draw = () => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      const shake = shakeRef.current;
      const shakeX = shake > 0 ? (Math.random() - 0.5) * shake : 0;
      const shakeY = shake > 0 ? (Math.random() - 0.5) * shake : 0;

      ctx.save();

      // Clear & Background
      ctx.fillStyle = '#0f172a';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.translate(shakeX, shakeY);

      // Draw Platforms
      ctx.fillStyle = '#334155';
      PLATFORMS.forEach(p => {
          ctx.fillRect(p.x, p.y, p.width, p.height);
          ctx.fillStyle = '#475569';
          ctx.fillRect(p.x, p.y, p.width, 5);
          ctx.fillStyle = '#334155';
      });
      // Draw Ground
      ctx.fillStyle = '#1e293b';
      ctx.fillRect(0, GROUND_Y, canvas.width, canvas.height - GROUND_Y);

      // Draw Falling Items
      fallingItemsRef.current.forEach(item => {
        if (!item.onGround) {
             ctx.fillStyle = 'rgba(0,0,0,0.3)';
             ctx.beginPath(); ctx.ellipse(item.pos.x + item.width/2, GROUND_Y, 15, 5, 0, 0, Math.PI*2); ctx.fill();
        }

        ctx.save();
        ctx.translate(item.pos.x + item.width/2, item.pos.y + item.height/2);

        if (item.type === 'bomb') {
            ctx.fillStyle = '#000'; ctx.beginPath(); ctx.arc(0,0,10,0,Math.PI*2); ctx.fill();
            ctx.strokeStyle='#fff'; ctx.beginPath(); ctx.moveTo(0,-10); ctx.lineTo(5,-15); ctx.stroke();
        } else if (item.type === 'sword') {
             ctx.fillStyle = '#cbd5e1'; ctx.beginPath(); ctx.moveTo(-2, 10); ctx.lineTo(-2, -15); ctx.lineTo(0,-20); ctx.lineTo(2,-15); ctx.lineTo(2,10); ctx.fill();
             ctx.fillStyle = '#8B4513'; ctx.fillRect(-5, 10, 10, 3);
        } else if (item.type === 'atom_bomb') {
             ctx.fillStyle = '#1e1e1e'; ctx.beginPath(); ctx.arc(0,0,12,0,Math.PI*2); ctx.fill();
             ctx.fillStyle = '#eab308'; ctx.font='12px sans-serif'; ctx.fillText('☢', -5, 4);
        } else if (item.type === 'missile') {
             ctx.fillStyle = '#15803d'; ctx.fillRect(-12, -4, 24, 8);
             ctx.fillStyle = '#dc2626'; ctx.fillRect(12, -4, 4, 8);
        } else if (item.type === 'dragon') {
             ctx.font='24px serif'; ctx.fillText('🐉', -12, 8);
        } else if (item.type === 'bomber') {
             ctx.fillStyle = '#4b5563'; ctx.fillRect(-10, -10, 20, 14); 
             ctx.fillStyle = '#ef4444'; ctx.beginPath(); ctx.arc(5,-5,3,0,Math.PI*2); ctx.fill(); 
             ctx.fillRect(5, -18, 2, 8); 
        } else if (item.type === 'pokemon') {
             // 精灵球图标
             ctx.fillStyle = 'red'; ctx.beginPath(); ctx.arc(0,0,10, Math.PI, 0); ctx.fill();
             ctx.fillStyle = 'white'; ctx.beginPath(); ctx.arc(0,0,10, 0, Math.PI); ctx.fill();
             ctx.fillStyle = 'black'; ctx.fillRect(-10, -1, 20, 2);
             ctx.fillStyle = 'white'; ctx.beginPath(); ctx.arc(0,0,3, 0, Math.PI*2); ctx.fill();
             ctx.strokeStyle = 'black'; ctx.lineWidth = 1; ctx.beginPath(); ctx.arc(0,0,3, 0, Math.PI*2); ctx.stroke();
        }
        ctx.restore();
      });

      // Draw Projectiles
      projectilesRef.current.forEach(proj => {
           if (proj.type === 'dragon' && proj.dragonSegments) {
                ctx.strokeStyle = '#fbbf24'; 
                ctx.lineWidth = 20;
                ctx.lineCap = 'round';
                ctx.lineJoin = 'round';
                ctx.beginPath();
                if (proj.dragonSegments.length > 0) {
                     ctx.moveTo(proj.dragonSegments[0].x, proj.dragonSegments[0].y);
                     for(let i=1; i<proj.dragonSegments.length; i++) {
                         ctx.lineTo(proj.dragonSegments[i].x, proj.dragonSegments[i].y);
                     }
                }
                ctx.stroke();
                ctx.fillStyle = '#ef4444'; 
                ctx.beginPath(); ctx.arc(proj.pos.x, proj.pos.y - 10, 5, 0, Math.PI*2); ctx.fill();
                return;
           }

           if (proj.type === 'pokemon') {
                if (proj.pokemonState === 'attacking') {
                    // 闪电连线 (画在宝可梦后面)
                    const target = entitiesRef.current.find(e => e.id !== proj.ownerId);
                    if (target) {
                        ctx.strokeStyle = '#ffff00';
                        ctx.lineWidth = 3;
                        ctx.beginPath();
                        ctx.moveTo(proj.pos.x, proj.pos.y);
                        // 简单的锯齿闪电
                        const midX = (proj.pos.x + target.pos.x) / 2 + (Math.random() - 0.5) * 50;
                        const midY = (proj.pos.y + (target.pos.y - 40)) / 2 + (Math.random() - 0.5) * 50;
                        ctx.lineTo(midX, midY);
                        ctx.lineTo(target.pos.x, target.pos.y - 40);
                        ctx.stroke();
                    }
                }

                ctx.save();
                ctx.translate(proj.pos.x, proj.pos.y);
                // 皮卡丘
                ctx.fillStyle = '#facc15'; ctx.beginPath(); ctx.arc(0,0,12,0,Math.PI*2); ctx.fill(); // 身体
                // 耳朵
                ctx.beginPath(); ctx.moveTo(-8, -8); ctx.lineTo(-12, -20); ctx.lineTo(-4, -10); ctx.fill();
                ctx.beginPath(); ctx.moveTo(8, -8); ctx.lineTo(12, -20); ctx.lineTo(4, -10); ctx.fill();
                ctx.fillStyle = 'black'; 
                ctx.beginPath(); ctx.moveTo(-11, -17); ctx.lineTo(-12, -20); ctx.lineTo(-9, -15); ctx.fill(); // 耳尖
                ctx.beginPath(); ctx.moveTo(11, -17); ctx.lineTo(12, -20); ctx.lineTo(9, -15); ctx.fill();
                // 脸
                ctx.fillStyle = 'black'; ctx.beginPath(); ctx.arc(-4, -2, 1.5, 0, Math.PI*2); ctx.fill();
                ctx.beginPath(); ctx.arc(4, -2, 1.5, 0, Math.PI*2); ctx.fill();
                ctx.fillStyle = 'red'; ctx.beginPath(); ctx.arc(-7, 2, 2, 0, Math.PI*2); ctx.fill();
                ctx.beginPath(); ctx.arc(7, 2, 2, 0, Math.PI*2); ctx.fill();
                ctx.restore();
                return;
           }

           ctx.save();
           ctx.translate(proj.pos.x, proj.pos.y);

           if (proj.type === 'bomb') {
               ctx.fillStyle = '#000'; ctx.beginPath(); ctx.arc(0,0,8,0,Math.PI*2); ctx.fill();
           } else if (proj.type === 'atom_bomb') {
               ctx.fillStyle = '#333'; ctx.beginPath(); ctx.arc(0,0,12,0,Math.PI*2); ctx.fill();
               ctx.fillStyle = 'yellow'; ctx.fillText('☢', -4, 4);
           } else if (proj.type === 'missile') {
               const angle = Math.atan2(proj.vel.y, proj.vel.x);
               ctx.rotate(angle);
               ctx.fillStyle = '#166534'; ctx.fillRect(-10, -4, 20, 8);
               ctx.fillStyle = '#ef4444'; ctx.fillRect(10, -4, 4, 8);
           } else if (proj.type === 'bomber') {
               ctx.fillStyle = '#1f2937'; 
               ctx.beginPath(); ctx.moveTo(20,0); ctx.lineTo(-10, -15); ctx.lineTo(-10, 15); ctx.fill();
               ctx.fillStyle = '#374151';
               ctx.fillRect(-5, -30, 10, 60);
           }

           ctx.restore();
      });

      // Draw Particles
      particlesRef.current.forEach(p => {
          ctx.fillStyle = p.color;
          const alpha = p.currentAlpha !== undefined ? p.currentAlpha : (p.life / p.maxLife);
          ctx.globalAlpha = Math.max(0, alpha);
          ctx.beginPath(); ctx.arc(p.pos.x, p.pos.y, p.size, 0, Math.PI * 2); ctx.fill();
          ctx.globalAlpha = 1.0;
      });

      // Draw Entities
      entitiesRef.current.forEach(entity => drawEntity(ctx, entity));

      // Flash
      if (flashRef.current > 0) {
          ctx.fillStyle = `rgba(255, 255, 255, ${flashRef.current})`;
          ctx.fillRect(-shakeX, -shakeY, canvas.width, canvas.height); 
      }

      ctx.restore();
  };

  const tick = () => {
    update();
    draw();
    requestRef.current = requestAnimationFrame(tick);
  };

  useEffect(() => {
    if (canvasRef.current) {
        canvasRef.current.width = window.innerWidth;
        canvasRef.current.height = window.innerHeight;
    }
    requestRef.current = requestAnimationFrame(tick);
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [gameState]);

  return (
    <canvas 
        ref={canvasRef} 
        className="block w-full h-full bg-slate-900"
    />
  );
};

export default GameCanvas;
